const n={1:{id:"1",title:"郑伯克段于鄢",source:"《左传》",paragraphs:[{text:"初，郑武公娶于申。",annotations:["初：当初，《左传》追忆往事的发语词","娶于申：状语后置句，正常语序“于申娶”，从申国娶妻","申，春秋姜姓诸侯国。"],translation:"当初，郑武公从申国娶了一位妻子。"},{text:"曰武姜。",annotations:["武姜：春秋诸侯夫人称谓，武是丈夫郑武公的谥号，姜是她娘家姓氏。"],translation:"妻子名叫武姜。"},{text:"生庄公及共叔段。",annotations:["共(gōng)叔段：共是国名，段后来逃亡共国；叔代表家中次子。"],translation:"武姜生下了郑庄公和共叔段两个儿子。"},{text:"庄公寤生，惊姜氏。",annotations:["寤(wù)：通“啎”，逆；寤生：难产，胎儿脚先出来","惊：使动用法，使……受惊。"],translation:"庄公出生时难产，脚先落地，吓坏了武姜。"},{text:"故名曰“寤生”，遂恶之。",annotations:["故：因此","恶(wù)：厌恶、憎恨","之，代词，代指郑庄公。"],translation:"因此给庄公取名叫寤生，武姜从此十分厌恶他。"},{text:"爱共叔段，欲立之。",annotations:["立之：立共叔段为郑国太子。"],translation:"武姜偏爱小儿子共叔段，想要立他做太子。"},{text:"亟请于武公，公弗许。",annotations:["亟(qì)：屡次、多次","弗：不","许：答应、准许。"],translation:"她多次向郑武公请求，武公始终没有答应。"},{text:"及庄公即位，为之请制。",annotations:["及：等到","即位：登上国君之位","为(wèi)之：替共叔段","制，险要城邑，今河南虎牢关。"],translation:"等到庄公继承君位，武姜就替共叔段请求分封制地。"},{text:"公曰：“制，岩邑也，虢叔死焉，佗邑唯命。”",annotations:["岩邑：地势险要的城池","焉：于此，在这里","佗：通“他”","唯命：唯命是从。"],translation:"庄公说：“制是险要的城邑，当年东虢国君死在那里，其他城池我全都听您安排。”"},{text:"请京，使居之，谓之京城大叔。",annotations:["京：郑国城邑","大(tài)：通“太”。"],translation:"武姜又请求京邑，庄公就让共叔段住在京邑，人们称他为京城太叔。"},{text:"祭仲曰：“都城过百雉，国之害也。”",annotations:["祭(zhài)仲：郑国大夫","雉(zhì)：城墙度量单位，长三丈高一丈为一雉。"],translation:"祭仲说：“分封城池的城墙超过三百丈，就会成为国家的祸患。”"},{text:"先王之制：大都不过参国之一；中，五之一；小，九之一。",annotations:["参：通“三”","国：国都","省略句，中等城池城墙不超过国都五分之一，小城不超九分之一。"],translation:"先王定下规矩：大城城墙不能超过国都的三分之一，中等城池不超过五分之一，小城池不超过九分之一。"},{text:"今京不度，非制也，君将不堪。",annotations:["不度：不合法度","堪：承受、忍受。"],translation:"如今京邑的城墙不合规制，违背先王制度，日后您会难以控制。"},{text:"公曰：“姜氏欲之，焉辟害？”",annotations:["焉：哪里","辟：通“避”，躲避。"],translation:"庄公说：“是我母亲想要这样，我又哪里能躲开灾祸呢？”"},{text:"对曰：“姜氏何厌之有？”",annotations:["宾语前置句，正常语序“姜氏有何厌”","厌：满足。"],translation:"祭仲回答：“姜氏哪里会有满足的时候？”"},{text:"不如早为之所，无使滋蔓。",annotations:["为之所：给他更换封地，安排去处","滋蔓：势力滋生扩张。"],translation:"不如早点给他换一块封地，不要让他的势力不断扩张。"},{text:"蔓难图也。",annotations:["图：图谋、对付、铲除。"],translation:"势力一旦扩张开来，就很难对付了。"},{text:"蔓草犹不可除，况君之宠弟乎？",annotations:["犹：尚且","况：何况。"],translation:"蔓延的野草尚且难以铲除，更何况是您受宠的弟弟呢？"},{text:"公曰：“多行不义必自毙，子姑待之。”",annotations:["自毙：自取灭亡","子：你","姑：姑且、暂且。"],translation:"庄公说：“做多了不合道义的事，一定会自取灭亡，你暂且等着看吧。”"},{text:"既而大叔命西鄙、北鄙贰于己。",annotations:["既而：不久","鄙：边境城邑","贰：两属，同时归两方管辖。"],translation:"没过多久，太叔下令西边、北边的边境城邑同时听命于自己。"},{text:"公子吕曰：“国不堪贰，君将若之何？”",annotations:["公子吕：郑国大夫，字子封","若之何：对此事该怎么办。"],translation:"公子吕说：“国家不能有双重管辖，您打算怎么处理这件事？”"},{text:"欲与大叔，臣请事之；若弗与，则请除之，无生民心。",annotations:["与：给予","事：侍奉","生民心：让百姓生出二心。"],translation:"如果您想把国家交给太叔，我请求去侍奉他；如果不想给他，就请除掉他，不要让百姓产生异心。"},{text:"公曰：“无庸，将自及。”",annotations:["无庸：不用、不必","自及：自己招来灾祸。"],translation:"庄公说：“不用动手，他自己会自取祸患。”"},{text:"大叔又收贰以为己邑，至于廪延。",annotations:["廪延：郑国边境邑名","收贰：把两属边邑完全划入自己封地。"],translation:"太叔又把两处两面依附的边邑全部吞并，领地扩张到廪延。"},{text:"子封曰：“可矣。厚将得众。”",annotations:["厚：土地广阔、势力雄厚","众：民心、百姓。"],translation:"子封说：“可以动手了，地盘扩大就能收拢百姓。”"},{text:"公曰：“不义不暱，厚将崩。”",annotations:["暱(nì)：通“昵”，亲近","崩：人心离散、溃败。"],translation:"庄公说：“他对君主不义、对兄长不亲，势力再大也终将分崩离析。”"},{text:"大叔完聚，缮甲兵，具卒乘，将袭郑。",annotations:["完聚：修整城墙、囤积粮草","缮：修缮","乘(shèng)：战车","袭：暗中偷袭，无鼓。"],translation:"太叔修整城池、储备粮草，修造铠甲兵器，备好士兵战车，准备偷袭郑国都城。"},{text:"夫人将启之。",annotations:["夫人：指武姜","启：打开城门，做内应。"],translation:"武姜准备到时打开城门接应共叔段。"},{text:"公闻其期，曰：“可矣！”",annotations:["期：偷袭都城的日期。"],translation:"庄公得知了偷袭的日子，说：“可以出兵了！”"},{text:"命子封帅车二百乘以伐京。",annotations:["帅：通“率”，率领","伐：公开出兵讨伐。"],translation:"庄公命令子封率领二百辆战车攻打京邑。"},{text:"京叛大叔段。",annotations:["叛：百姓背叛、脱离共叔段。"],translation:"京邑的百姓全都背叛了共叔段。"},{text:"段入于鄢。",annotations:["入：逃进","鄢：郑国城邑。"],translation:"共叔段逃到鄢城。"},{text:"公伐诸鄢。",annotations:["诸：“之于”合音，伐之于鄢，到鄢地讨伐他。"],translation:"庄公又追到鄢城攻打他。"},{text:"五月辛丑，大叔出奔共。",annotations:["辛丑：干支纪日","奔：有罪出逃","共(gōng)：诸侯国名。"],translation:"五月辛丑这天，共叔段出逃到共国避难。"},{text:"书曰：“郑伯克段于鄢。”",annotations:["书：《春秋》经文","克：战胜，多用于两国交战。"],translation:"《春秋》记载：“郑伯克段于鄢。”"},{text:"段不弟，故不言弟。",annotations:["弟：通“悌”，恪守为人弟的本分。"],translation:"共叔段没有遵守做弟弟的本分，所以经文不称他为弟。"},{text:"如二君，故曰克。",annotations:["两人交战如同两国国君相争，故用“克”。"],translation:"二人交战如同两个国君对抗，所以用“克”这个字。"},{text:"称郑伯，讥失教也。",annotations:["讥：讥讽、批评","失教：未尽兄长教化弟弟的责任。"],translation:"称庄公为郑伯，是讥讽他没有好好教导弟弟。"},{text:"谓之郑志。",annotations:["志：本心、本意，驱逐弟弟是庄公内心所想。"],translation:"这表明驱逐弟弟本就是庄公的心意。"},{text:"不言出奔，难之也。",annotations:["难(nàn)之：史官下笔为难，暗含责备庄公。"],translation:"经文不写共叔段出逃，是史官下笔有所顾虑，暗含对庄公的批评。"},{text:"遂寘姜氏于城颍，而誓之曰：“不及黄泉，无相见也。”",annotations:["寘(zhì)：通“置”，放逐","黄泉：地下泉水，代指坟墓，至死不见。"],translation:"庄公于是把武姜放逐到城颍，并且对她发誓：“不到死后埋入黄泉，永不相见。”"},{text:"既而悔之。",annotations:["既而：不久","悔之：对这件事感到后悔。"],translation:"没过多久，庄公就后悔了。"},{text:"颍考叔为颍谷封人，闻之，有献于公。",annotations:["封人：管理边境的官吏","有献：进献礼品。"],translation:"颍考叔是颍谷管理边疆的官员，听说这件事后，向庄公进献贡品。"},{text:"公赐之食。",annotations:["赐之食：赏赐给他食物。"],translation:"庄公赏赐给他一顿饭。"},{text:"食舍肉。",annotations:["舍：放置、留存，吃饭时把肉单独放一边。"],translation:"吃饭时，颍考叔把肉单独留了下来。"},{text:"公问之。",annotations:["之，代词，代指留肉这件事。"],translation:"庄公询问其中缘由。"},{text:"对曰：“小人有母，皆尝小人之食矣，未尝君之羹，请以遗之。”",annotations:["小人：谦称","羹：带汤汁的肉食","遗(wèi)：赠送、带给。"],translation:"他答道：“我家中有老母亲，我的粗茶淡饭她都吃过，却从没吃过您赏赐的肉羹，请允许我带回去送给她。”"},{text:"公曰：“尔有母遗，繄我独无！”",annotations:["繄(yī)：句首语气词，可是、唯独。"],translation:"庄公叹道：“你还有母亲可以孝敬，唯独我没有！”"},{text:"颍考叔曰：“敢问何谓也？”",annotations:["敢问：谦辞，冒昧请问。"],translation:"颍考叔说：“冒昧问一句，您这话是什么意思？”"},{text:"公语之故，且告之悔。",annotations:["语(yù)：告诉","故：整件事的前因后果。"],translation:"庄公把事情的原委告诉了他，还诉说自己满心后悔。"},{text:"对曰：“君何患焉！”",annotations:["患：忧虑、发愁。"],translation:"颍考叔回答：“您何必为此发愁！”"},{text:"若阙地及泉，隧而相见，其谁曰不然？",annotations:["阙(jué)：通“掘”","隧：名词作动词，挖隧道","然：指黄泉相见。"],translation:"如果挖地直到挖出泉水，在隧道里母子相见，谁能说这违背您黄泉相见的誓言？"},{text:"公从之。",annotations:["从：听从、采纳建议。"],translation:"庄公听从了他的办法。"},{text:"公入而赋：“大隧之中，其乐也融融！”",annotations:["赋：吟诵诗句","融融：和睦愉悦的样子。"],translation:"庄公走进隧道吟诗：“宽大隧道里面，母子心中和乐温暖！”"},{text:"姜出而赋：“大隧之外，其乐也泄泄！”",annotations:["泄泄(yì yì)：舒畅快活的样子。"],translation:"武姜走出隧道吟诗：“宽大隧道外面，母子心中自在欢愉！”"},{text:"遂为母子如初。",annotations:["如初：恢复从前母子和睦的样子。"],translation:"从此母子二人和好，恢复了往日的亲情。"},{text:"君子曰：颍考叔，纯孝也。",annotations:["君子：《左传》作者的评论者代称","纯孝：至孝、真正的孝子。"],translation:"史官评论说：颍考叔是至纯至孝的人。"},{text:"爱其母，施及庄公。",annotations:["施(yì)：推及、影响到。"],translation:"他敬爱自己的母亲，还把这份孝心推及、感化了庄公。"},{text:"《诗》曰：“孝子不匮，永锡尔类。”",annotations:["匮(kuì)：穷尽","锡(cì)：通“赐”","类：同类之人。"],translation:"《诗经》说：“孝子的孝心没有穷尽，永远把孝道分给同类之人。”"},{text:"其是之谓乎！",annotations:["宾语前置句，其谓是乎，大概说的就是颍考叔这类人吧。"],translation:"说的大概就是颍考叔这样的人吧！"}]},2:{id:"2",title:"齐桓公伐楚",source:"《左传》",paragraphs:[{text:"四年春，齐侯以诸侯之师侵蔡。",annotations:["四年：鲁僖公四年","齐侯：齐桓公","以：率领","师：军队","侵：无钟鼓、不宣而战叫侵。"],translation:"鲁僖公四年春天，齐桓公率领各诸侯国的军队攻打蔡国。"},{text:"蔡溃，遂伐楚。",annotations:["溃：军队溃散、战败","遂：于是，紧接着。"],translation:"蔡国军队溃败，齐桓公顺势进攻楚国。"},{text:"楚子使与师言曰：“君处北海，寡人处南海，唯是风马牛不相及也。”",annotations:["楚子：楚成王","使：派遣使者","北海、南海：泛指南北边远之地","风：雌雄相诱","不相及：互不牵扯。"],translation:"楚成王派使者来到诸侯军中说：“您住在北方，我住在南方，就算牛马雌雄相诱，也到不了对方地界，两国毫不相干。”"},{text:"不虞君之涉吾地也，何故？",annotations:["不虞：没想到","涉：渡过，这里指进入","何故：什么缘故。"],translation:"没想到您竟率军进入我国领土，这是什么原因？"},{text:"管仲对曰：“昔召康公命我先君大公曰：‘五侯九伯，女实征之，以夹辅周室。’”",annotations:["管仲：齐国国相","召康公：召公奭，周王室重臣","大公：太公姜尚","女：通“汝”，你","征：讨伐","夹辅：辅佐。"],translation:"管仲答复使者说：“从前召康公命令我们先君姜太公：天下各路诸侯，你都有权征伐，以此辅佐周王室。”"},{text:"赐我先君履，东至于海，西至于河，南至于穆陵，北至于无棣。",annotations:["履：征伐管辖范围","河：黄河","穆陵、无棣：齐国南北边界地名。"],translation:"还划定我们太公可以征伐的疆界：东到大海，西至黄河，南到穆陵，北到无棣。"},{text:"尔贡包茅不入，王祭不共，无以缩酒，寡人是征。",annotations:["尔：你","包茅：成捆青茅，祭祀滤酒用","共：通“供”，供给","缩酒：滤酒","是征：宾语前置，征是这件事。"],translation:"你们应当进贡的包茅没有进献，周王祭祀缺少供给，没有东西滤酒，我特来索取这件贡品。"},{text:"昭王南征而不复，寡人是问。",annotations:["昭王：周昭王","复：返回","相传昭王南巡溺死汉水","是问：质问这件事。"],translation:"周昭王南巡没能平安返回，我还要追问这件事。"},{text:"对曰：“贡之不入，寡君之罪也，敢不共给？”",annotations:["寡君：谦称本国君主","敢：岂敢，怎么敢。"],translation:"楚使回答：“贡品没有按时进献，是我国君主的过错，我们怎敢不供给？”"},{text:"昭王之不复，君其问诸水滨。",annotations:["其：还是","诸：之于","水滨：汉水边，暗示与楚国无关。"],translation:"至于周昭王没能返回，您还是到汉水边去问问吧。"},{text:"师进，次于陉。",annotations:["次：军队临时驻扎","陉：楚地名，险要高地。"],translation:"诸侯联军继续进军，驻扎在陉地。"},{text:"夏，楚子使屈完如师。",annotations:["屈完：楚国大夫","如：前往、到。"],translation:"夏天，楚成王派大夫屈完前往诸侯军中议和。"},{text:"师退，次于召陵。",annotations:["联军主动后撤以示诚意","召陵：楚地。"],translation:"诸侯军队向后撤退，驻扎在召陵。"},{text:"齐侯陈诸侯之师，与屈完乘而观之。",annotations:["陈：通“阵”，列阵","乘：同乘一辆战车。"],translation:"齐桓公把各路诸侯军队摆开阵列，和屈完同乘战车检阅军队。"},{text:"齐侯曰：“岂不谷是为？先君之好是继。”",annotations:["不谷：诸侯自谦之称","岂不谷是为：宾语前置，难道是为我个人？","好：友好关系。"],translation:"齐桓公说：“这次出兵哪里是为了我自己？只是为了延续先代各国之间的友好。”"},{text:"与不谷同好，如何？",annotations:["同好：互相交好，结盟。"],translation:"你们楚国和我重修旧好，怎么样？"},{text:"对曰：“君惠徼福于敝邑之社稷，辱收寡君，寡君之愿也。”",annotations:["惠：恩惠","徼（yāo）：求取","敝邑：谦称楚国","辱：谦辞，承蒙。"],translation:"屈完答道：“承蒙您施恩，为我国社稷求取福分，收容我们君主结盟，这正是我们国君的心愿。”"},{text:"齐侯曰：“以此众战，谁能御之？以此攻城，何城不克？”",annotations:["御：抵挡","克：攻克、攻下。"],translation:"齐桓公说：“凭着这样强大的军队作战，谁能抵挡？用这支军队攻城，哪座城池攻不下来？”"},{text:"对曰：“君若以德绥诸侯，谁敢不服？”",annotations:["绥：安抚、怀柔","德：仁德道义。"],translation:"屈完回答：“您如果用仁德安抚诸侯，天下诸侯谁敢不臣服？”"},{text:"君若以力，楚国方城以为城，汉水以为池，虽众，无所用之。",annotations:["方城：楚方城山","池：护城河","以力：依仗武力。"],translation:"您如果依仗武力，楚国以方城山为城墙，以汉水作护城河，您军队再多，也没有用处。"},{text:"屈完及诸侯盟。",annotations:["及：和","盟：订立盟约。"],translation:"屈完代表楚国，与各路诸侯订立盟约。"}]},3:{id:"3",title:"烛之武退秦师",source:"《左传》",paragraphs:[{text:"晋侯、秦伯围郑，以其无礼于晋，且贰于楚也。",annotations:["晋侯：晋文公","秦伯：秦穆公","以：因为","无礼于晋：状语后置，晋文公流亡过郑时郑国未以礼相待","贰于楚：同时依附晋、楚两国。"],translation:"晋文公、秦穆公联合出兵包围郑国，因为郑国曾对晋文公无礼，并且同时依附楚国。"},{text:"晋军函陵，秦军氾南。",annotations:["函陵、氾(fàn)南：郑国两处地名","省略介词“于”，晋军驻于函陵。"],translation:"晋国军队驻扎在函陵，秦国军队驻扎在氾水南面。"},{text:"佚之狐言于郑伯曰：“国危矣，若使烛之武见秦君，师必退。”",annotations:["佚(yì)之狐：郑国大夫","郑伯：郑文公","使：派遣","见：拜见。"],translation:"佚之狐对郑文公说：“国家危急了，如果派烛之武去拜见秦穆公，敌军一定退兵。”"},{text:"公从之。",annotations:["从：听从、采纳建议。"],translation:"郑文公听从了他的建议。"},{text:"辞曰：“臣之壮也，犹不如人；今老矣，无能为也已。”",annotations:["辞：推辞","壮：年轻壮年","犹：尚且","无能为：做不了什么","已：通“矣”，句末语气词。"],translation:"烛之武推辞说：“我年轻的时候，尚且比不上别人；现在年老了，更做不成什么事了。”"},{text:"公曰：“吾不能早用子，今急而求子，是寡人之过也。”",annotations:["子：您，尊称","急：国家危急","是：这","过：过错。"],translation:"郑文公说：“我没能早点重用您，如今国家危急才来求助您，这是我的过错。”"},{text:"然郑亡，子亦有不利焉。",annotations:["然：可是","焉：句末语气词。"],translation:"可是郑国一旦灭亡，对您也没有好处。"},{text:"许之。",annotations:["许：答应。"],translation:"烛之武便答应了出使。"},{text:"夜缒而出，见秦伯。",annotations:["缒(zhuì)：用绳子拴着人从城墙上放下去","夜：名词作状语，在夜里。"],translation:"夜里，烛之武顺着绳子从城墙下出城，拜见秦穆公。"},{text:"曰：“秦、晋围郑，郑既知亡矣。”",annotations:["既：已经。"],translation:"烛之武说：“秦、晋两国围攻郑国，郑国已经知道自己要灭亡了。”"},{text:"若亡郑而有益于君，敢以烦执事。",annotations:["亡：使动，使……灭亡","执事：代指秦穆公，谦敬说辞，不敢直称君主。"],translation:"如果灭掉郑国对您有好处，怎敢冒昧拿这件事劳烦您。"},{text:"越国以鄙远，君知其难也。",annotations:["鄙：名词意动，把……当作边邑","远：远方的郑国","越国：秦国要越过晋国才能占有郑国土地。"],translation:"越过别国，把远方的郑国当作秦国边境，您也知道这件事有多困难。"},{text:"焉用亡郑以陪邻？",annotations:["焉：何必","陪：增加","邻：晋国。"],translation:"何必灭掉郑国来增强邻国晋国的土地呢？"},{text:"邻之厚，君之薄也。",annotations:["厚：势力雄厚","薄：势力削弱。"],translation:"晋国实力变强，就等于秦国实力变弱。"},{text:"若舍郑以为东道主，行李之往来，共其乏困，君亦无所害。",annotations:["舍：放弃攻打","东道主：东方道路上招待过客的主人","行李：外交使者","共：通“供”，供给","乏困：缺少的物资。"],translation:"如果放弃攻打郑国，把郑国作为东方路上招待您使者的主人，秦国使者往来，郑国可以供给他们缺少的粮草物资，对您秦国也没有害处。"},{text:"且君尝为晋君赐矣，许君焦、瑕。",annotations:["尝：曾经","赐：恩惠，秦穆公曾扶持晋惠公回国即位","焦、瑕：晋国两座城池。"],translation:"况且您曾经对晋惠公有恩惠，他答应把焦、瑕两座城池送给您。"},{text:"朝济而夕设版焉。",annotations:["济：渡河回国","设版：修筑防御城墙，指立刻防备秦国。"],translation:"可他早上刚渡过黄河回国，晚上就修筑城墙防备秦国。"},{text:"君之所知也。",annotations:["之：取独，主谓之间取消句子独立性。"],translation:"这是您清清楚楚知道的事。"},{text:"夫晋，何厌之有？",annotations:["宾语前置，有何厌","厌：满足。"],translation:"晋国，哪里会有满足的时候？"},{text:"既东封郑，又欲肆其西封。",annotations:["东封郑：向东把郑国划为边境","封：疆界","肆：扩张","西封：西边的疆土。"],translation:"等晋国向东把郑国划为边境，下一步一定会向西扩张边界。"},{text:"若不阙秦，将焉取之？",annotations:["阙(quē)：侵损、削减","焉：从哪里。"],translation:"如果不损害秦国，晋国又能从哪里取得土地？"},{text:"阙秦以利晋，唯君图之。",annotations:["利：使……获利","唯：希望","图：考虑、权衡。"],translation:"损害秦国来让晋国得利，希望您仔细权衡这件事。"},{text:"秦伯说，与郑人盟。",annotations:["说：通“悦”，高兴","盟：订立盟约。"],translation:"秦穆公十分高兴，和郑国订立了盟约。"},{text:"使杞子、逢孙、杨孙戍之，乃还。",annotations:["戍(shù)：驻守","还：撤军回国。"],translation:"派杞子、逢孙、杨孙帮郑国守城，秦国军队就撤兵回国了。"},{text:"子犯请击之。",annotations:["子犯：晋国大夫狐偃","之：指代秦军。"],translation:"晋国大夫子犯请求出兵攻打秦军。"},{text:"公曰：“不可。”",annotations:[],translation:"晋文公说：“不行。”"},{text:"微夫人之力不及此。",annotations:["微：如果没有","夫人：那个人，指秦穆公","不及此：到不了今天的地位。"],translation:"如果没有秦穆公的帮助，我到不了今天这个位置。"},{text:"因人之力而敝之，不仁。",annotations:["因：依靠","敝：损害","仁：仁义。"],translation:"依靠过别人的力量，现在反而去伤害他，是不仁义的。"},{text:"失其所与，不知。",annotations:["与：同盟者","知：通“智”，明智。"],translation:"失去自己的同盟国，是不明智的。"},{text:"以乱易整，不武。",annotations:["乱：互相攻打","整：两军协同和睦","武：武德。"],translation:"用互相攻伐的混乱局面，代替协同一致的和睦，不符合武德。"},{text:"吾其还也。",annotations:["其：表商量语气，还是。"],translation:"我们还是撤军回去吧。"},{text:"亦去之。",annotations:["去：撤离、离开郑国。"],translation:"晋国军队也撤离了郑国。"}]},4:{id:"4",title:"吕相绝秦",source:"《左传》",paragraphs:[{text:"晋侯使吕相绝秦，曰：“昔逮我献公及穆公相好，戮力同心，申之以盟誓，重之以昏姻。",annotations:["晋侯：晋厉公","吕相：魏锜之子魏相，又称吕宣子","绝秦：与秦国断绝外交关系","逮：自从","献公：晋献公","穆公：秦穆公","戮力：合力","申：申明","昏：通“婚”。"],translation:"晋厉公派遣吕相出使秦国，宣告与秦国断交，说：“自从我国晋献公与秦穆公两国交好，同心协力，用盟誓巩固情谊，又用婚姻加深两国关系。"},{text:"天祸晋国，文公如齐，惠公如秦。",annotations:["天祸：天降灾祸","文公：晋文公重耳","惠公：晋惠公夷吾","如：前往、流亡。"],translation:"上天降下灾祸给晋国，晋文公流亡到齐国，晋惠公流亡到秦国。"},{text:"无禄，献公即世。",annotations:["无禄：不幸，古人遭遇丧事常用","即世：去世。"],translation:"不幸，晋献公离世。"},{text:"穆公不忘旧德，俾我惠公用能奉祀于晋。",annotations:["俾(bǐ)：使","奉祀：主持宗庙祭祀，指回国即位做国君。"],translation:"秦穆公不忘往日恩情，让晋惠公能够回到晋国主持宗庙祭祀、登上君位。"},{text:"又不能成大勋，而为韩之师。",annotations:["勋：功业","韩之师：韩原之战，秦晋交战，惠公战败被俘。"],translation:"可惠公没能成就秦国的大恩，反而与秦国在韩原开战。"},{text:"亦悔于厥心，用集我文公，是穆之成也。",annotations:["厥：他的","集：安定、扶持","成：成全、恩德。"],translation:"惠公后来内心也十分悔恨，秦国又扶持晋文公回国安定国家，这是秦穆公的恩德。"},{text:"穆公躬裒甲兵，冯陵我城郜，芟夷我农功，虔刘我边垂。",annotations:["躬：亲自","裒(póu)：调集","冯(píng)陵：侵犯","城郜：晋国城邑","芟(shān)夷：收割毁坏","农功：庄稼","虔刘：杀害","垂：通“陲”，边境。"],translation:"可秦穆公亲自调集军队，侵犯我国城郜，毁坏田里庄稼，杀害我国边境百姓。"},{text:"我文公帅诸侯之师以东之邘、略、粱、曲沃，君之仇也。",annotations:["帅：通“率”","邘、略、粱、曲沃：秦国东部城邑","君之仇：这些是秦国敌对势力的封地。"],translation:"晋文公率领诸侯军队向东攻打邘、略、粱、曲沃，这些都是秦国仇敌占据的地方。"},{text:"文公即世，穆为不吊，蔑死我君，寡我襄公，迭我殽地，奸绝我好，伐我保城，殄灭我费滑，散离我兄弟，挠乱我同盟，倾覆我国家。",annotations:["不吊：不体恤死者","蔑：轻视","寡：轻视、欺负","迭：突袭","殽(xiáo)：殽山","保城：边境小城","殄(tiǎn)：尽灭","费滑：滑国，晋国同姓盟国","挠乱：扰乱。"],translation:"晋文公去世，秦穆公毫无体恤之心，轻视逝去的君主，欺辱新即位的晋襄公，突袭我国殽山之地，断绝两国友好，攻打我国边城，灭掉同姓盟国滑国，离间晋国同姓诸侯，扰乱诸侯同盟，企图颠覆晋国。"},{text:"我襄公未忘君之旧勋，而惧社稷之陨，是以有殽之师。",annotations:["陨：灭亡","殽之师：殽之战，晋国伏击秦军。"],translation:"晋襄公没有忘记秦穆公从前的恩德，只是惧怕国家灭亡，因此才爆发殽山之战。"},{text:"犹愿赦罪于穆公。",annotations:["赦罪：请求秦国谅解，缓和矛盾。"],translation:"我们依旧希望秦穆公能谅解晋国。"},{text:"穆公弗听，而即楚谋我。",annotations:["即：亲近、联合","谋：算计、攻打。"],translation:"秦穆公不肯听，反而联合楚国图谋攻打晋国。"},{text:"天诱其衷，成王陨命，穆公是以不克逞志于我。",annotations:["天诱其衷：上天开导人心，指天意","成王：楚成王","陨命：被杀","克：能够","逞志：实现野心。"],translation:"上天自有安排，楚成王被杀，秦穆公联合楚国算计晋国的阴谋没能得逞。"},{text:"穆、襄即世，康、灵即位。",annotations:["康：秦康公","灵：晋灵公","即世：去世。"],translation:"秦穆公、晋襄公先后去世，秦康公、晋灵公即位。"},{text:"康公，我之自出，又欲阙翦我公室，倾覆我社稷，帅我蝥贼，以来荡摇我边疆。",annotations:["我之自出：秦康公母亲是晋献公之女，出身晋国","阙翦：损害削弱","蝥(máo)贼：害虫，比喻晋国叛臣","荡摇：扰乱侵扰。"],translation:"秦康公母亲是晋国女子，本与我们有亲缘，可他却想削弱晋国公族、颠覆晋国，收留我国叛贼，侵扰我国边境。"},{text:"我是以有令狐之役。",annotations:["令狐之役：秦晋令狐交战。"],translation:"因此晋秦爆发令狐之战。"},{text:"康犹不悛，入我河曲，伐我涑川，俘我王官，翦我羁马。",annotations:["悛(quān)：悔改","河曲、涑川、王官、羁马：晋国城邑","翦：掠夺。"],translation:"秦康公仍旧不知悔改，攻入河曲，攻打涑川，掳掠王官百姓，劫掠羁马之地。"},{text:"秦大失诸侯之望，诸侯皆贰，是秦无成也。",annotations:["望：期望","贰：怀有二心，背离秦国","成：恩德、信义。"],translation:"秦国彻底失去诸侯信任，各国诸侯都背离秦国，这都是秦国不讲信义造成的。"},{text:"桓、灵即世，悼、厉即位。",annotations:["桓：秦桓公","灵：晋灵公","悼：晋悼公","厉：晋厉公。"],translation:"秦桓公、晋灵公去世，晋悼公、晋厉公先后即位。"},{text:"桓公是不逞，造于弊邑之疆场。",annotations:["不逞：心怀歹念","疆场(yì)：边境。"],translation:"秦桓公心怀恶意，带兵来到我国边境挑衅。"},{text:"寡人率诸侯以待之，秦师无返。",annotations:["寡人：晋厉公自称","待：抵御","无返：秦军战败溃逃。"],translation:"我率领诸侯军队抵御秦军，秦军大败而逃。"},{text:"秦桓公归，不克逞志，又诱我狄人，离间诸侯。",annotations:["克：能够","诱：引诱勾结","狄人：北方少数民族。"],translation:"秦桓公回国后，野心没能实现，又勾结狄人，挑拨诸侯各国关系。"},{text:"天诛加焉，狄人离叛，桓公是以不克逞志于我。",annotations:["天诛：上天惩罚","离叛：背离秦国。"],translation:"上天降下惩罚，狄人背弃秦国，秦桓公算计晋国的计谋再次落空。"},{text:"今君嗣桓之位，而无桓之德；待诸侯之好，而有贪利之心。",annotations:["嗣：继承","君：指当时秦桓公之子秦景公","德：信义德行。"],translation:"如今您继承秦桓公的君位，却没有桓公仅存的一点信义；本应善待诸侯，内心却充满贪利之心。"},{text:"诸侯备闻此言，斯是用痛心疾首，昵就寡人。",annotations:["备：全部","斯是用：因此","痛心疾首：极度怨恨","昵就：亲近归附。"],translation:"各国诸侯全都听闻秦国所作所为，因此内心痛恨秦国，全都亲近归附晋国。"},{text:"寡人帅之以听命，唯好是求。",annotations:["宾语前置，唯求好","听命：前来与秦国交涉","好：友好盟约。"],translation:"我率领诸侯前来听候秦国答复，只求恢复往日友好。"},{text:"君若惠顾诸侯，矜哀寡人，而赐之盟，则寡人之愿也。",annotations:["惠顾：体恤","矜哀：怜悯","赐之盟：与诸侯订立盟约。"],translation:"如果您体恤各国诸侯、怜悯我，愿意订立盟约，这便是我的心愿。"},{text:"其承宁诸侯以退，岂敢徼乱？",annotations:["承宁：安定","徼(yāo)：求取、挑起。"],translation:"我会安抚诸侯撤军，怎敢主动挑起战乱？"},{text:"君若不施大惠，寡人不佞，其不能以诸侯退矣。",annotations:["不佞：谦辞，不才","其：将。"],translation:"如果您不肯施以恩惠，我不才，就无法劝说诸侯退兵。"},{text:"敢尽布之执事，俾执事实图利之。”",annotations:["布：陈述","执事：敬称，代指秦国君主","俾：使","图利：权衡利弊。"],translation:'我冒昧把全部实情告知您，请您仔细权衡利弊。"'},{text:"使吕相绝秦。",annotations:["省略主语晋厉公","使：派遣。"],translation:"于是派遣吕相出使秦国，宣告两国断绝外交关系。"}]},5:{id:"5",title:"勾践灭吴",source:"《国语》",paragraphs:[{text:"越王勾践栖于会稽之上，乃号令于三军曰：“凡我父兄昆弟及国子姓，有能助寡人谋而退吴者，吾与之共知越国之政。”",annotations:["栖：退守、驻扎","会稽：山名","昆弟：兄弟","国子姓：国内百姓","知：主持、共管。"],translation:"越王勾践退守在会稽山上，向全军传令：凡是我父辈、兄弟以及国内百姓，有能帮我谋划击退吴国的人，我就和他一同掌管越国政事。"},{text:"大夫种进对曰：“臣闻之，贾人夏则资皮，冬则资絺，旱则资舟，水则资车，以待乏也。”",annotations:["种：文种","贾(gǔ)人：商人","资：储备","絺(chī)：细葛布","待乏：以备缺用时取用。"],translation:"大夫文种上前回答说：我听说，商人夏天储备皮货，冬天储备细葛布，天旱储备船只，雨季储备车辆，用来等待物资缺乏时卖出。"},{text:"夫虽无四方之忧，然谋臣与爪牙之士，不可不养而择也。",annotations:["四方之忧：外敌入侵的忧患","爪牙之士：勇猛将士","养：培养。"],translation:"就算没有外敌入侵的忧患，谋臣与猛将，也不能不提前培养、挑选。"},{text:"譬如蓑笠，时雨既至，必求之。",annotations:["蓑笠：蓑衣斗笠","既至：到来。"],translation:"就好比蓑衣斗笠，大雨来临的时候，一定需要它们。"},{text:"今君王既栖于会稽之上，然后乃求谋臣，无乃后乎？",annotations:["无乃……乎：固定句式，恐怕……吧","后：太迟、滞后。"],translation:"如今大王退守会稽山，才来寻求谋臣，恐怕太晚了吧？"},{text:"勾践曰：“苟得闻子大夫之言，何后之有？”",annotations:["苟：如果","何后之有：宾语前置，有何后。"],translation:"勾践说：如果能听到大夫您的这番话，又有什么晚的？"},{text:"执其手而与之谋。",annotations:["执：握住","谋：商议对策。"],translation:"勾践握住文种的手，和他一同谋划对策。"},{text:"遂使之行成于吴。",annotations:["遂：于是","行成：求和、议和。"],translation:"于是派文种前往吴国求和。"},{text:"吴王夫差将欲听与之成。",annotations:["听：听从","成：停战结盟。"],translation:"吴王夫差打算听从文种，和越国议和。"},{text:"子胥谏曰：“不可！夫吴之与越也，仇雠敌战之国也；三江环之，民无所移。”",annotations:["子胥：伍子胥","仇雠(chóu)：仇敌","三江：长江、钱塘江、浦阳江","环：环绕。"],translation:"伍子胥劝谏吴王说：不行！吴国和越国，是世代敌对、互相攻伐的国家；三条江水环绕两国，百姓没有别处迁移。"},{text:"有吴则无越，有越则无吴，将不可改于是矣。",annotations:["于是：这种局面。"],translation:"有吴国就不能存在越国，有越国就容不下吴国，这种局面无法改变。"},{text:"员闻之：陆人居陆，水人居水。",annotations:["员：伍子胥自称","居：适应、安居。"],translation:"我听说：陆地百姓习惯住在陆地，水乡百姓习惯住在水边。"},{text:"夫上党之国，我攻而胜之，吾不能居其地，不能乘其车；夫越国，吾攻而胜之，吾能居其地，吾能乘其舟。",annotations:["上党之国：中原内陆诸侯国","乘：乘坐。"],translation:"那些中原内陆国家，就算我们战胜它们，我们也不能住在他们的土地，不会乘坐他们的车辆；而越国，我们打赢之后，可以住在这片土地，乘坐他们的船只。"},{text:"此其利也，不可失也已，君必灭之。",annotations:["利：有利之处","失：错失时机。"],translation:"这是攻打越国的有利之处，千万不能错失，大王一定要灭掉越国。"},{text:"失此利也，虽悔之，必无及已。",annotations:["无及：来不及。"],translation:"放过这次有利机会，日后就算后悔，也一定来不及了。"},{text:"越人饰美女八人，纳之太宰嚭，曰：“子苟赦越国之罪，又有美于此者将进之。”",annotations:["饰：装扮","纳：进献","嚭(pǐ)：吴国太宰伯嚭","苟：假如。"],translation:"越国挑选打扮八位美女，进献给太宰伯嚭，说：您如果饶恕越国的罪过，还有比这些更美的女子会献给您。"},{text:"太宰嚭谏曰：“嚭闻古之伐国者，服之而已；今已服矣，又何求焉？”",annotations:["服之：使对方臣服","而已：罢了。"],translation:"太宰伯嚭劝谏吴王说：我听说古代讨伐别国，只是让对方臣服就够了；如今越国已经臣服，还苛求什么呢？"},{text:"夫差与之成而去之。",annotations:["去之：撤兵离开越国。"],translation:"夫差便和越国订立和约，撤兵离去。"},{text:"勾践说于国人曰：“寡人不知其力之不足也，而又与大国执仇，以暴露百姓之骨于中原，此则寡人之罪也。”",annotations:["说：向百姓解释","执仇：结下仇怨","中原：野外。"],translation:"勾践向全国百姓宣告：我自知国力不足，却和强大吴国结下仇怨，致使百姓尸骨暴露在荒野，这都是我的过错。"},{text:"寡人请更。",annotations:["更：改正过失，改变国策。"],translation:"我请求改正所有过错。"},{text:"于是葬死者，问伤者，养生者；吊有忧，贺有喜；送往者，迎来者；去民之所恶，补民之不足。",annotations:["吊：慰问","恶(wù)：厌恶、反感的事。"],translation:"于是安葬战死的人，慰问受伤的人，抚养活着的百姓；慰问有丧事的家庭，祝贺有喜事的人家；欢送远行的人，迎接归来的人；去掉百姓厌恶的政令，补足百姓缺少的物资。"},{text:"然后卑事夫差，宦士三百人于吴，其身亲为夫差前马。",annotations:["卑事：放下身份侍奉","宦士：派士人做奴仆","前马：马前开道的侍从。"],translation:"之后放下身段侍奉夫差，派三百士人到吴国做奴仆，勾践自己亲自做夫差马前引路的侍从。"},{text:"勾践之地，南至于句无，北至于御儿，东至于鄞，西至于姑蔑，广运百里。",annotations:["句(gōu)无、御儿、鄞(yín)、姑蔑：越国四方边界地名","广运：方圆。"],translation:"勾践的国土，南到句无，北到御儿，东到鄞地，西到姑蔑，方圆百里。"},{text:"乃致其父母昆弟而誓之，曰：“寡人闻，古之贤君，四方之民归之，若水之归下也。”",annotations:["致：召集","归：归附","下：低处。"],translation:"勾践召集国内父老兄弟，对他们立誓：我听说古代贤明君主，天下百姓归附他，就像水流向低处一样自然。"},{text:"今寡人不能，将帅二三子夫妇以蕃。",annotations:["二三子：各位百姓","蕃：繁衍人口。"],translation:"如今我做不到，我将带领大家繁育人口。"},{text:"令壮者无取老妇，令老者无取壮妻；女子十七不嫁，其父母有罪；丈夫二十不取，其父母有罪。",annotations:["取：通“娶”","丈夫：男子。"],translation:"下令壮年男子不能娶年老妇人，老年男子不能娶年轻女子；女子十七岁不出嫁，她父母要治罪；男子二十岁不娶妻，父母也要治罪。"},{text:"将免者以告，公令医守之。",annotations:["免：通“娩”，分娩","守：看护接生。"],translation:"妇女将要分娩必须上报，官府派医生看护接生。"},{text:"生丈夫，二壶酒，一犬；生女子，二壶酒，一豚；生三人，公与之母；生二人，公与之饩。",annotations:["豚：小猪","母：乳母","饩(xì)：粮食口粮。"],translation:"生男孩，赏两壶酒、一条狗；生女孩，赏两壶酒、一头小猪；一胎生三个，官府配乳母；一胎生两个，官府供给粮食。"},{text:"当室者死，三年释其政；支子死，三月释其政；必哭泣葬埋之如其子。",annotations:["当室者：嫡长子","释其政：免除徭役","支子：庶子。"],translation:"嫡长子去世，免除他家三年徭役；庶子去世，免除他家三月徭役；勾践一定亲自哭吊安葬，如同对待自己儿子。"},{text:"令孤子、寡妇、疾疹、贫病者，纳宦其子。",annotations:["疾疹(chèn)：患病之人","纳宦其子：官府收养他们的子女。"],translation:"下令孤儿、寡妇、患病、贫苦人家，他们的子女由官府供养。"},{text:"其达士，洁其居，美其服，饱其食，而摩厉之于义。",annotations:["达士：贤能之士","洁、美、饱：使动","摩厉：磨砺、切磋。"],translation:"对于国内贤才，打扫干净他们住所，给华美的衣服，充足食物，和他们切磋道义、治国之道。"},{text:"四方之士来者，必庙礼之。",annotations:["庙礼：在庙堂之上以礼接待。"],translation:"各国前来投奔的贤士，一定在庙堂以隆重礼节接待。"},{text:"勾践载稻与脂于舟以行，国之孺子之游者，无不餔也，无不歠也，必问其名。",annotations:["脂：油","孺子：年轻人","餔(bū)：喂食","歠(chuò)：给水喝。"],translation:"勾践乘船出行，船上装载粮食油肉，遇见外出游学的年轻人，没有不供给吃喝的，一定记下他们姓名。"},{text:"非其身之所种则不食，非其夫人之所织则不衣。",annotations:["衣(yì)：穿衣服。"],translation:"不是自己亲手耕种的粮食就不吃，不是夫人亲手织的布就不穿。"},{text:"十年不收于国，民俱有三年之食。",annotations:["不收于国：不向百姓征收赋税。"],translation:"十年间不向百姓征税，百姓家家都储备够吃三年的粮食。"},{text:"国之父兄请曰：“昔者夫差耻吾君于诸侯之国，今越国亦节矣，请报之。”",annotations:["耻：使动，使……受羞辱","节：积蓄充足","报：报仇。"],translation:"国内父老乡亲请求勾践：从前夫差让我们国君在诸侯面前蒙受羞辱，如今越国积蓄充足，请允许我们报仇。"},{text:"勾践辞曰：“昔者之战也，非二三子之罪也，寡人之罪也。”",annotations:["辞：推辞拒绝。"],translation:"勾践推辞说：当年战败，不是各位百姓的过错，全是我的过错。"},{text:"如寡人者，安与知耻？请姑无庸战。",annotations:["安：哪里","姑：暂且","无庸：不用。"],translation:"像我这样的人，哪里配谈雪耻？请大家暂且不要作战。"},{text:"父兄又请曰：“越四封之内，亲吾君也，犹父母也。子而思报父母之仇，臣而思报君之仇，其有敢不尽力者乎？请复战。”",annotations:["四封：四方边境","犹：如同","其：难道。"],translation:"父老再次请求：越国全境百姓爱戴大王，如同爱戴父母。子女想报父母之仇，臣子想报君主之仇，哪有不肯拼尽全力的？请准许再次开战。"},{text:"勾践既许之，乃致其众而誓之。",annotations:["许：答应","致：召集。"],translation:"勾践终于答应众人，召集全体百姓立誓。"},{text:"曰：“寡人闻古之贤君，不患其众之不足也，而患其志行之少耻也。”",annotations:["患：担忧","少耻：缺少羞耻之心。"],translation:"勾践说：我听说古代贤明君主，不担忧百姓数量不足，只担忧百姓缺少知耻之心。"},{text:"今夫差衣水犀之甲者亿有三千，不患其志行之少耻也，而患其众之不足也。",annotations:["水犀之甲：水犀牛皮铠甲","亿有三千：上万兵士。"],translation:"如今夫差手下身披犀牛皮铠甲的士兵上万，他不担忧士兵缺少羞耻道义，只担忧兵力不够多。"},{text:"今寡人将助天灭之。",annotations:["助天：顺应天意。"],translation:"如今我将顺应天意灭掉吴国。"},{text:"吾不欲匹夫之勇也，欲其旅进旅退。",annotations:["匹夫之勇：个人莽撞蛮干","旅进旅退：一同前进、一同后退，统一行动。"],translation:"我不想要个人逞匹夫之勇，希望大家进退行动整齐统一。"},{text:"进则思赏，退则思刑；如此，则有常赏。",annotations:["刑：惩罚","常赏：固定合理奖赏制度。"],translation:"前进时想着立功受赏，后退时谨记军法惩罚；这样，国家才有规范的奖惩。"},{text:"进不用命，退则无耻；如此，则有常刑。",annotations:["不用命：不服从军令","常刑：固定军法。"],translation:"进攻不听从号令，退却不知羞耻；这样就要按军法处置。"},{text:"果行，国人皆劝。父勉其子，兄勉其弟，妇勉其夫，曰：“孰是君也，而可无死乎？”",annotations:["果行：正式出兵","劝：互相勉励","孰：谁。"],translation:"军队正式出征，百姓全都互相勉励。父亲勉励儿子，兄长勉励弟弟，妻子勉励丈夫，说：谁能像我们这样体恤百姓的君主，我们怎能不为他拼死作战？"},{text:"是故败吴于囿，又败之于没，又郊败之。",annotations:["囿、没：吴国地名","郊：吴国都城郊外。"],translation:"因此越军先在囿地击败吴军，又在没地大败吴军，最后直逼吴国都城郊外，再次击溃吴军。"},{text:"夫差行成，曰：“寡人之师徒不足以辱君矣，请以金玉子女赂君之辱。”",annotations:["行成：求和","师徒：军队","赂：奉献。"],translation:"夫差派人求和，说：我的军队已经不值得大王亲自讨伐，请允许我献上金玉美女，赔罪求和。"},{text:"勾践对曰：“昔天以越予吴，而吴不受命；今天以吴予越，越可以无听天之命，而听君之令乎？”",annotations:["予：给予","受命：接受天命。"],translation:"勾践答复：从前上天把越国送给吴国，吴国不接受；如今上天把吴国送给越国，我怎能不听从天命，反而听从您的命令？"},{text:"吾请达王甬、句东，吾与君为二君乎。",annotations:["达：遣送","甬、句东：海岛，打算流放夫差。"],translation:"我打算把您送到甬江、句章东边的海岛，让你我两国依旧像两位君主共处。"},{text:"夫差对曰：“寡人礼先壹饭矣，君若不忘周室而为弊邑宸宇，亦寡人之愿也。”",annotations:["礼先壹饭：早年对越王有恩惠","宸宇：屋檐，指庇护吴国。"],translation:"夫差说：从前我曾对您有恩德，大王如果看在周王室份上，庇护吴国，是我最大心愿。"},{text:"君若曰：‘吾将残汝社稷，灭汝宗庙。’寡人请死，余何面目以视于天下乎！”",annotations:["残：摧毁","社稷、宗庙：代指国家","视：见人。"],translation:"大王如果说：我要摧毁你的国家、断绝你的宗庙祭祀，那我只求一死，我还有什么脸面见天下诸侯！"},{text:"遂自杀。",annotations:["遂：于是。"],translation:"夫差随后自尽身亡。"},{text:"勾践灭吴。",annotations:["灭：彻底征服吴国。"],translation:"勾践最终灭掉吴国。"}]},6:{id:"6",title:"邹忌讽齐王纳谏",source:"《战国策》",paragraphs:[{text:"邹忌修八尺有余，而形貌昳丽。",annotations:["修：长，指身高","昳(yì)丽：光艳美丽。"],translation:"邹忌身高八尺多，容貌光艳好看。"},{text:"朝服衣冠，窥镜，谓其妻曰：“我孰与城北徐公美？”",annotations:["朝(zhāo)：早晨","服：名词作动词，穿戴","窥：照","孰与：固定句式，和……相比谁更……。"],translation:"早晨他穿戴好衣帽，照着镜子，对他妻子说：“我和城北徐公相比，谁更美？”"},{text:"其妻曰：“君美甚，徐公何能及君也？”",annotations:["甚：极、非常","及：比得上。"],translation:"他妻子说：“您美极了，徐公哪里能比得上您呢？”"},{text:"城北徐公，齐国之美丽者也。",annotations:["判断句，“……者也”表判断。"],translation:"城北的徐公，是齐国的美男子。"},{text:"忌不自信，而复问其妾曰：“吾孰与徐公美？”",annotations:["不自信：宾语前置，不信自，不相信自己（比徐公美）","复：又。"],translation:"邹忌不相信自己比徐公好看，又问他的侍妾：“我和徐公谁更美？”"},{text:"妾曰：“徐公何能及君也？”",annotations:["何能：怎么能。"],translation:"侍妾说：“徐公哪里比得上您呀？”"},{text:"旦日，客从外来，与坐谈，问之客曰：“吾与徐公孰美？”",annotations:["旦日：第二天","与坐谈：省略宾语，与之坐谈。"],translation:"第二天，有客人从外边来，邹忌和他坐着谈话，向客人问道：“我和徐公谁更美？”"},{text:"客曰：“徐公不若君之美也。”",annotations:["不若：不如，比不上。"],translation:"客人说：“徐公比不上您好看。”"},{text:"明日徐公来，孰视之，自以为不如。",annotations:["明日：又过了一天","孰：通“熟”，仔细。"],translation:"又过了一天，徐公前来拜访，邹忌仔细端详他，自己觉得比不上徐公。"},{text:"窥镜而自视，又弗如远甚。",annotations:["弗如：不如","远甚：差得很远。"],translation:"再照镜子看看自己，更是觉得远远比不上人家。"},{text:"暮寝而思之，曰：“吾妻之美我者，私我也；妾之美我者，畏我也；客之美我者，欲有求于我也。”",annotations:["寝：躺下","美：意动用法，以……为美","私：偏爱","畏：害怕","有求于我：状语后置，对我有所求。"],translation:"夜里躺在床上思考这件事，心想：我的妻子认为我美，是偏爱我；侍妾说我美，是惧怕我；客人夸我美，是有事情想求我帮忙。"},{text:"于是入朝见威王，曰：“臣诚知不如徐公美。",annotations:["诚：确实、实在","威王：齐威王。"],translation:"于是邹忌上朝拜见齐威王，说：我确实知道自己比不上徐公好看。"},{text:"臣之妻私臣，臣之妾畏臣，臣之客欲有求于臣，皆以美于徐公。",annotations:["以：认为","美于徐公：状语后置，比徐公美。"],translation:"我的妻子偏爱我，我的侍妾惧怕我，我的客人有求于我，全都认为我比徐公美。"},{text:"今齐地方千里，百二十城，宫妇左右莫不私王，朝廷之臣莫不畏王，四境之内莫不有求于王：由此观之，王之蔽甚矣。”",annotations:["地方：土地方圆","左右：君主身边近臣","蔽：受蒙蔽","甚：严重。"],translation:"如今齐国国土方圆千里，一百二十座城池，宫中姬妾、身边近臣没有不偏爱大王的，朝中大臣没有不惧怕大王的，全国百姓没有不有求于大王的：从这点来看，大王您受到的蒙蔽太严重了。"},{text:"王曰：“善。”",annotations:["善：说得好，表示赞同。"],translation:"齐威王说：“说得好。”"},{text:"乃下令：“群臣吏民能面刺寡人之过者，受上赏；上书谏寡人者，受中赏；能谤讥于市朝，闻寡人之耳者，受下赏。”",annotations:["面刺：当面指责","过：过错","谤讥：议论、批评（无贬义）","市朝：公共场合","闻：使动，使……听到。"],translation:"随即下达命令：大小官吏、百姓，能够当面指责我过失的，受上等赏赐；上书劝谏我的，受中等赏赐；能在公共场所议论我的过失，传到我耳朵里的，受下等赏赐。"},{text:"令初下，群臣进谏，门庭若市。",annotations:["初：刚","门庭若市：门前庭院像集市一样热闹。"],translation:"命令刚下达时，百官纷纷进言劝谏，王宫门前热闹得如同集市。"},{text:"数月之后，时时而间进。",annotations:["时时：偶尔","间(jiàn)：间或、偶然","进：进谏。"],translation:"过了几个月，只是偶尔有人来进谏。"},{text:"期年之后，虽欲言，无可进者。",annotations:["期(jī)年：满一年","无可进：没有可以劝谏的过失。"],translation:"满一年之后，就算有人想提意见，也没有可说的过失了。"},{text:"燕、赵、韩、魏闻之，皆朝于齐。",annotations:["朝(cháo)：朝拜、臣服","朝于齐：状语后置，到齐国朝拜。"],translation:"燕、赵、韩、魏各国听说这件事后，都到齐国来朝拜称臣。"},{text:"此所谓战胜于朝廷。",annotations:["战胜于朝廷：状语后置，在朝堂之上战胜别国，指内政修明不需用兵。"],translation:"这就是人们所说的，不必出兵，在朝堂之内就能战胜敌国。"}]},7:{id:"7",title:"触龙说赵太后",source:"《战国策》",paragraphs:[{text:"赵太后新用事，秦急攻之。",annotations:["新用事：刚掌权","赵太后：赵孝成王之母","急攻：加紧攻打。"],translation:"赵太后刚刚执掌赵国政权，秦国就加紧进攻赵国。"},{text:"赵氏求救于齐。",annotations:["状语后置，向齐国求救。"],translation:"赵国向齐国求救。"},{text:"齐曰：“必以长安君为质，兵乃出。”",annotations:["长安君：太后小儿子","质：人质","乃：才。"],translation:"齐国说：一定要把长安君送来做人质，我们才出兵。"},{text:"太后不肯，大臣强谏。",annotations:["强(qiǎng)：竭力、强行","谏：规劝君主。"],translation:"赵太后不肯答应，大臣们极力劝谏。"},{text:"太后明谓左右：“有复言令长安君为质者，老妇必唾其面。”",annotations:["明谓：明确告诉","左右：身边近臣","复言：再说","唾：吐唾沫。"],translation:"太后明确对身边侍从说：有谁再敢说让长安君去做人质，我一定往他脸上吐唾沫。"},{text:"左师触龙言愿见太后，太后盛气而揖之。",annotations:["左师：官名","盛气：怒气冲冲","揖：等候接见。"],translation:"左师触龙说希望拜见太后，太后满脸怒气等着他。"},{text:"入而徐趋，至而自谢，曰：“老臣病足，曾不能疾走，不得见久矣。”",annotations:["徐趋：小步快走（古代见君礼仪，脚有病只能慢慢走）","谢：道歉","疾走：快跑。"],translation:"触龙进门后慢慢小跑上前，到太后面前主动道歉说：老臣腿脚有毛病，不能快跑，很久没能拜见您了。"},{text:"窃自恕，而恐太后玉体之有所郄也，故愿望见太后。",annotations:["窃：私下，谦辞","玉体：尊称太后身体","郄(xì)：不舒服、病痛。"],translation:"我私下原谅自己，又担心太后贵体有什么不适，所以想来拜见您。"},{text:"太后曰：“老妇恃辇而行。”",annotations:["恃：依靠","辇(niǎn)：人拉的车子。"],translation:"太后说：我只能靠坐车行动。"},{text:"曰：“日食饮得无衰乎？”",annotations:["得无……乎：该不会……吧","衰：减少。"],translation:"触龙问：您每天饮食该不会减少吧？"},{text:"曰：“恃粥耳。”",annotations:["耳：罢了。"],translation:"太后说：只靠喝粥罢了。"},{text:"老臣今者殊不欲食，乃自强步，日三四里，少益耆食，和于身也。",annotations:["殊：特别","强步：勉强散步","耆(shì)：通“嗜”，喜爱","和：舒适。"],translation:"我近来特别不想吃东西，就自己勉强散步，每天走三四里，稍微增加一点食欲，身体才舒服些。"},{text:"太后曰：“老妇不能。”",annotations:[],translation:"太后说：我做不到。"},{text:"太后之色少解。",annotations:["色：怒气","少解：稍稍缓和。"],translation:"太后脸上的怒气稍微消了一点。"},{text:"左师公曰：“老臣贱息舒祺，最少，不肖。",annotations:["贱息：谦称自己儿子","不肖：不成才、不贤。"],translation:"触龙说：我的小儿子舒祺，年纪最小，不成器。"},{text:"而臣衰，窃爱怜之，愿令得补黑衣之数，以卫王宫，没死以闻。”",annotations:["衰：年老","怜：疼爱","黑衣：王宫卫士","没死：冒着死罪","闻：禀告。"],translation:"可我年事已高，私下十分疼爱他，希望能让他补上卫士的名额，护卫王宫，我冒着死罪把这个心愿禀告您。"},{text:"太后曰：“敬诺。年几何矣？”",annotations:["敬诺：答应，好的","几何：多大。"],translation:"太后说：好，我答应你。他多大年纪了？"},{text:"对曰：“十五岁矣。虽少，愿及未填沟壑而托之。”",annotations:["填沟壑：谦称自己死去","托：托付。"],translation:"触龙答道：十五岁。虽然年纪小，我希望趁我没死把他托付给您。"},{text:"太后曰：“丈夫亦爱怜其少子乎？”",annotations:["丈夫：古代指男子","少子：小儿子。"],translation:"太后说：男人也疼爱自己的小儿子吗？"},{text:"对曰：“甚于妇人。”",annotations:["甚：超过。"],translation:"触龙答：比妇人疼爱得还厉害。"},{text:"太后笑曰：“妇人异甚。”",annotations:["异甚：特别厉害。"],translation:"太后笑着说：妇人疼爱小儿子才格外厉害。"},{text:"对曰：“老臣窃以为媪之爱燕后贤于长安君。”",annotations:["媪(ǎo)：对老年女子尊称","燕后：太后女儿，嫁燕国","贤：胜过。"],translation:"触龙说：我私下认为您疼爱燕后，超过疼爱长安君。"},{text:"曰：“君过矣，不若长安君之甚。”",annotations:["过：错了","不若：比不上。"],translation:"太后说：你错了，我疼爱燕后远不如疼爱长安君。"},{text:"左师公曰：“父母之爱子，则为之计深远。",annotations:["计深远：做长远打算。"],translation:"触龙说：父母疼爱子女，就要为他们做长远的打算。"},{text:"媪之送燕后也，持其踵，为之泣，念悲其远也，亦哀之矣。",annotations:["踵(zhǒng)：脚后跟","持其踵：拉着她的脚舍不得放手","哀：伤心。"],translation:"当年您送燕后出嫁，握着她的脚为她哭泣，心疼她远嫁，实在是伤心。"},{text:"已行，非弗思也，祭祀必祝之，祝曰：‘必勿使反。’",annotations:["反：通“返”，古代诸侯女儿不被废就不能回国","祝：祷告。"],translation:"她走后，您不是不想她，但每逢祭祀一定为她祷告，祷告说：千万别让她回来。"},{text:"岂非计久长，有子孙相继为王也哉？”",annotations:["岂非……哉：难道不就是……吗。"],translation:"这不就是为她长远考虑，希望她的子孙世代在燕国为王吗？"},{text:"太后曰：“然。”",annotations:["然：对，是这样。"],translation:"太后说：是。"},{text:"左师公曰：“今三世以前，至于赵之为赵，赵王之子孙侯者，其继有在者乎？”",annotations:["三世：三代","侯：名作动词，封侯","继：后代继承人。"],translation:"触龙问：从现在往上推三代，直到赵国建立之初，赵王被封侯的子孙，他们的后代还有保住爵位的吗？"},{text:"曰：“无有。”",annotations:[],translation:"太后说：没有。"},{text:"曰：“微独赵，诸侯有在者乎？”",annotations:["微独：不仅，不单是。"],translation:"触龙又问：不单赵国，其他诸侯的封侯子孙还有继承爵位的吗？"},{text:"曰：“老妇不闻也。”",annotations:[],translation:"太后说：我从没听说过。"},{text:"“此其近者祸及身，远者及其子孙。",annotations:["及：落到。"],translation:"触龙说：这是因为他们当中，祸患早的落到自己身上，晚的落到子孙头上。"},{text:"岂人主之子孙则必不善哉？位尊而无功，奉厚而无劳，而挟重器多也。",annotations:["奉：通“俸”，俸禄","挟：拥有","重器：金玉封地等贵重器物。"],translation:"难道君主的子孙就一定不好吗？只因他们地位尊贵却没有功勋，俸禄丰厚却没有劳苦，还拥有大量贵重封地宝物。"},{text:"今媪尊长安君之位，而封之以膏腴之地，多予之重器，而不及今令有功于国。",annotations:["尊：使动，使……尊贵","膏腴(yú)：肥沃","有功于国：状语后置，对国家立下功劳。"],translation:"如今您抬高长安君的地位，把肥沃土地封给他，赐给他无数珍宝，却不趁现在让他为国家立下功劳。"},{text:"一旦山陵崩，长安君何以自托于赵？”",annotations:["山陵崩：委婉称太后去世","何以：宾语前置，凭什么","托：立足。"],translation:"一旦您百年之后，长安君凭什么在赵国立足呢？"},{text:"老臣以媪为长安君计短也，故以为其爱不若燕后。”",annotations:["计短：打算得太短浅。"],translation:"我认为您为长安君考虑得太短浅，所以说您爱他比不上爱燕后。"},{text:"太后曰：“诺，恣君之所使之。”",annotations:["恣：任凭","使之：派遣他。"],translation:"太后说：好吧，任凭你安排派遣长安君。"},{text:"于是为长安君约车百乘，质于齐，齐兵乃出。",annotations:["约车：备办车辆","乘(shèng)：战车","质：名作动词，做人质。"],translation:"于是为长安君备好一百辆车子，送他到齐国做人质，齐国这才出兵救赵。"},{text:"子义闻之曰：“人主之子也，骨肉之亲也，犹不能恃无功之尊、无劳之奉，而守金玉之重也，而况人臣乎。”",annotations:["子义：赵国贤士","犹：尚且","况：何况。"],translation:"贤士子义听说这件事后感慨：君主的亲生子女，尚且不能靠着没有功勋的高位、没有劳苦的厚禄守住贵重封地宝物，更何况普通臣子呢。"}]},8:{id:"8",title:"子路曾皙冉有公西华侍坐",source:"《论语》",paragraphs:[{text:"子路、曾皙、冉有、公西华侍坐。",annotations:["侍坐：陪孔子闲坐","子路：仲由","曾皙：曾点，曾子之父","冉有：冉求","公西华：公西赤。"],translation:"子路、曾皙、冉有、公西华四人陪孔子坐着。"},{text:"子曰：“以吾一日长乎尔，毋吾以也。",annotations:["以：因为","长(zhǎng)：年长","乎：比","毋吾以：宾语前置，毋以吾，不要因为我（年长）就不敢说话。"],translation:"孔子说：“因为我年纪比你们大一点，你们不要因为我年长就不敢发言。"},{text:"居则曰：‘不吾知也！’",annotations:["居：平日闲居","不吾知：宾语前置，不知吾，没有人了解我。"],translation:"你们平日总说：‘没有人了解我呀！’"},{text:"如或知尔，则何以哉？”",annotations:["或：有人","何以：宾语前置，以何，凭借什么（施展抱负）。"],translation:"如果有人赏识重用你们，你们打算怎么做呢？”"},{text:"子路率尔而对曰：“千乘之国，摄乎大国之间，加之以师旅，因之以饥馑；由也为之，比及三年，可使有勇，且知方也。”",annotations:["率尔：轻率、急忙","千乘(shèng)之国：拥有千辆兵车的诸侯国","摄：夹在","师旅：军队，指外敌入侵","因之：接着","饥馑：饥荒","比(bì)及：等到","方：礼义正道。"],translation:"子路不假思索地答道：“一个拥有千辆兵车的国家，夹在大国中间，外有军队侵犯，内又接连遭遇饥荒；让我去治理，只要三年，就能让百姓勇敢善战，并且懂得礼义。”"},{text:"夫子哂之。",annotations:["哂(shěn)：微笑，这里带有轻微讥笑。"],translation:"孔子听了，微微一笑。"},{text:"“求，尔何如？”",annotations:["求：冉有之名","何如：怎么样。"],translation:"孔子又问：“冉求，你怎么样？”"},{text:"对曰：“方六七十，如五六十，求也为之，比及三年，可使足民。如其礼乐，以俟君子。”",annotations:["方：方圆","如：或者","足民：使百姓富足","俟(sì)：等待。"],translation:"冉有答道：“方圆六七十里，或者五六十里的小国，让我治理三年，可以让百姓衣食富足；至于礼乐教化，就要等待贤德君子来推行了。”"},{text:"“赤，尔何如？”",annotations:["赤：公西华之名。"],translation:"孔子问：“公西赤，你呢？”"},{text:"对曰：“非曰能之，愿学焉。宗庙之事，如会同，端章甫，愿为小相焉。”",annotations:["能之：独自胜任","会同：诸侯会盟、朝见天子","端、章甫：古代礼服、礼帽，名作动词，穿戴礼服礼帽","相：司仪赞礼的官员。"],translation:"公西华答道：“不敢说我能做到，只是愿意学习。宗庙祭祀，或是诸侯会盟、朝见天子，我愿意穿戴礼服礼帽，做一名小小的司仪。”"},{text:"“点，尔何如？”",annotations:["点：曾皙之名。"],translation:"孔子问：“曾点，你怎么样？”"},{text:"鼓瑟希，铿尔，舍瑟而作，对曰：“异乎三子者之撰。”",annotations:["希：通“稀”，弹瑟声音渐缓","铿尔：放下瑟的声响","作：起身","撰：才能、为政的说法","异乎三子者之撰：状语后置，和三人的志向不同。"],translation:"这时曾皙弹瑟的声音渐渐稀疏，接着铿的一声放下瑟，站起身答道：“我的志向和三位同学所说的不一样。”"},{text:"子曰：“何伤乎？亦各言其志也。”",annotations:["何伤：有什么妨碍。"],translation:"孔子说：“有什么关系呢？不过是各自谈谈自己的志向罢了。”"},{text:"曰：“莫春者，春服既成，冠者五六人，童子六七人，浴乎沂，风乎舞雩，咏而归。”",annotations:["莫：通“暮”","冠者：成年人","沂(yí)：沂水","风：名作动词，吹风乘凉","舞雩(yú)：求雨的祭坛","浴乎沂、风乎舞雩：状语后置。"],translation:"曾皙说：“暮春时节，春天的衣服都穿定了，和五六位成年人、六七个少年，在沂水里沐浴，到舞雩台上吹风乘凉，一路唱着歌走回家。”"},{text:"夫子喟然叹曰：“吾与点也！”",annotations:["喟(kuì)然：长叹的样子","与(yù)：赞同、赞许。"],translation:"孔子长叹一声说：“我赞同曾皙的志向啊！”"},{text:"三子者出，曾皙后。",annotations:["后：走在后面，留到最后。"],translation:"子路、冉有、公西华三人都出去了，曾皙走在后面。"},{text:"曾皙曰：“夫三子者之言何如？”",annotations:[],translation:"曾皙问道：“他们三个人的话怎么样？”"},{text:"子曰：“亦各言其志也已矣。”",annotations:["已矣：罢了。"],translation:"孔子说：“也不过是各自说说自己的志向罢了。”"},{text:"曰：“夫子何哂由也？”",annotations:[],translation:"曾皙问：“您为什么笑仲由呢？”"},{text:"曰：“为国以礼，其言不让，是故哂之。",annotations:["让：谦让","是故：因此。"],translation:"孔子说：“治理国家要依靠礼，可他说话毫不谦让，所以我笑他。"},{text:"唯求则非邦也与？",annotations:["邦：国家","与：通“欤”，语气词。"],translation:"难道冉求讲的就不是治国大事吗？"},{text:"安见方六七十，如五六十而非邦也者？",annotations:["安：怎么。"],translation:"怎么见得方圆六七十里或五六十里的土地就不算国家呢？"},{text:"唯赤则非邦也与？",annotations:[],translation:"难道公西赤讲的就不是治国大事吗？"},{text:"宗庙会同，非诸侯而何？赤也为之小，孰能为之大？”",annotations:["孰：谁","小、大：指小相、大相。"],translation:"宗庙祭祀、诸侯会盟，不是诸侯的大事又是什么？如果公西华只能做小司仪，那谁能做大司仪呢？”"}]},9:{id:"9",title:"季氏将伐颛臾",source:"《论语》",paragraphs:[{text:"季氏将伐颛臾。",annotations:["季氏：季康子，鲁国权臣","颛(zhuān)臾(yú)：鲁国附属小国。"],translation:"季康子准备攻打颛臾。"},{text:"冉有、季路见于孔子曰：“季氏将有事于颛臾。”",annotations:["冉有、季路（子路）：季氏家臣","见：拜见","有事：指军事行动","状语后置：于颛臾有事。"],translation:"冉有、子路来拜见孔子，说：季氏将要对颛臾采取军事行动。"},{text:"孔子曰：“求！无乃尔是过与？",annotations:["求：冉有","无乃……与：恐怕……吧","宾语前置：尔是过，过尔，责备你","与：通“欤”。"],translation:"孔子说：冉求！这恐怕该责备你吧？"},{text:"夫颛臾，昔者先王以为东蒙主，且在邦域之中矣，是社稷之臣也。何以伐为？”",annotations:["东蒙主：主管蒙山祭祀","邦域：鲁国国境","社稷之臣：鲁国属臣","何以伐为：宾语前置，为何要攻打它呢。"],translation:"颛臾，从前先王让它主持蒙山祭祀，而且地处鲁国疆域之内，是鲁国的属国，为什么要攻打它？"},{text:"冉有曰：“夫子欲之，吾二臣者皆不欲也。”",annotations:["夫子：指季康子","欲之：想要攻打颛臾。"],translation:"冉有说：是季康子想要这么做，我们两个做家臣的都不希望开战。"},{text:"孔子曰：“求！周任有言曰：‘陈力就列，不能者止。’",annotations:["周任：古代史官","陈力：施展才能","就列：担任职位","止：辞去职位。"],translation:"孔子说：冉求！古代史官周任说过：能施展才干就担任官职，做不到就辞官。"},{text:"危而不持，颠而不扶，则将焉用彼相矣？",annotations:["危：走路不稳","颠：跌倒","相：搀扶盲人的人","焉：何必。"],translation:"盲人摇晃要摔倒却不去搀扶，那还要搀扶的人干什么？"},{text:"且尔言过矣，虎兕出于柙，龟玉毁于椟中，是谁之过与？”",annotations:["兕(sì)：独角犀牛","柙(xiá)：兽笼","椟(dú)：木匣","状语后置：出于柙、毁于椟中。"],translation:"况且你的话错了。老虎犀牛从笼子里跑出，龟甲美玉在匣子里毁坏，这是谁的过错呢？"},{text:"冉有曰：“今夫颛臾，固而近于费，今不取，后世必为子孙忧。”",annotations:["固：城墙坚固","费(bì)：季氏封地","忧：祸患。"],translation:"冉有说：如今颛臾城墙坚固，又靠近季氏的封地费邑，现在不攻取，将来一定会成为子孙的祸患。"},{text:"孔子曰：“求！君子疾夫舍曰欲之而必为之辞。",annotations:["疾：痛恨","舍曰：不说","为之辞：找借口。"],translation:"孔子说：冉求！君子痛恨那种心里想要，却不肯直说，还要另找借口的行为。"},{text:"丘也闻有国有家者，不患寡而患不均，不患贫而患不安。",annotations:["有国：诸侯","有家：卿大夫","患：担忧。"],translation:"我听说诸侯、大夫这类统治者，不担心人口少，而担心分配不均；不担心贫穷，而担心境内不能安定。"},{text:"盖均无贫，和无寡，安无倾。",annotations:["盖：大概、因为","倾：倾覆亡国。"],translation:"财物分配平均就没有贫穷，上下和睦就不愁人少，境内安定国家就不会倾覆。"},{text:"夫如是，故远人不服，则修文德以来之。",annotations:["如是：像这样","文德：礼乐德教","来：使动，使……归顺。"],translation:"做到这样，如果远方百姓还不归附，就修明礼乐德教使他们前来归顺。"},{text:"既来之，则安之。",annotations:["安：使动，使……安定生活。"],translation:"他们归顺之后，就让他们安定下来。"},{text:"今由与求也，相夫子，远人不服而不能来也；邦分崩离析而不能守也；而谋动干戈于邦内。",annotations:["相：辅佐","分崩离析：四分五裂","干戈：兵器，代指战争","状语后置：动干戈于邦内。"],translation:"如今子路和冉有你们二人辅佐季氏，远方之人不归附却无法使他们归顺；国内四分五裂却不能保全，反而谋划在国内发动战争。"},{text:"吾恐季孙之忧，不在颛臾，而在萧墙之内也。”",annotations:["萧墙：宫门内屏风，代指宫廷内部。"],translation:"我担心季康子的忧患不在颛臾，而在鲁国宫廷内部啊。"}]},10:{id:"10",title:"逍遥游",source:"《庄子》",paragraphs:[{text:"北冥有鱼，其名为鲲。",annotations:["北冥：北方深海","鲲：传说中的大鱼。"],translation:"北方的深海里有一条鱼，它的名字叫鲲。"},{text:"鲲之大，不知其几千里也。",annotations:["之：主谓之间，取消句子独立性。"],translation:"鲲的体型巨大，不知道它有几千里长。"},{text:"化而为鸟，其名为鹏。",annotations:["化：变化。"],translation:"鲲变化成一只鸟，它的名字叫鹏。"},{text:"鹏之背，不知其几千里也。",annotations:[],translation:"鹏的脊背，也不知道有几千里宽广。"},{text:"怒而飞，其翼若垂天之云。",annotations:["怒：奋起、振翅","垂天：天边","垂，通“陲”，边际。"],translation:"当它振翅奋起高飞时，翅膀就像悬挂在天边的云彩。"},{text:"是鸟也，海运则将徙于南冥。",annotations:["是：这","海运：海水翻腾起大风","徙：迁徙","南冥：南方深海。"],translation:"这只鹏鸟，每当海上风起，就要迁徙飞往南方的深海。"},{text:"南冥者，天池也。",annotations:["天池：天然形成的大池，大海。判断句。"],translation:"南方深海，是天然形成的浩瀚大湖。"},{text:"《齐谐》者，志怪者也。",annotations:["《齐谐》：古代记载怪异之事的书","志：记载。判断句。"],translation:"《齐谐》这本书，是专门记载奇异怪事的。"},{text:"《谐》之言曰：“鹏之徙于南冥也，水击三千里，抟扶摇而上者九万里，去以六月息者也。”",annotations:["水击：翅膀拍打水面","抟(tuán)：盘旋飞翔","扶摇：旋风","息：风，六月大风。"],translation:"书上记载说：鹏鸟飞往南海时，翅膀拍打水面，激起三千里浪花，乘着旋风盘旋飞上九万里高空，凭借六月的大风才能离去。"},{text:"野马也，尘埃也，生物之以息相吹也。",annotations:["野马：山野间浮动的雾气","息：气息","之：取独。"],translation:"山野中蒸腾的雾气、空中漂浮的尘埃，都是万物的气息相互吹拂而飘动。"},{text:"天之苍苍，其正色邪？其远而无所至极邪？",annotations:["苍苍：深蓝","正色：本来的颜色","极：尽头。"],translation:"天空深蓝苍茫，这是它真正的颜色吗？还是因为天高远，看不到它的尽头呢？"},{text:"其视下也，亦若是则已矣。",annotations:["是：这样","已矣：罢了。"],translation:"鹏鸟从高空向下看大地，也如同人抬头看天，不过如此罢了。"},{text:"且夫水之积也不厚，则其负大舟也无力。",annotations:["负：承载。"],translation:"再说，如果水积蓄得不深厚，就没有力量承载大船。"},{text:"覆杯水于坳堂之上，则芥为之舟；置杯焉则胶，水浅而舟大也。",annotations:["坳(ào)堂：厅堂低洼处","芥：小草","胶：粘住搁浅。状语后置。"],translation:"倒一杯水在厅堂的低洼处，小草可以当作小船；放上杯子就会粘住不动，这是水太浅而船太大的缘故。"},{text:"风之积也不厚，则其负大翼也无力。",annotations:["大翼：鹏巨大的翅膀。"],translation:"如果风力积蓄得不够雄厚，就没有力量承载鹏巨大的翅膀。"},{text:"故九万里，则风斯在下矣，而后乃今培风；背负青天而莫之夭阏者，而后乃今将图南。",annotations:["斯：才","培：凭借","莫之夭阏(è)：宾语前置，莫夭阏之，没有什么能阻挡它","夭阏：阻拦","图南：计划向南飞。"],translation:"所以鹏飞上九万里高空，大风就在它身下托举，这之后才能凭借风力；背负青天，没有任何东西能阻挡它，然后才打算向南飞行。"},{text:"蜩与学鸠笑之曰：“我决起而飞，抢榆枋而止，时则不至，而控于地而已矣，奚以之九万里而南为？”",annotations:["蜩(tiáo)：蝉","学鸠：小斑鸠","决(xuè)：急速飞起","抢(qiāng)：撞上","榆枋：榆树、檀树","控：落下","奚以……为：固定句式，何必……呢。"],translation:"蝉和小斑鸠讥笑鹏说：我们猛地起飞，撞上榆树、檀树就停下，有时飞不上去，落在地上就算了，何必飞上九万里高空再向南飞呢？"},{text:"适莽苍者，三餐而反，腹犹果然；适百里者，宿舂粮；适千里者，三月聚粮。",annotations:["适：前往","莽苍：近郊郊野","反：通“返”","果然：饱胀的样子","舂(chōng)粮：捣米备粮。"],translation:"去近郊游玩的人，带上三餐粮食往返，回来肚子还是饱饱的；去百里之外的人，前一晚就要捣米准备干粮；去往千里之外的人，要提前三个月储备粮食。"},{text:"之二虫又何知！",annotations:["之：这","二虫：指蜩与学鸠","何知：宾语前置，知何，知道什么。"],translation:"这两个小虫又懂得什么！"},{text:"小知不及大知，小年不及大年。",annotations:["知：通“智”，智慧","年：寿命。"],translation:"小聪明比不上大智慧，短寿比不上长寿。"},{text:"奚以知其然也？",annotations:["奚以：宾语前置，凭什么","然：这样。"],translation:"凭什么知道是这样呢？"},{text:"朝菌不知晦朔，蟪蛄不知春秋，此小年也。",annotations:["朝菌：清晨生、日暮死的菌类","晦朔：月末、月初，代指一月","蟪(huì)蛄(gū)：寒蝉，春生夏死、夏生秋死","春秋：一整年。"],translation:"朝生暮死的菌类不知道一月的时光，寒蝉不知道一年的时光，这就是短寿。"},{text:"楚之南有冥灵者，以五百岁为春，五百岁为秋；上古有大椿者，以八千岁为春，八千岁为秋，此大年也。",annotations:["冥灵、大椿：长寿古树","岁：年。"],translation:"楚国南方有一种叫冥灵的树，把五百年当作一个春天，五百年当作一个秋天；远古时代有一棵大椿树，把八千年当作春，八千年当作秋，这就是长寿。"},{text:"而彭祖乃今以久特闻，众人匹之，不亦悲乎！",annotations:["彭祖：古代长寿之人","特：独","匹：相比。"],translation:"彭祖如今唯独以长寿闻名，普通人与他相比，岂不可悲！"},{text:"汤之问棘也是已。",annotations:["汤：商汤","棘：汤的贤人","是已：就是这样。"],translation:"商汤询问贤人棘，说的也是这个道理。"},{text:"穷发之北，有冥海者，天池也。",annotations:["穷发：不生草木的极北荒漠。"],translation:"在寸草不生的极北之地，有一片深海，是天然形成的大湖。"},{text:"有鱼焉，其广数千里，未有知其修者，其名为鲲。",annotations:["修：长度。"],translation:"海里有一条鱼，宽达几千里，没人知道它有多长，名字叫鲲。"},{text:"有鸟焉，其名为鹏，背若泰山，翼若垂天之云，抟扶摇羊角而上者九万里，绝云气，负青天，然后图南，且适南冥也。",annotations:["羊角：旋风","绝：穿过、超越。"],translation:"里面还有一只鸟名叫鹏，脊背像泰山，翅膀如同天边垂云，乘着盘旋旋风飞上九万里高空，穿过云层，背负青天，之后打算向南，飞往南海。"},{text:"斥鷃笑之曰：“彼且奚适也？我腾跃而上，不过数仞而下，翱翔蓬蒿之间，此亦飞之至也。而彼且奚适也？”",annotations:["斥鷃(yàn)：小麻雀","仞：古代长度单位","蓬蒿：低矮野草","至：极致、顶点","奚适：宾语前置，去哪里。"],translation:"小麻雀讥笑鹏说：它将要飞到哪里去？我跳跃向上飞，不过几丈高就落下，在野草间盘旋飞舞，这也是飞翔的极致了。而它还要飞到哪里去呢？"},{text:"此小大之辩也。",annotations:["辩：通“辨”，区别。"],translation:"这就是小和大的分别。"},{text:"故夫知效一官，行比一乡，德合一君，而征一国者，其自视也，亦若此矣。",annotations:["效：胜任","比：团结","合：投合","征：取信","而：通“能”，能力。"],translation:"那些才智足以胜任一官之职、品行能团结一乡之人、德行能投合一位君主、能力能取信一国百姓的人，他们看待自己，也如同小麻雀这般自满。"},{text:"而宋荣子犹然笑之。",annotations:["宋荣子：先秦思想家","犹然：嗤笑的样子。"],translation:"宋荣子尚且嗤笑这类人。"},{text:"且举世誉之而不加劝，举世非之而不加沮，定乎内外之分，辩乎荣辱之境，斯已矣。",annotations:["举：全","劝：勉励","沮：沮丧","内外：自我与外物","境：界限。"],translation:"世上所有人都称赞他，他也不会更加奋勉；全天下人都非议他，他也不会感到沮丧。他能分清自我与外物的分界，辨明荣与辱的界限，不过如此而已。"},{text:"彼其于世，未数数然也。",annotations:["数数(shuò)然：急切追求的样子。"],translation:"他对于世间的功名利禄，从来不去急切追求。"},{text:"虽然，犹有未树也。",annotations:["树：树立，指达到逍遥无待的境界。"],translation:"即便这样，他仍有未能树立的境界。"},{text:"夫列子御风而行，泠然善也，旬有五日而后反。",annotations:["列子：列御寇，传说能乘风而行","泠(líng)然：轻快的样子","有：通“又”。"],translation:"列子能乘风行走，身姿轻快美妙，十五天后才返回。"},{text:"彼于致福者，未数数然也。",annotations:["致福：求福、求顺遂。"],translation:"他对于求福这件事，也不曾急切追逐。"},{text:"此虽免乎行，犹有所待者也。",annotations:["待：凭借、依靠。"],translation:"他虽然免去了步行，却依旧要依靠风力，不能真正自由。"},{text:"若夫乘天地之正，而御六气之辩，以游无穷者，彼且恶乎待哉？",annotations:["天地之正：天地万物的自然本性","六气：阴、阳、风、雨、晦、明","辩：通“变”，变化","恶(wū)乎待：宾语前置，待恶，依靠什么。"],translation:"至于顺应天地万物的本性，驾驭六气的变化，遨游于无边无尽境界的人，他还需要依靠什么外物呢？"},{text:"故曰：至人无己，神人无功，圣人无名。",annotations:["至人、神人、圣人：庄子心中三种最高境界之人","无己：忘却自我","无功：不求功绩","无名：不求名望。"],translation:"所以说：修养最高的至人能忘却自我，神明之人不追求功业，圣明之人不追求世俗名望。"}]},11:{id:"11",title:"秋水",source:"《庄子》",paragraphs:[{text:"秋水时至，百川灌河。",annotations:["时：名词作状语，按时令","河：特指黄河。"],translation:"秋天的洪水按照时令到来，众多小河的水都汇入黄河。"},{text:"泾流之大，两涘渚崖之间，不辩牛马。",annotations:["泾流：通畅的水流","涘(sì)：岸边","渚(zhǔ)：水中沙洲","崖：河岸","辩：通“辨”，分辨。"],translation:"河面水流宽阔，两岸与水中沙洲之间，连牛马都分辨不清。"},{text:"于是焉河伯欣然自喜，以天下之美为尽在己。",annotations:["河伯：黄河水神","欣然：高兴的样子","以……为：认为……是。"],translation:"在这时，河伯十分得意，认为天下所有壮美的景色全都汇集在自己这里。"},{text:"顺流而东行，至于北海。",annotations:["东：名词作状语，向东","北海：此处指渤海。"],translation:"他顺着水流向东前行，来到了渤海。"},{text:"东面而视，不见水端。",annotations:["东面：面朝东","端：尽头。"],translation:"面朝东方眺望，看不见海水的边际。"},{text:"于是焉河伯始旋其面目，望洋向若而叹曰：“野语有之曰，‘闻道百，以为莫己若’者，我之谓也。”",annotations:["旋：调转","望洋：抬头仰望的样子","若：北海海神名","野语：俗语","莫己若：宾语前置，莫若己，没有谁比得上自己","我之谓：宾语前置，谓我，说的就是我。"],translation:"这时河伯才转变了自得的神情，抬头望着海神若叹息说：俗语有这样的说法，‘听闻过许多道理，就认为没有谁能比得上自己’，说的就是我这样的人啊。"},{text:"且夫我尝闻少仲尼之闻，而轻伯夷之义者，始吾弗信。",annotations:["少、轻：意动用法，以……为少、以……为轻","仲尼：孔子","伯夷：上古守义隐士","闻：学识。"],translation:"况且我曾经听说，有人小看孔子的学识，轻视伯夷的道义，起初我还不相信。"},{text:"今我睹子之难穷也，吾非至于子之门，则殆矣。",annotations:["睹：看见","穷：穷尽","殆：危险。"],translation:"如今我亲眼看见您广阔无边难以穷尽，如果我没有来到您的门前，那就危险了。"},{text:"吾长见笑于大方之家。”",annotations:["见……于：被动句式，被","大方之家：懂得大道理的人。"],translation:"我将长久地被学识渊博、通晓大道的人耻笑。"},{text:"北海若曰：“井蛙不可以语于海者，拘于虚也。",annotations:["语(yù)：谈论","拘：束缚","虚：通“墟”，居住的地方","被动句：拘于虚，被居所局限。"],translation:"海神若说：井底的青蛙不能和它谈论大海，是因为它被狭小的居住环境束缚住了。"},{text:"夏虫不可以语于冰者，笃于时也。",annotations:["笃：限制","时：时节。"],translation:"夏天生长的小虫不能和它谈论冰雪，是因为它被生长的时节限制。"},{text:"曲士不可以语于道者，束于教也。",annotations:["曲士：见识浅陋的读书人","束：束缚","教：片面的教化、学识。"],translation:"见识浅陋的书生不能和他谈论大道，是因为他被片面的学识束缚。"},{text:"今尔出于崖涘，观于大海，乃知尔丑，尔将可与语大理矣。",annotations:["丑：浅陋、不足","大理：宏大的道理。"],translation:"如今你走出河岸，看见了大海，才知道自己的浅陋，那就可以和你谈论宏大的道理了。"},{text:"天下之水，莫大于海。",annotations:[],translation:"天下所有的水域，没有比大海更大的。"},{text:"万川归之，不知何时止而不盈；尾闾泄之，不知何时已而不虚。",annotations:["盈：满","尾闾(lǘ)：传说中大海泄水的地方","已：停止","虚：空。"],translation:"千万条江河都汇入大海，永不停歇，大海却不会满溢；海水从尾闾不断泄出，无休无止，大海却不会变空。"},{text:"春秋不变，水旱不知。",annotations:["春秋：四季更替","知：察觉、影响。"],translation:"无论春秋更替，大海水量始终不变，水灾旱灾也丝毫影响不到它。"},{text:"此其过江河之流，不可为量数。",annotations:["过：超过","量数：估量计算。"],translation:"大海的水量远超长江黄河，无法用数字估量。"},{text:"而吾未尝以此自多者，自以比形于天地，而受气于阴阳。",annotations:["自多：自我夸耀","比形：寄托形体","受气：禀受阴阳之气。"],translation:"但我从未凭借大海而自我夸耀，我自知形体寄托在天地之间，从阴阳二气禀受生机。"},{text:"吾在于天地之间，犹小石小木之在大山也。",annotations:[],translation:"我处在天地之间，就像一块小石头、一棵小树置身于大山之中。"},{text:"方存乎见少，又奚以自多！",annotations:["存：心中存有","奚以：宾语前置，凭什么。"],translation:"我总觉得自己十分渺小，又哪里敢自我夸耀！"},{text:"计四海之在天地之间也，不似礨空之在大泽乎？",annotations:["礨(lěi)空：石块上的小孔","大泽：广阔的湖泊。"],translation:"算起来四海处在天地之间，不就像石块上的小孔处在广阔湖泽里吗？"},{text:"计中国之在海内，不似稊米之在大仓乎？",annotations:["中国：中原大地","稊(tí)米：细小的米粒","大仓：巨大粮仓。"],translation:"中原大地处在四海之内，不就像一粒小米存放在巨大粮仓中吗？"},{text:"号物之数谓之万，人处一焉。",annotations:["号：称","处一：只是万物中的一种。"],translation:"人们称物类的数量为万物，人类只是其中一种。"},{text:"人卒九州，谷食之所生，舟车之所通，人处一焉。",annotations:["卒：通“萃”，聚集","九州：天下。"],translation:"人类聚集在天下，凡是粮食生长、车船通行的地方，每个人也只是万千人中的一个。"},{text:"此其比万物也，不似豪末之在于马体乎？",annotations:["豪：通“毫”，毫毛","末：末梢。"],translation:"拿人和万物相比，不就像一根毫毛长在马身上吗？"},{text:"五帝之所连，三王之所争，仁人之所忧，任士之所劳，尽此矣。",annotations:["五帝：黄帝、颛顼、帝喾、尧、舜","连：禅让相传","三王：夏禹、商汤、周文王","任士：贤能之士。"],translation:"五帝禅让相传的天下、三王争夺的疆土、仁人担忧的世事、贤能之士操劳的功业，全都不过是这毫末般微小的东西。"},{text:"伯夷辞之以为名，仲尼语之以为博，此其自多也，不似尔向之自多于水乎？”",annotations:["辞：推辞天下","向：刚才","自多于水：凭借河水自我夸耀。"],translation:"伯夷推辞天下用来博取美名，孔子谈论天下用来显示学识广博，他们这样自我夸耀，不就像你刚才凭借河水洋洋自得一样吗？"}]},12:{id:"12",title:"齐桓晋文之事",source:"《孟子》",paragraphs:[{text:"齐宣王问曰：“齐桓、晋文之事可得闻乎？”",annotations:["齐宣王：齐国君主","齐桓、晋文：春秋霸主齐桓公、晋文公","闻：使动，使我听闻。"],translation:"齐宣王问道：“齐桓公、晋文公称霸的事迹，能讲给我听听吗？”"},{text:"孟子对曰：“仲尼之徒无道桓文之事者，是以后世无传焉，臣未之闻也。”",annotations:["徒：弟子","道：谈论","是以：因此","未之闻：宾语前置，未闻之，没有听过这件事。"],translation:"孟子回答说：“孔子的弟子没人谈论齐桓公、晋文公的事迹，所以后世没有流传，我不曾听说。”"},{text:"无以，则王乎？",annotations:["无以：不得已","王(wàng)：动词，施行王道统一天下。"],translation:"如果非要我说，那我就说说施行王道的道理吧？"},{text:"曰：“德何如，则可以王矣？”",annotations:["何如：怎样","王：称王天下。"],translation:"宣王说：“德行要达到怎样，才能依靠王道统一天下？”"},{text:"曰：“保民而王，莫之能御也。”",annotations:["保：安抚","莫之能御：宾语前置，莫能御之，没人能够抵挡。"],translation:"孟子说：“安抚百姓从而称王天下，就没有人能阻挡他。”"},{text:"曰：“若寡人者，可以保民乎哉？”",annotations:["若：像","寡人：君主谦称。"],translation:"宣王说：“像我这样的人，能够安抚百姓吗？”"},{text:"曰：“可。”",annotations:["简单应答，表肯定。"],translation:"孟子说：“可以。”"},{text:"曰：“何由知吾可也？”",annotations:["何由：宾语前置，由何，凭什么。"],translation:"宣王说：“凭什么知道我能做到？”"},{text:"曰：“臣闻之胡龁曰：王坐于堂上，有牵牛而过堂下者，王见之，曰：‘牛何之？’”",annotations:["胡龁(hé)：宣王近侍","何之：宾语前置，之何，去哪里。"],translation:"孟子说：“我从胡龁那里听说：大王坐在大殿上，有人牵着牛从殿下走过，大王看见了，问：‘牛要牵到哪里去？’”"},{text:"对曰：“将以衅钟。”",annotations:["衅(xìn)钟：古代祭祀仪式，杀牲畜取血涂抹钟器。"],translation:"那人回答：“准备杀掉取血祭祀钟。”"},{text:"王曰：“舍之！吾不忍其觳觫，若无罪而就死地。”",annotations:["舍：释放","觳(hú)觫(sù)：牲畜恐惧发抖的样子","就：走向。"],translation:"大王说：“放了它！我不忍心看它浑身发抖，毫无罪过却要走向死地。”"},{text:"对曰：“然则废衅钟与？”",annotations:["然则：既然这样那么","与：通“欤”，语气助词。"],translation:"那人问道：“既然这样，就要废除祭钟的仪式吗？”"},{text:"曰：“何可废也？以羊易之。”",annotations:["易：替换。"],translation:"大王说：“怎么能废除？用羊替换这头牛。”"},{text:"不识有诸？",annotations:["识：知晓","诸：之乎的合音，有这件事吗。"],translation:"不知道是否有这件事？"},{text:"曰：“有之。”",annotations:["应答，确认事实。"],translation:"宣王说：“有这件事。”"},{text:"曰：“是心足以王矣。百姓皆以王为爱也，臣固知王之不忍也。”",annotations:["是：这种","爱：吝啬","固：本来。"],translation:"孟子说：“这份仁心足够施行王道了。百姓都认为大王吝啬，我原本就知道您是于心不忍。”"},{text:"王曰：“然，诚有百姓者。齐国虽褊小，吾何爱一牛？”",annotations:["诚：确实","褊(biǎn)小：国土狭小。"],translation:"宣王说：“没错，确实有百姓这样想。齐国就算狭小，我又怎么会吝啬一头牛？”"},{text:"即不忍其觳觫，若无罪而就死地，故以羊易之也。",annotations:["即：只是","就死地：赴死。"],translation:"只是不忍心看见它恐惧发抖，毫无过错就要被杀，所以才用羊替换它。"},{text:"曰：“王无异于百姓之以王为爱也。以小易大，彼恶知之？”",annotations:["无异：不要责怪","恶(wū)：怎么，哪里。"],translation:"孟子说：“大王不要怪百姓觉得您吝啬。您用小羊换大牛，他们怎么明白您的心意？”"},{text:"王若隐其无罪而就死地，则牛羊何择焉？",annotations:["隐：怜悯","择：区别。"],translation:"您如果怜悯牲畜无罪赴死，那牛和羊又有什么区别呢？"},{text:"王笑曰：“是诚何心哉？我非爱其财而易之以羊也，宜乎百姓之谓我爱也。”",annotations:["宜：应当","主谓倒装句，百姓说我吝啬是理所应当。"],translation:"宣王笑着说：“我这到底是什么心思？我不是舍不得钱财才换羊，百姓说我吝啬，也难怪了。”"},{text:"曰：“无伤也，是乃仁术也，见牛未见羊也。”",annotations:["无伤：没关系","仁术：体现仁爱的举动。"],translation:"孟子说：“没关系，这正是仁爱的体现，您亲眼看见了牛，却没有看见羊。”"},{text:"君子之于禽兽也，见其生，不忍见其死；闻其声，不忍食其肉。是以君子远庖厨也。",annotations:["远：使动用法，使……远离","庖厨：厨房。"],translation:"有德的人对待鸟兽，看见它们活着，就不忍心看它们死去；听见它们的哀鸣，就不忍心吃它们的肉。因此君子会远离厨房。"},{text:"王说，曰：“《诗》云：‘他人有心，予忖度之。’夫子之谓也。”",annotations:["说：通“悦”，喜悦","忖(cǔn)度(duó)：揣测","夫子之谓：宾语前置，说的就是先生您。"],translation:"宣王十分高兴，说：“《诗经》写道：‘别人心中的想法，我能够揣测到。’这话讲的就是先生您。”"},{text:"夫我乃行之，反而求之，不得吾心。夫子言之，于我心有戚戚焉。",annotations:["反：事后回头","戚戚：内心有所触动、豁然明白。"],translation:"我自己做了这件事，事后回想，却说不清自己的心思。先生一点明，我内心豁然通透。"},{text:"此心之所以合于王者，何也？",annotations:["合：契合","王：王道。"],translation:"这份心思之所以契合王道，是什么道理？"},{text:"曰：“有复于王者曰：‘吾力足以举百钧，而不足以举一羽；明足以察秋毫之末，而不见舆薪。’则王许之乎？”",annotations:["复：禀报","钧：古代重量单位，三十斤","明：视力","秋毫：秋天鸟兽细毛","舆薪：整车柴火","许：相信。"],translation:"孟子说：“如果有人向大王禀报：‘我的力气能举起三千斤重物，却拿不起一根羽毛；我的眼力能看清细毛末梢，却看不见整车柴火。’大王会相信他吗？”"},{text:"曰：“否。”",annotations:["否定答复。"],translation:"宣王说：“不信。”"},{text:'"今恩足以及禽兽，而功不至于百姓者，独何与？"',annotations:["及：推及","独：偏偏","与：通“欤”。"],translation:"孟子说：“如今大王的恩惠能推及牲畜，恩德却到不了百姓身上，偏偏是什么原因呢？”"},{text:"然则一羽之不举，为不用力焉；舆薪之不见，为不用明焉；百姓之不见保，为不用恩焉。",annotations:["见保：被动句式，被安抚","为：因为。"],translation:"拿不起一根羽毛，是不肯使出力气；看不见整车柴火，是不肯动用眼力；百姓得不到安抚，是大王不肯布施恩德。"},{text:"故王之不王，不为也，非不能也。",annotations:["前王：齐宣王","后王(wàng)：施行王道。"],translation:"所以大王不能施行王道统一天下，是不肯去做，不是做不到。"},{text:"曰：“不为者与不能者之形何以异？”",annotations:["形：外在表现","何以异：宾语前置，凭什么区分。"],translation:"宣王说：“不肯做和做不到，外在表现怎么区分？”"},{text:"曰：“挟太山以超北海，语人曰‘我不能’，是诚不能也。”",annotations:["挟：夹在腋下","超：跨越","北海：渤海。"],translation:"孟子说：“夹着泰山跨越渤海，对别人说‘我做不到’，这是真的做不到。”"},{text:"为长者折枝，语人曰‘我不能’，是不为也，非不能也。",annotations:["折枝：折树枝，代指简单容易的小事。"],translation:"为年长的人折一根树枝，说‘我做不到’，这是不肯做，不是做不到。"},{text:"故王之不王，非挟太山以超北海之类也；王之不王，是折枝之类也。",annotations:[],translation:"大王不施行王道，不是像夹泰山跨渤海那样真做不到，而是像不肯折树枝一样不愿去做。"},{text:"老吾老，以及人之老；幼吾幼，以及人之幼。天下可运于掌。",annotations:["第一个老、幼：形容词作动词，敬重、爱护","及：推及。"],translation:"敬重自己的长辈，再推及敬重别人的长辈；爱护自己的孩子，再推及爱护别人的孩子。治理天下就像在手掌中转动东西一样容易。"},{text:"《诗》云：‘刑于寡妻，至于兄弟，以御于家邦。’言举斯心加诸彼而已。",annotations:["刑：通“型”，作榜样","御：治理","举：拿，把。"],translation:"《诗经》说：“先给自己的妻子做好榜样，再推广到兄弟，进而治理好封邑与国家。”说的就是把这份仁心施加到他人身上罢了。"},{text:"故推恩足以保四海，不推恩无以保妻子。",annotations:["妻子：古今异义，妻子和儿女","无以：没有用来……的办法。"],translation:"推广恩德足以安定天下，不推广恩德，连自己的妻儿都保全不了。"},{text:"古之人所以大过人者，无他焉，善推其所为而已矣。",annotations:["大过人：远远超过普通人。"],translation:"古代圣贤远超常人的原因，没有别的，只是善于推广自己的善心罢了。"},{text:"今恩足以及禽兽，而功不至于百姓者，独何与？",annotations:[],translation:"如今恩惠能给到牲畜，却惠及不到百姓，究竟是为什么？"},{text:"权，然后知轻重；度，然后知长短。物皆然，心为甚。",annotations:["权：称量","度(duó)：丈量长短。"],translation:"称一称，才能知道轻重；量一量，才能知道长短。万物都是这样，人心更是如此。"},{text:"王请度之！抑王兴甲兵，危士臣，构怨于诸侯，然后快于心与？",annotations:["抑：难道","危：使动，使……陷入危难","构怨：结仇","快于心：状语后置，在心中畅快。"],translation:"大王请仔细思量！难道大王要发动战争，让将士百官身处险境，和各国诸侯结下仇怨，心里才痛快吗？"},{text:"王曰：“否，吾何快于是？将以求吾所大欲也。”",annotations:["何快于是：状语后置，对此有什么快乐。"],translation:"宣王说：“不是，我怎么会以此为乐？我是想要实现心中最大的愿望。”"},{text:"曰：“王之所大欲可得闻与？”",annotations:["闻：使我听闻。"],translation:"孟子说：“大王心中最大的愿望，可以讲给我听听吗？”"},{text:"王笑而不言。",annotations:["不言：不肯直说心中称霸的想法。"],translation:"宣王只是微笑，不说话。"},{text:"曰：“为肥甘不足于口与？轻暖不足于体与？抑为采色不足视于目与？声音不足听于耳与？便嬖不足使令于前与？王之诸臣皆足以供之，而王岂为是哉？”",annotations:["肥甘：肥美美食","轻暖：轻便保暖衣物","采色：美色","便(pián)嬖(bì)：君王身边受宠的近臣。"],translation:"孟子说：“是肥美食物不够吃？轻便暖衣不够穿？绚丽美色不够看？美妙乐曲不够听？身边宠臣不够使唤？您手下臣子全都能供给这些，大王难道是为了这些？”"},{text:"曰：“否，吾不为是也。”",annotations:[],translation:"宣王说：“不是，我不是为了这些。”"},{text:"曰：“然则王之所大欲可知已：欲辟土地，朝秦楚，莅中国而抚四夷也。”",annotations:["辟：开拓","朝：使动，使……朝拜","莅(lì)：统治","四夷：四方少数民族。"],translation:"孟子说：“那大王最大的愿望我就清楚了：想要开拓疆土，让秦国、楚国前来朝拜，统治中原大地，安抚四方外族。"},{text:"以若所为，求若所欲，犹缘木而求鱼也。”",annotations:["若：这样","缘木：爬上树木。"],translation:"用您现在的做法，去追求您想要的霸业，就像爬到树上去寻找鱼。”"},{text:"王曰：“若是其甚与？”",annotations:["甚：严重","主谓倒装，其甚若是，有这么严重吗。"],translation:"宣王说：“事情有这么严重吗？”"},{text:"曰：“殆有甚焉。缘木求鱼，虽不得鱼，无后灾；以若所为，求若所欲，尽心力而为之，后必有灾。”",annotations:["殆：恐怕，大概。"],translation:"孟子说：“恐怕比这还要严重。爬树找鱼，就算得不到鱼，也不会留下后患；用您的方式追逐霸业，尽心尽力去做，日后一定会招来灾祸。”"},{text:"曰：“可得闻与？”",annotations:[],translation:"宣王说：“能讲给我听听其中的道理吗？”"},{text:"曰：“邹人与楚人战，则王以为孰胜？”",annotations:["邹：小国","楚：大国，形成强弱对比。"],translation:"孟子说：“邹国人和楚国人交战，大王认为谁会取胜？”"},{text:"曰：“楚人胜。”",annotations:[],translation:"宣王说：“楚国人会获胜。”"},{text:"曰：“然则小固不可以敌大，寡固不可以敌众，弱固不可以敌强。”",annotations:["固：本来","敌：抵挡。"],translation:"孟子说：“小国本来抵挡不了大国，人少抵挡不了人多，弱小抵挡不了强大。"},{text:"海内之地，方千里者九，齐集有其一。以一服八，何以异于邹敌楚哉？盖亦反其本矣。”",annotations:["集：合计","服：使……臣服","盖：通“盍”，何不","本：王道、保民仁政。"],translation:"天下的土地，方圆千里的区域共有九块，齐国只占其中一块。凭一块土地去征服八块，和邹国对抗楚国有什么区别？何不回归王道的根本。"},{text:"今王发政施仁，使天下仕者皆欲立于王之朝，耕者皆欲耕于王之野，商贾皆欲藏于王之市，行旅皆欲出于王之涂，天下之欲疾其君者皆欲赴愬于王。其若是，孰能御之？”",annotations:["涂：通“途”","疾：憎恨","愬(sù)：通“诉”，申诉。"],translation:"如今大王推行仁政，让天下做官的人都想在您朝堂任职，农夫都想在齐国田野耕种，商人都想把货物存放在齐国集市，赶路的旅人都想从齐国道路通行，天下痛恨本国君主的百姓，都想来向您申诉。如果做到这样，谁能阻挡您统一天下？”"},{text:"王曰：“吾惛，不能进于是矣。愿夫子辅吾志，明以教我。我虽不敏，请尝试之。”",annotations:["惛(hūn)：糊涂","敏：聪慧。"],translation:"宣王说：“我头脑糊涂，达不到这种境界。希望先生辅佐我实现志向，清晰地教导我。我虽然愚钝，愿意试着施行仁政。”"},{text:"曰：“无恒产而有恒心者，惟士为能。若民，则无恒产，因无恒心。”",annotations:["恒产：固定赖以生存的产业","恒心：向善安分的心","惟：只有。"],translation:"孟子说：“没有固定产业，却保有向善之心，只有读书人能做到。至于普通百姓，没有固定产业，就不会有稳定的善心。"},{text:"苟无恒心，放辟邪侈，无不为已。及陷于罪，然后从而刑之，是罔民也。”",annotations:["苟：如果","放辟邪侈：放纵作恶、违法乱纪","刑：名作动，施加刑罚","罔：通“网”，陷害。"],translation:"如果没有向善之心，就会肆意作恶，什么坏事都做得出来。等到百姓犯了罪，再去施加刑罚，这是陷害百姓。"},{text:"焉有仁人在位，罔民而可为也？是故明君制民之产，必使仰足以事父母，俯足以畜妻子，乐岁终身饱，凶年免于死亡。然后驱而之善，故民之从之也轻。",annotations:["畜(xù)：养活","乐岁：丰年","凶年：荒年","轻：容易。"],translation:"哪里有仁君在位，却做出陷害百姓的事？所以圣明君主规定百姓的产业，一定让百姓上能奉养父母，下能养活妻儿，丰年全年温饱，荒年不至于饿死。再引导百姓向善，百姓就容易听从教化。"},{text:"今也制民之产，仰不足以事父母，俯不足以畜妻子，乐岁终身苦，凶年不免于死亡。此惟救死而恐不赡，奚暇治礼义哉？",annotations:["赡(shàn)：充足","奚暇：哪里有空余时间。"],translation:"如今给百姓划定的产业，上不足以赡养父母，下养活不了妻儿，丰年终年劳苦，荒年只能等死。百姓连保全性命都来不及，哪里有空学习礼义？"},{text:"王欲行之，则盍反其本矣：五亩之宅，树之以桑，五十者可以衣帛矣；鸡、豚、狗、彘之畜，无失其时，七十者可以食肉矣；百亩之田，勿夺其时，八口之家可以无饥矣；谨庠序之教，申之以孝悌之义，颁白者不负戴于道路矣。老者衣帛食肉，黎民不饥不寒，然而不王者，未之有也。”",annotations:["树：种植","衣(yì)：穿","豚彘：小猪、大猪","庠序：古代学校","申：反复教导","悌：尊敬兄长","颁：通“斑”","未之有：宾语前置，未有之，从来没有这种事。"],translation:"大王想要施行仁政，何不回归根本：每家五亩宅院，种上桑树，五十岁的老人就能穿上丝帛；鸡、猪、狗这类家畜，不错过繁殖时节，七十岁老人常有肉吃；每家百亩田地，不耽误耕种农时，八口之家不会挨饿；重视学校教化，反复宣讲孝顺父母、尊敬兄长，头发花白的老人不用在路上背负重物。老年人穿丝吃肉，百姓温饱无忧，这样还不能依靠王道统一天下，是从来没有过的事。"}]},13:{id:"13",title:"许行",source:"《孟子》",paragraphs:[{text:"有为神农之言者许行，自楚之滕。",annotations:["为：奉行","神农之言：农家学派主张，神农代表农耕","之：动词，到、前往。"],translation:"有个奉行神农农家学说的人叫许行，从楚国来到滕国。"},{text:"踵门而告文公曰：“远方之人，闻君行仁政，愿受一廛而为氓。”",annotations:["踵门：登门","廛(chán)：百姓住房","氓(méng)：外来百姓。"],translation:"他登门拜见滕文公说：“我从远方来，听说您施行仁政，希望能得到一处住所，做您的百姓。”"},{text:"文公与之处。",annotations:["与：给予","处：住所。"],translation:"滕文公给了他住处。"},{text:"其徒数十人，皆衣褐，捆屦织席以为食。",annotations:["衣(yì)：名作动，穿","褐：粗麻短衣","捆屦(jù)：敲打编织草鞋使其结实","以为食：靠此谋生。"],translation:"他的门徒有几十个人，全都穿着粗麻布短衣，靠编草鞋、织草席维持生计。"},{text:"陈良之徒陈相，与其弟辛，负耒耜而自宋之滕。",annotations:["陈良：楚国儒家学者","负：背着","耒(lěi)耜(sì)：古代耕地农具。"],translation:"儒家陈良的弟子陈相，和他弟弟陈辛，背着耕地农具从宋国来到滕国。"},{text:"曰：“闻君行圣人之政，是亦圣人也，愿为圣人氓。”",annotations:["是：此人，指滕文公。"],translation:"陈相对文公说：“听闻您施行圣人的仁政，您也就是圣人，我们愿意做圣人治下的百姓。”"},{text:"陈相见许行而大悦，尽弃其学而学焉。",annotations:["大悦：十分欢喜","弃其学：抛弃原先儒家学问","焉：代词，代许行的农家学说。"],translation:"陈相见到许行后十分高兴，完全抛弃自己原来所学的儒学，改向许行学习农家之道。"},{text:"陈相见孟子，道许行之言曰：“滕君，则诚贤君也；虽然，未闻道也。”",annotations:["道：转述","诚：确实","虽然：虽然如此","道：真正的圣人治国之道。"],translation:"陈相拜见孟子，转述许行的话说：“滕文公确实是贤明君主；即便这样，他还没有掌握圣人的大道。”"},{text:"贤者与民并耕而食，饔飧而治。",annotations:["并耕：一同耕种","饔(yōng)飧(sūn)：早餐、晚餐，此处名作动，自己做饭。"],translation:"圣明的君主应当和百姓一同耕种获取粮食，自己做饭，同时治理国家。"},{text:"今也，滕有仓廪府库，则是厉民而自养也，恶得贤！",annotations:["仓廪：粮仓","府库：储藏财货兵器的库房","厉：损害、剥削","恶(wū)：怎么。"],translation:"如今滕国有粮仓财库，这是剥削百姓来供养君主自己，怎么能算贤明！"},{text:"孟子曰：“许子必种粟而后食乎？”",annotations:["粟：谷物粮食。"],translation:"孟子问道：“许先生一定自己种粮食才吃饭吗？”"},{text:"曰：“然。”",annotations:["然：对，是的。"],translation:"陈相说：“没错。”"},{text:'"许子必织布然后衣乎？"',annotations:[],translation:"孟子又问：“许先生一定要自己织布之后才穿衣服吗？”"},{text:"曰：“否。许子衣褐。”",annotations:["褐：粗麻，无需织布染色。"],translation:"陈相说：“不是，许先生穿粗麻短衣。”"},{text:'"许子冠乎？"',annotations:["冠(guàn)：名作动，戴帽子。"],translation:"孟子问：“许先生戴帽子吗？”"},{text:"曰：“冠。”",annotations:[],translation:"陈相说：“戴。”"},{text:"曰：“奚冠？”",annotations:["奚冠：宾语前置，冠奚，戴什么帽子。"],translation:"孟子问：“戴什么帽子？”"},{text:"曰：“冠素。”",annotations:["素：白色生丝绢。"],translation:"陈相说：“戴白绢做的帽子。”"},{text:"曰：“自织之与？”",annotations:["与：通“欤”，语气词，吗。"],translation:"孟子问：“帽子是他自己织的吗？”"},{text:"曰：“否，以粟易之。”",annotations:["易：交换。"],translation:"陈相说：“不是，用粮食换的。”"},{text:"曰：“许子奚为不自织？”",annotations:["奚为：宾语前置，为何。"],translation:"孟子问：“许先生为什么不自己织布？”"},{text:"曰：“害于耕。”",annotations:["害：妨碍。"],translation:"陈相说：“会妨碍耕种。”"},{text:"曰：“许子以釜甑爨，以铁耕乎？”",annotations:["釜：铁锅","甑(zèng)：陶制蒸食器具","爨(cuàn)：做饭","铁：铁制农具。"],translation:"孟子问：“许先生用锅甑做饭，用铁器耕田吗？”"},{text:"曰：“然。”",annotations:[],translation:"陈相说：“是的。”"},{text:'"自为之与？"',annotations:[],translation:"孟子问：“这些器具是他自己打造的吗？”"},{text:"曰：“否，以粟易之。”",annotations:[],translation:"陈相说：“不是，用粮食交换来的。”"},{text:'"以粟易械器者，不为厉陶冶；陶冶亦以其械器易粟者，岂为厉农夫哉？"',annotations:["械器：锅、农具等器物","陶冶：制陶、打铁的工匠","厉：损害。"],translation:"孟子说：“农夫拿粮食换器具，不算剥削陶匠铁匠；陶匠铁匠拿器具换粮食，难道算是剥削农夫吗？”"},{text:"且许子何不为陶冶，舍皆取诸其宫中而用之？",annotations:["舍：止，不去交换","诸：之于","宫：此处指自家屋舍。"],translation:"况且许先生为什么不自己制陶打铁，所有器物都从自己家里取用？"},{text:"何为纷纷然与百工交易？",annotations:["纷纷然：忙碌不停的样子","百工：各类工匠。"],translation:"为什么还要忙碌地和各类工匠交换物品？"},{text:"何许子之不惮烦？",annotations:["惮(dàn)：害怕、嫌麻烦。"],translation:"许先生怎么这么不怕麻烦？"},{text:"曰：“百工之事，固不可耕且为也。”",annotations:["固：本来","耕且为：一边耕种一边做工。"],translation:"陈相说：“各类工匠的活计，本来就不可能一边耕种一边兼顾。”"},{text:'"然则治天下独可耕且为与？"',annotations:["独：偏偏","与：通“欤”。"],translation:"孟子说：“那治理天下偏偏就能一边耕种一边兼顾吗？”"},{text:"有大人之事，有小人之事。",annotations:["大人：统治者、君子","小人：底层百姓劳动者。"],translation:"世上有治理天下者的事务，也有普通百姓的劳作。"},{text:"且一人之身，而百工之所为备，如必自为而后用之，是率天下而路也。",annotations:["备：齐备","路：通“露”，疲于奔命。"],translation:"况且一个人的生活，需要各行各业工匠的产品才能齐备，如果每件东西都必须自己制作才使用，这是带领天下人终日奔波劳苦。"},{text:"故曰：或劳心，或劳力；劳心者治人，劳力者治于人；治于人者食人，治人者食于人，天下之通义也。",annotations:["或：有的人","治于人：被动句，被人治理","食(sì)：供养","通义：普遍道理。"],translation:"所以说：有的人操劳心智，有的人操劳体力；劳心的人治理百姓，劳力的人被百姓治理；被治理的人供养别人，治理人的人靠他人供养，这是天下通用的道理。"},{text:"当尧之时，天下犹未平，洪水横流，泛滥于天下，草木畅茂，禽兽繁殖，五谷不登，禽兽偪人。",annotations:["登：成熟丰收","偪(bī)：通“逼”，侵扰。"],translation:"尧在位的时候，天下还没有安定，洪水四处泛滥，草木疯长，禽兽大量繁衍，五谷无法成熟，野兽侵扰百姓。"},{text:"兽蹄鸟迹之道，交于中国。",annotations:["交：交错遍布","中国：中原地区。"],translation:"鸟兽足迹遍布中原大地。"},{text:"尧独忧之，举舜而敷治焉。",annotations:["敷治：全面治理。"],translation:"尧独自为此忧虑，举荐舜全面治理天下。"},{text:"舜使益掌火，益烈山泽而焚之，禽兽逃匿。",annotations:["益：舜的臣子","烈：名作动，放火焚烧。"],translation:"舜派益掌管火政，益放火烧毁山野沼泽的草木，鸟兽都四处躲藏。"},{text:"禹疏九河，瀹济漯而注诸海；决汝汉，排淮泗，而注之江，然后中国可得而食也。",annotations:["瀹(yuè)：疏通","注诸海：使之流入大海","决、排：开凿疏导。"],translation:"大禹疏通九条大河，疏导济水、漯水使之入海；开凿汝水、汉水，疏通淮河、泗水，导入长江，中原百姓才能够耕种谋生。"},{text:"当是时也，禹八年于外，三过其门而不入，虽欲耕，得乎？",annotations:["得乎：办得到吗。"],translation:"在那个时候，大禹在外治水八年，多次路过自家大门都不进去，就算他想亲自耕种，办得到吗？"},{text:"后稷教民稼穑，树艺五谷；五谷熟，而民人育。",annotations:["稼穑：耕种收获","树艺：种植","育：得以生存繁衍。"],translation:"后稷教导百姓农耕，种植各类谷物；谷物成熟，百姓才能得以生存。"},{text:"人之有道也，饱食、暖衣、逸居而无教，则近于禽兽。",annotations:["逸居：安逸居住","教：教化礼义。"],translation:"人有生存的常理，如果吃饱穿暖、安居度日却没有教化，就和禽兽相差无几。"},{text:"圣人有忧之，使契为司徒，教以人伦：父子有亲，君臣有义，夫妇有别，长幼有序，朋友有信。",annotations:["契(xiè)：舜时司徒","人伦：人与人的伦理关系。"],translation:"圣人又为此忧虑，派契担任司徒，教导百姓人伦道义：父子要有亲情，君臣要有道义，夫妇内外有别，长幼尊卑有序，朋友相处守信。"},{text:"放勋曰：“劳之来之，匡之直之，辅之翼之，使自得之，又从而振德之。”",annotations:["放勋：尧的名号","劳、来：慰劳安抚","匡、直：纠正品行","辅、翼：扶持","振：通“赈”，救济。"],translation:"尧说：“慰劳安抚百姓，纠正他们的过失，扶持帮助他们，让他们自觉守住本性，再持续施以恩惠救济。”"},{text:"圣人之忧民如此，而暇耕乎？",annotations:["暇：空闲","而暇耕乎：哪里还有空闲耕种？（节选截止句）。"],translation:"圣人为百姓操心操劳到这种地步，哪里还有空闲亲自耕种呢？"}]},14:{id:"14",title:"劝学",source:"《荀子》",paragraphs:[{text:"君子曰：学不可以已。",annotations:["君子：有学问、有修养的人","已：停止。"],translation:"君子说：学习是不可以停止的。"},{text:"青，取之于蓝，而青于蓝。",annotations:["蓝：蓝草，可作染料","状语后置，从蓝草提取，却比蓝草更青。"],translation:"靛青从蓝草中提取，却比蓝草的颜色更深。"},{text:"冰，水为之，而寒于水。",annotations:["为：凝结而成","寒于水：比水更寒冷。"],translation:"冰是水凝结成的，却比水更寒凉。"},{text:"木直中绳，輮以为轮，其曲中规。",annotations:["中(zhòng)：合乎","绳：墨线","輮(róu)：通“煣”，用火烘烤使木材弯曲","规：圆规。"],translation:"木材笔直，合乎墨线，用火烘烤把它弯成车轮，它弯曲的弧度符合圆规画的圆圈。"},{text:"虽有槁暴，不复挺者，輮使之然也。",annotations:["槁(gǎo)：枯干","暴(pù)：晒","挺：直","然：这样。"],translation:"即使又晒干了，也不会再挺直，是火烤弯曲的工艺让它变成这样。"},{text:"故木受绳则直，金就砺则利。",annotations:["金：金属制刀剑","就：靠近","砺：磨刀石","利：锋利。"],translation:"所以木材经墨线量过就能取直，金属刀剑靠近磨刀石打磨就会锋利。"},{text:"君子博学而日参省乎己，则知明而行无过矣。",annotations:["博学：广泛学习","日：名作状，每天","参省(xǐng)：检验反省","知：通“智”，智慧","过：过错。"],translation:"君子广泛学习，并且每天对自己检验反省，就智慧明达，行为没有过错。"},{text:"故不登高山，不知天之高也；不临深溪，不知地之厚也；不闻先王之遗言，不知学问之大也。",annotations:["溪：山谷。","先王：前代的圣明君主。","遗言：古训，训诫。"],translation:"因此，不登上高山，就不知道天多么高；不面临深谷，就不知道地多么厚；不懂得前代圣明君主的古训，就不知道学问的博大。"},{text:"干越夷貉之子，生而同声，长而异俗，教使之然也。",annotations:["然：这样。"],translation:"干、越、夷、貉的婴儿，生下来时啼哭的声音都相同，而长大后风俗习性却不相同，这是教育使他们这样的。"},{text:'《诗》曰："嗟尔君子，无恒安息。靖共尔位，好是正直。神之听之，介尔景福。"',annotations:["嗟：感叹词。","尔：你们。",'无：通"毋"，不要。',"恒：常。息：歇息。",'靖：通"静"。','共：通"供"，指供职。',"好：喜爱。","正直：正直的人。","神：天神。",'之：前一个是连词，后一个是代词，指"靖共尔位，好是正直"。',"听：听察，闻知。","介：给予。","景：大。"],translation:'《诗经》上说："你们这些君子啊，不要常常安然地歇息。安心地供职，喜爱这正直的人。天神听察这一切，就会给予你大的福气。"'},{text:"神莫大于化道，福莫长于无祸。",annotations:["神：精神修养。",'化道：等于说"化于道"，指学有所得。',"化：变化。","道：圣贤之道。",'长：意思与"大"相近。',"无祸：指自身修养。"],translation:"精神修养没有比学有所得更大了，福分没有比自身修养更大了。"},{text:"吾尝终日而思矣，不如须臾之所学也。",annotations:["尝：曾经","须臾(yú)：片刻、短暂时间。"],translation:"我曾经整天空想，比不上片刻学习收获大。"},{text:"吾尝跂而望矣，不如登高之博见也。",annotations:["跂(qǐ)：踮起脚后跟","博见：看见更广远的景象。"],translation:"我曾经踮起脚跟远望，比不上登上高处看得广阔。"},{text:"登高而招，臂非加长也，而见者远。",annotations:["招：挥手","加长：变长。"],translation:"登上高处挥手，手臂没有加长，可是远处的人能看见。"},{text:"顺风而呼，声非加疾也，而闻者彰。",annotations:["疾：洪亮","彰：清楚。"],translation:"顺着风呼喊，声音没有变得洪亮，听的人却听得十分清楚。"},{text:"假舆马者，非利足也，而致千里。",annotations:["假：借助、利用","舆马：车马","利足：善于行走","致：到达。"],translation:"借助车马远行的人，不是脚擅长走路，却能到达千里之外。"},{text:"假舟楫者，非能水也，而绝江河。",annotations:["舟楫：船只","水：名作动词，游泳","绝：横渡。"],translation:"借助船只出行的人，不是擅长游泳，却能横渡长江黄河。"},{text:"君子生非异也，善假于物也。",annotations:["生(xìng)：通“性”，天赋、禀赋","物：外物，各类客观条件。"],translation:"君子的天赋同普通人没有差别，只是善于借助外物罢了。"},{text:"积土成山，风雨兴焉。",annotations:["焉：于此，从这里兴起。"],translation:"堆积泥土成为高山，风雨就从这里兴起。"},{text:"积水成渊，蛟龙生焉。",annotations:["渊：深水潭。"],translation:"汇集水流成为深潭，蛟龙就生长在这里。"},{text:"积善成德，而神明自得，圣心备焉。",annotations:["善：善行","神明：智慧、精神境界","圣心：圣人的修养。"],translation:"积累善行养成高尚品德，自然获得超凡智慧，具备圣人的心境。"},{text:"故不积跬步，无以至千里。",annotations:["跬(kuǐ)步：半步","无以：没有用来……的办法。"],translation:"所以不积累半步的行程，就没有办法到达千里远的地方。"},{text:"不积小流，无以成江海。",annotations:[],translation:"不汇集细小水流，无法形成大江大海。"},{text:"骐骥一跃，不能十步。",annotations:["骐骥(qí jì)：骏马","跃：跳跃。"],translation:"骏马一次跳跃，也达不到十步远。"},{text:"驽马十驾，功在不舍。",annotations:["驽(nú)马：劣马","十驾：马拉车走十天路程","舍：停止、舍弃。"],translation:"劣马拉车走十天也能走远，它的成功在于不停下。"},{text:"锲而舍之，朽木不折。",annotations:["锲(qiè)：雕刻","舍：中途放弃。"],translation:"雕刻几下就放弃，腐朽的木头也刻不断。"},{text:"锲而不舍，金石可镂。",annotations:["镂(lòu)：雕刻镂空。"],translation:"坚持雕刻不停止，金属、石头都能雕刻出花纹。"},{text:"蚓无爪牙之利，筋骨之强，上食埃土，下饮黄泉，用心一也。",annotations:["定语后置：利之爪牙，强之筋骨","上、下：名作状，向上、向下","黄泉：地下泉水","一：专一。"],translation:"蚯蚓没有锋利的爪牙、强健的筋骨，却能向上吃泥土，向下饮地下水，是心思专一的缘故。"},{text:"蟹六跪而二螯，非蛇鳝之穴无可寄托者，用心躁也。",annotations:["跪：蟹腿","螯(áo)：蟹钳","寄托：藏身","躁：浮躁不专一。"],translation:"螃蟹有六条腿两只蟹钳，如果没有蛇、鳝的洞穴就无处藏身，是心思浮躁不专一的缘故。"},{text:"是故无冥冥之志者，无昭昭之明；无惛惛之事者，无赫赫之功。",annotations:["冥冥：潜心埋头","昭昭：明晰通透","惛惛(hūn)：默默苦干","赫赫：显赫盛大。"],translation:"所以没有潜心钻研的志向，就不会有明辨事理的智慧；不能埋头苦干做事，就不会有显赫出众的功业。"},{text:"行衢道者不至，事两君者不容。",annotations:["衢(qú)道：四通八达的岔路","容：容纳、接纳。"],translation:"走上岔路徘徊不定的人，到不了目的地；同时侍奉两位君主的人，不会被任何一方接纳。"},{text:"目不能两视而明，耳不能两听而聪。",annotations:["明：看清事物","聪：听清声音。"],translation:"眼睛不能同时看两样东西还看得清楚，耳朵不能同时听两种声音还听得明晰。"},{text:"螣蛇无足而飞，鼫鼠五技而穷。",annotations:["螣(téng)蛇：传说中能飞的神蛇","鼫(shí)鼠：鼠类，有五种技能却样样粗浅","穷：困窘无用。"],translation:"螣蛇没有脚却能腾空飞翔，鼫鼠有五种技艺却处处困窘。"},{text:"《诗》曰：“尸鸠在桑，其子七兮。淑人君子，其仪一兮。其仪一兮，心如结兮。”",annotations:["尸鸠：布谷鸟","淑人：善人","仪：举止操守","结：凝聚专一。"],translation:"《诗经》说：布谷鸟筑巢在桑树，哺育七只小鸟公平如一。善人君子，举止操守始终专一。举止专一，内心坚定凝聚不散。"},{text:"故君子结于一也。",annotations:["结于一：心志凝聚、专一不二（节选结束句）。"],translation:"所以君子学习做事，心志都凝聚专一。"}]},15:{id:"15",title:"谏逐客书",source:"李斯",paragraphs:[{text:"臣闻吏议逐客，窃以为过矣。",annotations:["窃：私下，谦辞","过：错误。"],translation:"我听说朝中大臣商议驱逐客卿，我私下认为这是错误的。"},{text:"昔穆公求士，西取由余于戎，东得百里奚于宛，迎蹇叔于宋，来邳豹、公孙支于晋。",annotations:["穆公：秦穆公","由余：戎国贤臣","百里奚、蹇叔、邳豹、公孙支：皆他国入秦贤才","来：使动，使……来归附","状语后置：于戎取由余。"],translation:"从前秦穆公广求贤士，向西从戎地招揽由余，向东从宛地得到百里奚，从宋国迎来蹇叔，从晋国招来邳豹、公孙支。"},{text:"此五子者，不产于秦，而穆公用之，并国二十，遂霸西戎。",annotations:["产：出生","并：吞并","霸西戎：称霸西戎各部。"],translation:"这五位贤才，都不是秦国土生土长，可秦穆公重用他们，吞并二十个小国，于是称霸西戎。"},{text:"孝公用商鞅之法，移风易俗，民以殷盛，国以富强，百姓乐用，诸侯亲服，获楚、魏之师，举地千里，至今治强。",annotations:["孝公：秦孝公","商鞅：卫国人，变法名臣","殷盛：富足兴盛","乐用：乐于为国效力","举：攻取","治强：安定强盛。"],translation:"秦孝公采用商鞅的新法，改变旧风俗旧习气，百姓因此富足兴旺，国家因此富裕强大，百姓愿意为国出力，诸侯亲近臣服，战胜楚、魏两国军队，夺取千里土地，直到今天秦国依旧安定强盛。"},{text:"惠王用张仪之计，拔三川之地，西并巴、蜀，北收上郡，南取汉中，包九夷，制鄢、郢，东据成皋之险，割膏腴之壤，遂散六国之从，使之西面事秦，功施到今。",annotations:["惠王：秦惠文王","张仪：魏人，纵横家","拔：攻取","包：囊括","制：控制","从：通“纵”，合纵联盟","西面：面朝西","施(yì)：延续。"],translation:"秦惠王采纳张仪的计策，攻取三川地区，向西吞并巴蜀，向北收取上郡，向南夺取汉中，囊括众多夷族之地，控制鄢、郢楚都，东边占据成皋险要之地，分割肥沃土地，瓦解六国合纵盟约，让各国面朝西侍奉秦国，功业一直延续到今天。"},{text:"昭王得范雎，废穰侯，逐华阳，强公室，杜私门，蚕食诸侯，使秦成帝业。",annotations:["昭王：秦昭襄王","范雎：魏人","穰侯、华阳：秦王外戚，把持私权","强：使动，加强","杜：堵塞","私门：权贵豪门","蚕食：名作状，像蚕吃桑叶一样逐步侵占。"],translation:"秦昭王得到范雎，废除穰侯的权势，驱逐华阳君，强化王室权力，杜绝权贵私门势力，逐步侵占诸侯土地，使秦国成就帝王基业。"},{text:"此四君者，皆以客之功。",annotations:["以：依靠、凭借。"],translation:"这四位君主，都是依靠客卿建立功业。"},{text:"由此观之，客何负于秦哉？",annotations:["负：辜负","状语后置，于秦负。"],translation:"从这点来看，客卿哪里辜负过秦国？"},{text:"向使四君却客而不内，疏士而不用，是使国无富利之实，而秦无强大之名也。",annotations:["向使：假使","却：使动，拒绝","内：通“纳”，接纳","疏：疏远。"],translation:"假使这四位君主拒绝客卿、不接纳贤才，疏远士人不加任用，只会让国家没有富足实惠，秦国也不会有强大的名声。"},{text:"今陛下致昆山之玉，有随和之宝，垂明月之珠，服太阿之剑，乘纤离之马，建翠凤之旗，树灵鼍之鼓。",annotations:["致：求得","随和：随侯珠、和氏璧","服：佩戴","建、树：树立、陈设","灵鼍(tuó)：扬子鳄，皮可制鼓。"],translation:"如今陛下得到昆仑山美玉，拥有随侯珠、和氏璧，悬挂明月宝珠，佩戴太阿宝剑，乘坐纤离宝马，树立翠凤纹饰旌旗，陈设灵鼍皮制成的大鼓。"},{text:"此数宝者，秦不生一焉，而陛下说之，何也？",annotations:["生：出产","说：通“悦”，喜爱。"],translation:"这几件宝物，没有一件产自秦国，可陛下十分喜爱它们，为什么呢？"},{text:"必秦国之所生然后可，则是夜光之璧不饰朝廷，犀象之器不为玩好，郑、卫之女不充后宫，而骏良駃騠不实外厩，江南金锡不为用，西蜀丹青不为采。",annotations:["玩好：赏玩器物","駃騠(jué tí)：骏马","厩(jiù)：马棚","丹青：颜料","采：采用、彩绘。"],translation:"如果一定要秦国出产的东西才可以使用，那么夜光玉璧就不能装饰朝堂，犀角象牙器物不能当作赏玩珍品，郑国、卫国美女不能充实后宫，骏马不能养在宫外马棚，江南的金属锡矿不能使用，西蜀的颜料不能拿来彩绘。"},{text:"所以饰后宫、充下陈、娱心意、说耳目者，必出于秦然后可，则是宛珠之簪、傅玑之珥、阿缟之衣、锦绣之饰不进于前，而随俗雅化佳冶窈窕赵女不立于侧也。",annotations:["下陈：堂下侍妾","傅玑：镶嵌小珠","珥：耳环","阿缟：齐国细绢","佳冶窈窕：艳丽秀美。"],translation:"用来装饰后宫、充实侍妾队伍、愉悦身心、悦耳悦目的物品，如果必须产自秦国才可用，那么宛地珍珠发簪、镶珠耳环、齐国绢衣、锦绣饰物就不能进献到您面前，那些随风俗打扮、艳丽秀美的赵国女子也不能侍立在您身旁。"},{text:"夫击瓮叩缶，弹筝搏髀，而歌呼呜呜快耳者，真秦之声也。",annotations:["瓮、缶：瓦器","搏髀(bì)：拍打大腿","快耳：使耳朵畅快。"],translation:"敲打瓦瓮瓦罐，弹古筝、拍大腿，呜呜歌唱让人听着痛快，这才是纯正秦国本土音乐。"},{text:"《郑》《卫》《桑间》，《昭》《虞》《武》《象》者，异国之乐也。",annotations:["郑卫桑间：郑、卫民间乐曲","昭虞武象：上古帝王雅乐，非秦本土乐曲。"],translation:"《郑》《卫》《桑间》以及《昭》《虞》《武》《象》这类乐曲，都是别国的音乐。"},{text:"今弃击瓮叩缶而就《郑》《卫》，退弹筝而取《昭》《虞》，若是者何也？",annotations:["就：取用、选用","退：摒弃。"],translation:"如今陛下舍弃本土瓦器乐曲，选用郑卫之乐，抛开古筝取用上古雅乐，这么做是为什么？"},{text:"快意当前，适观而已矣。",annotations:["适观：适合观赏，赏心悦目。"],translation:"不过是眼前能使人舒心，适合观赏罢了。"},{text:"今取人则不然，不问可否，不论曲直，非秦者去，为客者逐。",annotations:["曲直：是非对错","去：驱逐离开。"],translation:"可选用人才却不是这样，不问是否可用、不论是非对错，不是秦国人就赶走，凡是客卿一律驱逐。"},{text:"然则是所重者在乎色、乐、珠玉，而所轻者在乎人民也。",annotations:["重：看重","轻：轻视。"],translation:"这样看来，陛下看重的是美色、乐曲、珠宝美玉，轻视的却是百姓人才。"},{text:"此非所以跨海内、制诸侯之术也。",annotations:["跨海内：驾驭天下","术：治国方法。"],translation:"这不是能统一天下、制服诸侯的治国办法。"},{text:"臣闻地广者粟多，国大者人众，兵强则士勇。",annotations:[],translation:"我听说土地广阔粮食就充足，国家广大百姓就众多，军队强盛士兵就勇敢。"},{text:"是以泰山不让土壤，故能成其大；河海不择细流，故能就其深；王者不却众庶，故能明其德。",annotations:["让：拒绝","择：舍弃","却：使动，推拒","众庶：百姓","明：使动，彰显。"],translation:"因此泰山不拒绝微小泥土，才能成就高大；河海不放弃细小水流，才能造就深邃；称王之人不推拒百姓，才能彰显恩德。"},{text:"是以地无四方，民无异国，四时充美，鬼神降福，此五帝三王之所以无敌也。",annotations:["四时：四季物产","五帝三王：上古贤君","无敌：天下无人能抗衡。"],translation:"所以土地不分东西南北，百姓不分本国他国，四季物产丰足，鬼神降下福运，这就是五帝、三王天下无敌的原因。"},{text:"今乃弃黔首以资敌国，却宾客以业诸侯，使天下之士退而不敢西向，裹足不入秦，此所谓藉寇兵而赍盗粮者也。",annotations:["黔首：百姓","资：资助","业：使动，成就功业","藉(jiè)：借","赍(jī)：赠送。"],translation:"如今您抛弃百姓去资助敌国，驱逐客卿去成全诸侯功业，天下贤士退缩不敢向西而来，止步不踏入秦国，这就是所说的借给敌人兵器、送给盗贼粮食。"},{text:"夫物不产于秦，可宝者多；士不产于秦，而愿忠者众。",annotations:["宝：名作动词，当作珍宝。"],translation:"物品不产自秦国，值得珍视的有很多；贤士不生在秦国，愿意效忠秦国的也有很多。"},{text:"今逐客以资敌国，损民以益仇，内自虚而外树怨于诸侯，求国无危，不可得也。",annotations:["损、益：减少、增益","自虚：使自身国力空虚","树怨：结下仇怨。"],translation:"如今驱逐客卿去资助敌国，减少本国百姓来增强仇敌力量，对内让国力空虚，对外和诸侯结怨，想要国家没有危难，是不可能做到的。"}]},16:{id:"16",title:"论贵粟疏",source:"晁错",paragraphs:[{text:"圣王在上，而民不冻饥者，非能耕而食之，织而衣之也，为开其资财之道也。",annotations:["食(sì)：使动，给……吃","衣(yì)：使动，给……穿","资财之道：获取物资财富的途径。"],translation:"圣明的君主身居上位，百姓却不受冻挨饿，不是君主能亲自耕种给百姓粮食、织布给百姓衣物，而是能为百姓开辟获取财物的门路。"},{text:"故尧、禹有九年之水，汤有七年之旱，而国亡捐瘠者，以畜积多而备先具也。",annotations:["亡：通“无”","捐瘠：被抛弃、饿死的人","畜：通“蓄”，储备","备先具：事先备好救灾物资。"],translation:"所以尧、禹时有九年大水，商汤时有七年大旱，国内却没有饿死、流离的百姓，是因为粮食储备充足，救灾物资早就准备好了。"},{text:"今海内为一，土地人民之众不避汤、禹，加以亡天灾数年之水旱，而畜积未及者，何也？",annotations:["海内为一：天下统一","不避：不亚于","亡：通“无”。"],translation:"如今天下统一，土地、人口数量不比商汤、大禹时期少，又没有连续多年的水旱天灾，可粮食储备却比不上古时，是什么缘故？"},{text:"地有遗利，民有余力，生谷之土未尽垦，山泽之利未尽出也，游食之民未尽归农也。",annotations:["遗利：未开发的潜力","游食之民：不务农、四处游荡谋生的人。"],translation:"土地还有未开发的潜力，百姓还有富余劳动力，能种粮食的田地没有全部开垦，山林湖泽的资源没有全部开发，不事农耕的游民没有全部回乡务农。"},{text:"民贫，则奸邪生。",annotations:["奸邪：违法作乱的事。"],translation:"百姓一旦贫穷，违法作乱的事就会滋生。"},{text:"贫生于不足，不足生于不农，不农则不地著，不地著则离乡轻家，民如鸟兽。",annotations:["地著(zhuó)：定居一地，依附土地","轻家：不看重家园。"],translation:"贫穷来自物资不足，物资不足源于不从事农耕；不务农就不会定居乡土，不安土重家就会轻易离开故乡，百姓就像鸟兽一样四处离散。"},{text:"虽有高城深池，严法重刑，犹不能禁也。",annotations:["池：护城河","犹：仍然。"],translation:"就算有高大城墙、深深护城河，严苛的法令、沉重刑罚，也无法禁止百姓流亡作乱。"},{text:"夫寒之于衣，不待轻暖；饥之于食，不待甘旨；饥寒至身，不顾廉耻。",annotations:["轻暖：华贵保暖衣物","甘旨：美味佳肴。"],translation:"人寒冷时，不奢求华贵暖和的衣服；饥饿时，不追求美味食物；饥寒缠身，就顾不上廉耻道义。"},{text:"人情，一日不再食则饥，终岁不制衣则寒。",annotations:["再食：吃两顿饭","终岁：一整年。"],translation:"人之常情，一天吃不上两顿饭就会饥饿，整年不做新衣就会受寒。"},{text:"夫腹饥不得食，肤寒不得衣，虽慈母不能保其子，君安能以有其民哉？",annotations:["安：怎么","有其民：保有、治理好百姓。"],translation:"肚子饿却没有粮食，身上冷却没有衣服，就算慈祥母亲也保全不了子女，君主又怎么能保有自己的百姓？"},{text:"明主知其然也，故务民于农桑，薄赋敛，广畜积，以实仓廪，备水旱，故民可得而有也。",annotations:["务：使……专心从事","薄赋敛：减轻赋税","仓廪：粮仓。"],translation:"圣明君主明白这个道理，所以引导百姓专心农耕养蚕，减轻赋税，广积粮食，充实粮仓，防备水旱灾害，因此才能安稳治理百姓。"},{text:"民者，在上所以牧之，趋利如水走下，四方无择也。",annotations:["牧：治理、管理","走下：流向低处。"],translation:"百姓，是君主所要管理的对象，百姓追逐利益就像水往低处流，不会挑选方向。"},{text:"夫珠玉金银，饥不可食，寒不可衣，然而众贵之者，以上用之故也。",annotations:["贵：意动，以……为贵重","上：朝廷、君主。"],translation:"珍珠、美玉、黄金白银，饿了不能充饥，冷了不能御寒，可众人都看重它们，是因为君主朝廷使用它们。"},{text:"其为物轻微易藏，在于把握，可以周海内而亡饥寒之患。",annotations:["把握：握在手中","周海内：走遍天下","亡：通“无”。"],translation:"这类东西轻巧细小容易收藏，握在手里，走遍天下都不用担心饥寒。"},{text:"此令臣轻背其主，而民易去其乡，盗贼有所劝，亡逃者得轻资也。",annotations:["背：背叛","劝：鼓励、引诱","轻资：轻便的随身财物。"],translation:"这就会让臣子轻易背叛君主，百姓轻易离开家乡，盗贼受到诱惑，逃亡之人能携带轻便财物。"},{text:"粟米布帛生于地，长于时，聚于力，非可一日成也。",annotations:["长于时：随时节生长","聚于力：靠人力收获储藏。"],translation:"粮食、布匹从土地产出，随时节生长，靠人力收获，不是一天就能得到。"},{text:"数石之重，中人弗胜，不为奸邪所利，一日弗得而饥寒至。",annotations:["石(dàn)：粮食计量单位","中人弗胜：普通人搬不动","利：利用、觊觎。"],translation:"几石粮食十分沉重，普通人难以搬运，不会被坏人轻易利用；可一天没有粮食，饥寒立刻降临。"},{text:"是故明君贵五谷而贱金玉。",annotations:["贵、贱：意动，以粮食为贵，以金玉为贱。"],translation:"因此圣明君主看重五谷粮食，轻视金玉珠宝。"},{text:"今农夫五口之家，其服役者不下二人，其能耕者不过百亩，百亩之收不过百石。",annotations:["服役：服官府徭役","石：计量单位。"],translation:"如今普通农户五口之家，去服徭役的不少于两人，能耕种的田地不超过百亩，百亩田地收成不过百石粮食。"},{text:"春耕，夏耘，秋获，冬藏，伐薪樵，治官府，给徭役。",annotations:["耘：除草","薪樵：柴草","治官府：修缮官府建筑。"],translation:"春天耕种，夏天除草，秋天收割，冬天储藏，还要砍柴，修缮官府房屋，供给官府徭役。"},{text:"春不得避风尘，夏不得避暑热，秋不得避阴雨，冬不得避寒冻，四时之间，亡日休息。",annotations:["四时：四季","亡：通“无”。"],translation:"春天不能躲避风沙尘土，夏天不能躲避酷暑，秋天不能躲避阴雨，冬天不能躲避严寒，一年四季，没有一天休息。"},{text:"又私自送往迎来，吊死问疾，养孤长幼在其中。",annotations:["吊死：吊唁死者","长(zhǎng)：抚育长大。"],translation:"私下还要应酬亲友往来，吊唁死者、慰问病人，抚养孤儿、养育孩童，开销都从这份收成里出。"},{text:"勤苦如此，尚复被水旱之灾，急政暴虐，赋敛不时，朝令而暮改。",annotations:["被：遭受","不时：不按固定时节征收。"],translation:"如此辛勤劳苦，还要遭受水旱灾害，官府政令严苛残暴，赋税征收没有定时，早上下达政令，傍晚就更改。"},{text:"当具，有者半贾而卖，亡者取倍称之息，于是有卖田宅、鬻子孙以偿责者矣。",annotations:["具：准备赋税","贾：通“价”","倍称之息：翻倍的利息","鬻(yù)：卖","责：通“债”。"],translation:"到要缴纳赋税时，有粮食的只能半价贱卖，没有粮食的只能借高利贷；于是就有人变卖田地房屋、卖掉子女偿还债务。"},{text:"而商贾大者积贮倍息，小者坐列贩卖，操其奇赢，日游都市，乘上之急，所卖必倍。",annotations:["商贾(gǔ)：商人","奇赢：囤积稀有货物牟取暴利","乘上之急：趁朝廷急需物资时抬价。"],translation:"大商人囤积货物收取翻倍利息，小商人摆摊贩卖，囤积稀有货物牟取暴利，天天游走集市，趁官府急需物资，卖出价格必定翻一倍。"},{text:"故其男不耕耘，女不蚕织，衣必文采，食必粱肉，亡农夫之苦，有仟伯之得。",annotations:["文采：华丽丝织衣物","粱肉：精米肉食","仟伯：通“阡陌”，代指田地般丰厚收入。"],translation:"商人家中男子不耕种，女子不养蚕织布，穿的一定是华丽绸缎，吃的一定是精米肉食，没有农夫的劳苦，却拥有田地般丰厚收入。"},{text:"因其富厚，交通王侯，力过吏势，以利相倾。",annotations:["交通：结交、攀附","相倾：互相竞争倾轧。"],translation:"凭借丰厚财富，攀附结交王侯，势力超过地方官吏，依靠财力互相倾轧攀比。"},{text:"千里游敖，冠盖相望，乘坚策肥，履丝曳缟。",annotations:["游敖：遨游游玩","冠盖：车马服饰","坚：坚固好车","肥：肥壮马匹","曳缟：披着丝绢长衣。"],translation:"千里四处游玩，车马络绎不绝，乘坐坚固豪车，驾驭肥壮骏马，脚穿丝鞋，身披绢衣。"},{text:"此商人所以兼并农人，农人所以流亡者也。",annotations:["兼并：侵夺、盘剥。"],translation:"这就是商人盘剥农民、农民流离失所的原因。"},{text:"今法律贱商人，商人已富贵矣；尊农夫，农夫已贫贱矣。",annotations:["贱、尊：使动，轻视、推崇。"],translation:"如今法律虽然轻视商人，商人却已经富贵；法律推崇农夫，农夫却十分贫贱。"},{text:"故俗之所贵，主之所贱也；吏之所卑，法之所尊也。",annotations:[],translation:"所以世俗看重的商人，却是君主法令轻视的；官吏鄙夷的农夫，却是法律推崇的。"},{text:"上下相反，好恶乖迕，而欲国富法立，不可得也。",annotations:["乖迕(wǔ)：相互违背、矛盾。"],translation:"朝廷与民间标准相反，喜好厌恶相互矛盾，还想让国家富足、法令有效施行，是不可能做到的。"},{text:"方今之务，莫若使民务农而已矣。",annotations:["方今之务：当下最要紧的事。"],translation:"当下最要紧的事，没有比引导百姓专心务农更重要的了。"},{text:"欲民务农，在于贵粟；贵粟之道，在于使民以粟为赏罚。",annotations:["贵粟：提高粮食地位、抬高粮价","以粟为赏罚：用粮食作为奖赏、赎罪的依据。"],translation:"想要百姓专心务农，关键在于重视粮食；重视粮食的办法，就是让粮食可以用来获取奖赏、抵免刑罚。"},{text:"今募天下入粟县官，得以拜爵，得以除罪。",annotations:["县官：汉代代指朝廷官府","拜爵：授予爵位","除罪：减免罪责。"],translation:"如今号召天下百姓向官府缴纳粮食，缴纳粮食可以授予爵位，可以减免罪行。"},{text:"如此，富人有爵，农民有钱，粟有所渫。",annotations:["渫(xiè)：流通、分散。"],translation:"这样一来，富人能得到爵位，农民能卖出粮食获利，粮食能够流通分散。"},{text:"夫能入粟以受爵，皆有余者也。",annotations:[],translation:"能拿出粮食换取爵位的，都是家中粮食富余的人。"},{text:"取于有余，以供上用，则贫民之赋可损，所谓损有余，补不足，令出而民利者也。",annotations:["损：减少","损有余补不足：从富余者收取物资，补给贫困百姓。"],translation:"从粮食富余者手中收取粮食，供给朝廷使用，贫民的赋税就能减轻，这就是削减富余、补给不足，政令一出百姓就能获利。"},{text:"顺于民心，所补者三：一曰主用足，二曰民赋少，三曰劝农功。",annotations:["劝农功：鼓励农耕劳作。"],translation:"顺应百姓心意，有三重好处：第一，朝廷物资充足；第二，百姓赋税减轻；第三，鼓励百姓从事农业。"},{text:"今令民有车骑马一匹者，复卒三人。",annotations:["车骑马：战车战马","复卒：免除三人的兵役。"],translation:"现行法令：百姓家中有一匹战马的，可免除三个人的兵役。"},{text:"车骑者，天下武备也，故为复卒。",annotations:["武备：军事装备。"],translation:"战马是国家军备物资，所以以此免除兵役。"},{text:"神农之教曰：“有石城十仞，汤池百步，带甲百万，而亡粟，弗能守也。”",annotations:["仞：古代高度单位","汤池：灌满沸水的护城河","带甲：士兵","亡：通“无”。"],translation:"神农留下教诲：就算有十仞高石头城墙，百步宽沸水护城河，百万披甲士兵，没有粮食，城池一定守不住。"},{text:"以是观之，粟者，王者大用，政之本务。",annotations:["大用：最重要的物资","本务：治国根本要务。"],translation:"由此来看，粮食是君主最重要的物资，是治国理政的根本。"},{text:"令民入粟受爵，至五大夫以上，乃复一人耳，此其与骑马之功相去远矣。",annotations:["五大夫：汉代爵位等级","相去：差距。"],translation:"百姓缴纳粮食换取爵位，到五大夫以上，才免除一人兵役，这份好处比拥有战马的优待差很多。"},{text:"爵者，上之所擅，出于口而亡穷；粟者，民之所种，生于地而不乏。",annotations:["擅：专有、掌控","亡穷：没有穷尽。"],translation:"爵位，是君主独有的，君主一句话就能授予，无穷无尽；粮食，是百姓耕种出来的，从土地源源不断产出。"},{text:"夫得高爵与免罪，人之所甚欲也。",annotations:["甚欲：十分渴求。"],translation:"获得高爵位、减免罪责，是人人十分渴求的事。"},{text:"使天下人入粟于边，以受爵免罪，不过三岁，塞下之粟必多矣。",annotations:["塞下：边境要塞","三岁：三年。"],translation:"让天下百姓向边境粮仓缴纳粮食，换取爵位、减免罪责，不出三年，边境储备的粮食一定会十分充足。"}]},17:{id:"17",title:"鸿门宴",source:"《史记》",paragraphs:[{text:"沛公军霸上，未得与项羽相见。",annotations:["军：名词作动词，驻军","沛公：刘邦","霸上：地名。"],translation:"刘邦驻军在霸上，还没能和项羽相见。"},{text:"沛公左司马曹无伤使人言于项羽曰：“沛公欲王关中，使子婴为相，珍宝尽有之。”",annotations:["言于项羽：状语后置，向项羽报告","王(wàng)：称王","子婴：秦末代君主","尽：全部。"],translation:"刘邦的左司马曹无伤派人对项羽说：刘邦想要在关中称王，让秦王子婴做丞相，把所有珍宝都占为己有。"},{text:"项羽大怒曰：“旦日飨士卒，为击破沛公军！”",annotations:["旦日：第二天","飨(xiǎng)：犒劳","为(wèi)：替、给。"],translation:"项羽十分愤怒，说：明天犒劳士兵，替我打败刘邦的军队！"},{text:"当是时，项羽兵四十万，在新丰鸿门；沛公兵十万，在霸上。",annotations:["当是时：在这个时候","新丰鸿门：地名。"],translation:"这时，项羽有四十万军队，驻扎在新丰鸿门；刘邦只有十万军队，驻扎在霸上。"},{text:"范增说项羽曰：“沛公居山东时，贪于财货，好美姬。”",annotations:["说(shuì)：劝说","山东：崤山以东","贪于财货：状语后置，贪图财物。"],translation:"范增劝项羽说：刘邦在崤山以东的时候，贪图财物，喜爱美女。"},{text:"今入关，财物无所取，妇女无所幸，此其志不在小。",annotations:["无所取：没有取用","幸：君主亲近女子","小：小的欲望。"],translation:"如今进了关中，财物一点不拿，妇女也不亲近，由此看来他的志向不小。"},{text:"吾令人望其气，皆为龙虎，成五采，此天子气也。急击勿失！",annotations:["望其气：观望云气，古代方术","五采：通“五彩”","判断句","失：错失时机。"],translation:"我派人观望他上空的云气，都是龙虎形状，五彩斑斓，这是天子的云气。赶快攻打，不要错失机会！"},{text:"楚左尹项伯者，项羽季父也，素善留侯张良。",annotations:["左尹：官职","季父：叔父","素：一向","善：形容词作动词，交好","判断句。"],translation:"楚国左尹项伯，是项羽的叔父，一向和留侯张良交好。"},{text:"张良是时从沛公，项伯乃夜驰之沛公军，私见张良，具告以事，欲呼张良与俱去。",annotations:["是时：这时","之：动词，到","具告以事：状语后置，把事情全部告诉他","俱去：一同离开。"],translation:"张良这时跟随刘邦，项伯就连夜骑马跑到刘邦军营，私下会见张良，把事情全都告诉了他，想叫张良和自己一起离开。"},{text:"曰：“毋从俱死也。”",annotations:["毋：不要","俱死：一同送死。"],translation:"项伯说：不要跟着刘邦一起送死。"},{text:"张良曰：“臣为韩王送沛公，沛公今事有急，亡去不义，不可不语。”",annotations:["为：替","亡去：逃跑离开","语(yù)：告诉。"],translation:"张良说：我替韩王护送沛公入关，如今沛公遇到危难，独自逃走不合道义，不能不告诉他。"},{text:"良乃入，具告沛公。",annotations:["具：全部。"],translation:"张良于是进去，把情况全部告诉刘邦。"},{text:"沛公大惊，曰：“为之奈何？”",annotations:["为之奈何：对此怎么办。"],translation:"刘邦大惊，说：这件事该怎么办？"},{text:"张良曰：“谁为大王为此计者？”",annotations:["前为(wèi)：替","后为(wéi)：想出。"],translation:"张良说：是谁给大王出这条计策的？"},{text:"曰：“鲰生说我曰：‘距关，毋内诸侯，秦地可尽王也。’故听之。”",annotations:["鲰(zōu)生：浅陋小人","距：通“拒”，把守","内：通“纳”，接纳","王：占有称王。"],translation:"刘邦说：一个小人劝我说：守住函谷关，不要放诸侯进来，秦国的土地可以全部占领称王。所以我听了他的话。"},{text:"良曰：“料大王士卒足以当项王乎？”",annotations:["料：估量","当：抵挡。"],translation:"张良说：大王估量自己的士兵足够抵挡项羽吗？"},{text:"沛公默然，曰：“固不如也。且为之奈何？”",annotations:["默然：沉默","固：本来。"],translation:"刘邦沉默许久，说：本来就比不上，那该怎么办？"},{text:"张良曰：“请往谓项伯，言沛公不敢背项王也。”",annotations:["谓：告诉","背：背叛。"],translation:"张良说：请让我去告诉项伯，说沛公不敢背叛项王。"},{text:"沛公曰：“君安与项伯有故？”",annotations:["安：怎么","有故：有旧交情。"],translation:"刘邦说：你怎么和项伯有旧交情？"},{text:"张良曰：“秦时与臣游，项伯杀人，臣活之；今事有急，故幸来告良。”",annotations:["游：交往","活：使动，使……活下来","幸：幸亏。"],translation:"张良说：秦朝时他和我交往，项伯杀了人，我救了他；如今事情危急，幸亏他来告诉我。"},{text:"沛公曰：“孰与君少长？”",annotations:["孰与：固定句式，和……相比谁更大。"],translation:"刘邦说：他和你谁年纪大？"},{text:"良曰：“长于臣。”",annotations:["长于臣：状语后置，比我年长。"],translation:"张良说：比我大。"},{text:"沛公曰：“君为我呼入，吾得兄事之。”",annotations:["兄：名词作状语，像对待兄长一样","事：侍奉。"],translation:"刘邦说：你替我请他进来，我要像对待兄长一样侍奉他。"},{text:"张良出，要项伯。",annotations:["要：通“邀”，邀请。"],translation:"张良出去，邀请项伯。"},{text:"项伯即入见沛公。",annotations:[],translation:"项伯就进去拜见刘邦。"},{text:"沛公奉卮酒为寿，约为婚姻。",annotations:["奉：捧","卮(zhī)：酒杯","为寿：敬酒祝福","婚姻：古今异义，儿女亲家。"],translation:"刘邦捧上一杯酒向项伯敬酒祝福，约定结为儿女亲家。"},{text:"曰：“吾入关，秋毫不敢有所近，籍吏民，封府库，而待将军。”",annotations:["秋毫：细微财物","籍：名词作动词，登记","府库：仓库。"],translation:"刘邦说：我进关中，一丝一毫财物都不敢碰，登记官吏百姓，封存仓库，专门等待将军到来。"},{text:"所以遣将守关者，备他盗之出入与非常也。",annotations:["所以：……的原因","出入：偏义复词，进入","非常：古今异义，意外变故。"],translation:"派遣将领把守函谷关的原因，是防备其他盗贼进来和意外变故。"},{text:"日夜望将军至，岂敢反乎！愿伯具言臣之不敢倍德也。",annotations:["倍：通“背”，背叛","德：恩德。"],translation:"我日日夜夜盼望将军到来，哪里敢反叛！希望您把我的心意全部告诉项王，我不敢忘恩负义。"},{text:"项伯许诺，谓沛公曰：“旦日不可不蚤自来谢项王。”",annotations:["蚤：通“早”","谢：道歉、谢罪。"],translation:"项伯答应了，对刘邦说：明天不能不早早亲自来向项王道歉。"},{text:"沛公曰：“诺。”",annotations:[],translation:"刘邦说：好。"},{text:"于是项伯复夜去，至军中，具以沛公言报项王，因言曰：“沛公不先破关中，公岂敢入乎？”",annotations:["复：又","具以沛公言报：状语后置","因：趁机。"],translation:"于是项伯又连夜离去，回到军营，把刘邦的话全部报告项羽，趁机劝道：如果不是刘邦先攻破关中，您怎么敢轻易进来？"},{text:"今人有大功而击之，不义也。不如因善遇之。",annotations:["善遇：好好对待。"],translation:"如今人家立了大功，你却攻打他，不合道义。不如就此好好款待他。"},{text:"项王许诺。",annotations:[],translation:"项羽答应了。"},{text:"沛公旦日从百余骑来见项王，至鸿门，谢曰：“臣与将军戮力而攻秦，将军战河北，臣战河南。”",annotations:["从：使动，使……跟随","骑(jì)：骑兵","戮力：合力","河北/河南：黄河以北、以南。"],translation:"第二天刘邦带着一百多名骑兵来拜见项羽，到鸿门，道歉说：我和将军合力攻打秦国，将军在黄河以北作战，我在黄河以南作战。"},{text:"然不自意能先入关破秦，得复见将军于此。",annotations:["不自意：自己没料到","于此：状语后置。"],translation:"我自己也没料到能先入关攻破秦国，能在这里再次见到将军。"},{text:"今者有小人之言，令将军与臣有郤。",annotations:["郤(xì)：通“隙”，隔阂、嫌怨。"],translation:"现在有小人搬弄是非，让将军和我产生隔阂。"},{text:"项王曰：“此沛公左司马曹无伤言之；不然，籍何以至此。”",annotations:["籍：项羽名","何以：宾语前置，凭什么。"],translation:"项羽说：这是你的左司马曹无伤说的，不然我怎么会到这种地步。"},{text:"项王即日因留沛公与饮。",annotations:["即日：当天","与饮：省略宾语，与之饮酒。"],translation:"项羽当天就留下刘邦一同饮酒。"},{text:"项王、项伯东向坐，亚父南向坐，—— 亚父者，范增也；沛公北向坐；张良西向侍。",annotations:["东向坐：面朝东坐，古礼以东为尊","亚父：范增尊称","判断句。"],translation:"项羽、项伯面朝东坐，范增面朝南坐，范增就是亚父；刘邦面朝北坐；张良面朝西陪侍。"},{text:"范增数目项王，举所佩玉玦以示之者三，项王默然不应。",annotations:["目：名词作动词，使眼色","数(shuò)：多次","玦(jué)：玉饰，谐音“决”，暗示下决心杀人。"],translation:"范增多次给项羽使眼色，多次举起佩戴的玉玦示意项羽动手，项羽沉默不回应。"},{text:"范增起，出召项庄，谓曰：“君王为人不忍。若入前为寿，寿毕，请以剑舞，因击沛公于坐，杀之。”",annotations:["若：你","为寿：敬酒","因：趁机","击沛公于坐：状语后置，在座上刺杀刘邦。"],translation:"范增起身，出去叫来项庄，说：项王为人心软。你上前敬酒，敬酒完请求舞剑，趁机在座席上刺杀刘邦，杀掉他。"},{text:"不者，若属皆且为所虏！",annotations:["不：通“否”","若属：你们这些人","为所虏：被动句，被他俘虏。"],translation:"不然，你们所有人都将被他俘虏！"},{text:"庄则入为寿。",annotations:[],translation:"项庄就进去敬酒。"},{text:"寿毕，曰：“君王与沛公饮，军中无以为乐，请以剑舞。”",annotations:["无以为乐：没有用来助兴的东西。"],translation:"敬酒完毕，项庄说：大王和沛公饮酒，军营里没有什么助兴，请允许我舞剑。"},{text:"项王曰：“诺。”",annotations:[],translation:"项羽说：好。"},{text:"项庄拔剑起舞，项伯亦拔剑起舞，常以身翼蔽沛公，庄不得击。",annotations:["翼：名词作状语，像翅膀一样","蔽：遮挡。"],translation:"项庄拔剑起舞，项伯也拔剑起舞，常常张开身体像翅膀一样护住刘邦，项庄无法刺杀。"},{text:"于是张良至军门见樊哙。",annotations:[],translation:"这时张良到军营门外见到樊哙。"},{text:"樊哙曰：“今日之事何如？”",annotations:["何如：怎么样。"],translation:"樊哙问：今天事情怎么样了？"},{text:"良曰：“甚急！今者项庄拔剑舞，其意常在沛公也。”",annotations:[],translation:"张良说：十分危急！现在项庄舞剑，他的心思总在沛公身上。"},{text:"哙曰：“此迫矣！臣请入，与之同命。”",annotations:["迫：紧迫","同命：同生共死。"],translation:"樊哙说：这太危急了，请让我进去，和沛公同生共死。"},{text:"哙即带剑拥盾入军门。",annotations:["拥盾：手持盾牌。"],translation:"樊哙立刻拿着剑、持着盾牌冲进营门。"},{text:"交戟之卫士欲止不内，樊哙侧其盾以撞，卫士仆地，哙遂入。",annotations:["交戟：持戟交叉把守","内：通“纳”","仆：倒地。"],translation:"持戟交叉守卫的士兵想拦住他不让进，樊哙侧过盾牌一撞，卫兵倒在地上，樊哙就冲进去了。"},{text:"披帷西向立，瞋目视项王，头发上指，目眦尽裂。",annotations:["披帷：掀开帐幕","瞋(chēn)目：瞪大眼睛","上：名作状，向上","眦(zì)：眼眶。"],translation:"掀开帐幕面朝西站定，瞪着项羽，头发向上竖起，眼眶全都裂开。"},{text:"项王按剑而跽曰：“客何为者？”",annotations:["跽(jì)：跪直身子，戒备姿态","何为：宾语前置，做什么的。"],translation:"项羽手握剑柄跪直身子，问：来人是干什么的？"},{text:"张良曰：“沛公之参乘樊哙者也。”",annotations:["参乘(shèng)：车上护卫","判断句。"],translation:"张良说：这是沛公的随车护卫樊哙。"},{text:"项王曰：“壮士！赐之卮酒。”",annotations:[],translation:"项羽说：壮士！赏他一杯酒。"},{text:"则与斗卮酒。",annotations:["斗卮：大酒杯。"],translation:"手下人递给他一大杯酒。"},{text:"哙拜谢，起，立而饮之。",annotations:[],translation:"樊哙行礼道谢，起身站着把酒喝完。"},{text:"项王曰：“赐之彘肩。”",annotations:["彘(zhì)肩：猪前腿。"],translation:"项羽说：赏他一条猪腿。"},{text:"则与一生彘肩。",annotations:[],translation:"手下递给他一条生猪腿。"},{text:"樊哙覆其盾于地，加彘肩上，拔剑切而啖之。",annotations:["覆：扣放","啖(dàn)：吃。"],translation:"樊哙把盾牌扣在地上，把猪腿放在盾上，拔剑切开来吃。"},{text:"项王曰：“壮士！能复饮乎？”",annotations:[],translation:"项羽说：壮士！还能再喝吗？"},{text:"樊哙曰：“臣死且不避，卮酒安足辞！夫秦王有虎狼之心，杀人如不能举，刑人如恐不胜，天下皆叛之。”",annotations:["举、胜：尽","刑：名作动词，施加刑罚。"],translation:"樊哙说：我连死都不躲避，一杯酒哪里值得推辞！秦王有虎狼般的心肠，杀人唯恐杀不完，处罚人唯恐不尽数，天下人全都背叛他。"},{text:"怀王与诸将约曰：‘先破秦入咸阳者王之。’",annotations:["王之：使动，让他为王。"],translation:"怀王和众将约定：先攻破秦国进入咸阳的人，就让他做关中王。"},{text:"今沛公先破秦入咸阳，毫毛不敢有所近，封闭宫室，还军霸上，以待大王来。",annotations:[],translation:"如今沛公先攻破秦国进入咸阳，一丝财物都不敢碰，封闭宫殿，撤军回霸上，等候大王到来。"},{text:"故遣将守关者，备他盗出入与非常也。劳苦而功高如此，未有封侯之赏，而听细说，欲诛有功之人，此亡秦之续耳。窃为大王不取也！”",annotations:["细说：小人谗言","续：老路","窃：私下。"],translation:"特意派将领守关，防备盗贼和意外变故。如此劳苦功高，没有封侯的赏赐，反而听信小人谗言，要杀有功之人，这是走灭亡秦国的老路。我私下认为大王不该这么做。"},{text:"项王未有以应，曰：“坐。”",annotations:["未有以应：没有话来回应。"],translation:"项羽无话可答，只说：坐。"},{text:"樊哙从良坐。",annotations:[],translation:"樊哙挨着张良坐下。"},{text:"坐须臾，沛公起如厕，因招樊哙出。",annotations:["须臾：片刻","如厕：上厕所","因：趁机。"],translation:"坐了一会儿，刘邦起身去上厕所，趁机招手叫樊哙出去。"},{text:"沛公已出，项王使都尉陈平召沛公。",annotations:[],translation:"刘邦出去后，项羽派都尉陈平去叫刘邦回来。"},{text:"沛公曰：“今者出，未辞也，为之奈何？”",annotations:["辞：告辞。"],translation:"刘邦说：现在出来，没有告辞，该怎么办？"},{text:"樊哙曰：“大行不顾细谨，大礼不辞小让。如今人方为刀俎，我为鱼肉，何辞为？”",annotations:["细谨：细小礼节","让：责备","刀俎(zǔ)：刀和砧板","何辞为：固定句式，何必告辞呢。"],translation:"樊哙说：做大事不必顾及细小礼节，行大礼不必回避小的责备。现在人家是刀和砧板，我们是鱼肉，何必告辞？"},{text:"于是遂去。乃令张良留谢。",annotations:["去：离开","留谢：留下来致歉。"],translation:"于是刘邦就离开了，让张良留下来代为道歉。"},{text:"良问曰：“大王来何操？”",annotations:["何操：宾语前置，带了什么礼物。"],translation:"张良问：大王来时带了什么礼物？"},{text:"曰：“我持白璧一双，欲献项王，玉斗一双，欲与亚父。会其怒，不敢献。公为我献之。”",annotations:["会：恰逢","璧、玉斗：玉器。"],translation:"刘邦说：我带了一对白璧，打算献给项王；一对玉斗，送给亚父。恰逢他发怒，不敢献上。你替我献给他们。"},{text:"张良曰：“谨诺。”",annotations:[],translation:"张良说：遵命。"},{text:"当是时，项王军在鸿门下，沛公军在霸上，相去四十里。",annotations:["相去：相距。"],translation:"这时，项羽军营在鸿门山下，刘邦军营在霸上，相距四十里。"},{text:"沛公则置车骑，脱身独去，与樊哙、夏侯婴、靳强、纪信等四人持剑盾步走，从郦山下，道芷阳间行。",annotations:["置：舍弃","步走：徒步快跑","道：名作动词，取道","间(jiàn)：名作状，从小路。"],translation:"刘邦舍弃车马随从，独自脱身离开，和樊哙、夏侯婴、靳强、纪信四人持剑盾步行快跑，从郦山脚下，取道芷阳，抄小路走。"},{text:"沛公谓张良曰：“从此道至吾军，不过二十里耳。度我至军中，公乃入。”",annotations:["度(duó)：估量。"],translation:"刘邦对张良说：从这条路到我们军营，不过二十里。估算我回到军营，你再进去。"},{text:"沛公已去，间至军中。",annotations:[],translation:"刘邦离开后，从小路回到军营。"},{text:"张良入谢，曰：“沛公不胜杯杓，不能辞。谨使臣良奉白璧一双，再拜献大王足下；玉斗一双，再拜奉大将军足下。”",annotations:["不胜杯杓(sháo)：禁不起酒力，喝醉","再拜：拜两次","足下：敬称。"],translation:"张良进去道歉说：沛公不胜酒力，不能亲自告辞。特地派我奉上一对白璧，拜两拜献给大王；一对玉斗，拜两拜献给范大将军。"},{text:"项王曰：“沛公安在？”",annotations:["安在：宾语前置，在哪里。"],translation:"项羽说：沛公在哪里？"},{text:"良曰：“闻大王有意督过之，脱身独去，已至军矣。”",annotations:["督过：责备。"],translation:"张良说：听说大王有意要责备他，就独自脱身离开，已经回到军营了。"},{text:"项王则受璧，置之坐上。",annotations:["坐：通“座”，座位。"],translation:"项羽收下白璧，放在座位上。"},{text:"亚父受玉斗，置之地，拔剑撞而破之，曰：“唉！竖子不足与谋！夺项王天下者必沛公也。吾属今为之虏矣！”",annotations:["竖子：小子，骂项羽、项庄","吾属：我们","为之虏：被动句，被他俘虏。"],translation:"范增接过玉斗，扔在地上，拔剑击碎它，叹道：唉！这小子不值得共谋大事！夺取项王天下的一定是刘邦，我们这些人马上就要被他俘虏了。"},{text:"沛公至军，立诛杀曹无伤。",annotations:["立：立刻。"],translation:"刘邦回到军营，立刻杀掉曹无伤。"}]},18:{id:"18",title:"报任安书",source:"司马迁",paragraphs:[{text:"太史公牛马走司马迁，再拜言，少卿足下：",annotations:["牛马走：谦辞，像牛马一样供驱使的仆人","再拜：拜两次，古代书信敬语","足下：对对方尊称。"],translation:"像牛马一样供人驱使的司马迁，再拜进言，少卿足下："},{text:"曩者辱赐书，教以慎于接物，推贤进士为务，意气勤勤恳恳。",annotations:["曩(nǎng)者：从前","辱：谦辞，承蒙","接物：与人交往","务：分内要事。"],translation:"从前承蒙您赐我书信，教导我待人接物应当谨慎，把推举贤才当作自己的职责，信中情意真挚恳切。"},{text:"若望仆不相师，而用流俗人之言。",annotations:["望：埋怨","仆：司马迁自谦","相师：遵从您的教导","流俗人：平庸世俗之人。"],translation:"好像在埋怨我没有遵从您的教诲，反而听信世俗庸人的话。"},{text:"仆非敢如是也。",annotations:[],translation:"我不敢像您所想的那样。"},{text:"仆虽罢驽，亦尝侧闻长者遗风矣。",annotations:["罢(pí)驽：疲惫劣马，自喻平庸无能","侧闻：从旁听闻，谦辞","长者：有德望之人。"],translation:"我虽然平庸愚钝，也曾私下听闻有德长者流传下来的风范。"},{text:"顾自以为身残处秽，动而见尤，欲益反损，是以独郁悒而无谁语。",annotations:["顾：只是","身残处秽：受过宫刑，身体残缺、身处屈辱境地","见尤：被动句式，被指责","郁悒(yì)：苦闷郁结。"],translation:"只是我自认为身体残缺、身处污辱之地，稍有行动就会受人指责，本想做点好事反而招致灾祸，因此独自苦闷，无处倾诉。"},{text:"谚曰：“谁为为之？孰令听之？”",annotations:["前为(wèi)：替","后为(wéi)：做","孰令：令孰，让谁。"],translation:"俗语说：为谁去做这件事？又能让谁听从我的主张？"},{text:"盖钟子期死，伯牙终身不复鼓琴。",annotations:["鼓：弹奏","伯牙、钟子期：知音典故。"],translation:"钟子期死后，伯牙终生不再弹琴。"},{text:"何则？",annotations:["何则：为什么呢。"],translation:"为什么呢？"},{text:"士为知己者用，女为悦己者容。",annotations:["容：名词作动词，梳妆打扮。"],translation:"士人愿意为理解自己的知己效力，女子愿意为喜爱自己的人梳妆。"},{text:"若仆大质已亏缺矣，虽才怀随和，行若由夷，终不可以为荣，适足以发笑而自点耳。",annotations:["大质：身体","随和：随侯珠、和氏璧，喻绝世才华","由夷：许由、伯夷，喻高洁品行","点：通“玷”，玷污。"],translation:"像我这般身体已经残缺的人，就算身怀随珠、和氏璧一样的才华，品行如同许由、伯夷一般高洁，终究不能算作荣耀，只会惹人耻笑、自取玷污。"},{text:"书辞宜答，会东从上来，又迫贱事，相见日浅，卒卒无须臾之间，得竭指意。",annotations:["会：恰逢","东从上来：随从汉武帝向东巡行","卒(cù)卒：匆忙仓促","间(xián)：空闲","指意：内心心意。"],translation:"本该及时回复您的来信，恰逢我随从皇帝东巡，又被繁杂琐事缠身，与您见面的机会极少，终日匆忙，没有片刻空闲能倾诉全部心意。"},{text:"今少卿抱不测之罪，涉旬月，迫季冬，仆又薄从上雍，恐卒然不可为讳，是仆终已不得舒愤懑以晓左右，则长逝者魂魄私恨无穷。",annotations:["不测之罪：死罪","旬月：一个月","季冬：冬季末月，汉代处决犯人的时节","薄：迫近","不可为讳：委婉代指死亡","左右：代指任安。"],translation:"如今您身遭死罪，再过一个月，就到冬季行刑之时，我又即将随从皇帝前往雍地，恐怕您骤然离世，那我终生无法抒发心中愤懑让您知晓，逝去之人魂魄会抱憾无尽。"},{text:"请略陈固陋。",annotations:["固陋：浅鄙粗浅的想法，自谦。"],translation:"请允许我简略陈述我浅陋的想法。"},{text:"阙然久不报，幸勿为过。",annotations:["阙然：间隔许久","过：责备。"],translation:"隔了这么久没有回信，希望您不要怪罪我。"},{text:"仆闻之：修身者，智之符也；爱施者，仁之端也；取予者，义之表也；耻辱者，勇之决也；立名者，行之极也。",annotations:["符：凭证、标志","端：开端","表：外在体现","决：判断标准","极：最高准则。"],translation:"我听说：修养自身，是智慧的凭证；乐于施舍，是仁德的开端；取舍有度，是道义的体现；懂得羞耻，是勇敢的标尺；树立美名，是品行的最高境界。"},{text:"士有此五者，然后可以托于世，列于君子之林矣。",annotations:[],translation:"士人具备这五种品德，之后才能立身于世，跻身有德君子之列。"},{text:"故祸莫憯于欲利，悲莫痛于伤心，行莫丑于辱先，诟莫大于宫刑。",annotations:["憯(cǎn)：惨痛","辱先：辱没先祖","诟：耻辱。"],translation:"所以灾祸没有比贪图私利更惨痛的，悲哀没有比内心伤痛更折磨人的，行为没有比辱没先祖更丑恶的，耻辱没有比宫刑更大的。"},{text:"刑余之人，无所比数，非一世也，所从来远矣。",annotations:["刑余之人：受过宫刑的人","比数：并列、相提并论。"],translation:"受过宫刑的人，不能和常人同等看待，这种看法不是一朝一夕形成，由来已久。"},{text:"昔卫灵公与雍渠同载，孔子适陈；",annotations:["雍渠：宦官","适：前往","卫灵公与宦官同车，孔子引以为耻离开卫国。"],translation:"从前卫灵公和宦官雍渠同乘一车，孔子为此离开卫国前往陈国。"},{text:"商鞅因景监见，赵良寒心；",annotations:["景监：举荐商鞅的宦官","寒心：失望痛心，认为依靠宦官不光彩。"],translation:"商鞅依靠宦官景监引荐才得见秦孝公，贤士赵良为此深感失望。"},{text:"同子参乘，袁丝变色：自古而耻之！",annotations:["同子：宦官赵谈（司马迁避父讳改称同子）","参乘：陪坐车旁","袁丝：袁盎","变色：面露不满。"],translation:"宦官赵谈陪汉文帝乘车，袁盎当即脸色大变：自古以来人们就以与宦官为伍为耻！"},{text:"夫以中材之人，事有关于宦竖，莫不伤气，而况于慷慨之士乎！",annotations:["中材：中等才能普通人","宦竖：宦官","伤气：挫伤志气","慷慨之士：有气节的志士。"],translation:"就算是普通才能的普通人，只要事情牵扯宦官，都会挫伤志气，更何况胸怀大义的志士！"},{text:"如今朝廷虽乏人，奈何令刀锯之余，荐天下之豪俊哉！",annotations:["刀锯之余：受过宫刑、身体残缺的自己","豪俊：天下贤才。"],translation:"如今朝廷就算缺少人才，又怎么能让我这种受过宫刑的人，去举荐天下的豪杰贤才呢！"},{text:"仆赖先人绪业，得待罪辇毂下，二十余年矣。",annotations:["绪业：遗留的官职家业","待罪：谦辞，任职","辇毂(gǔ)下：皇帝车驾旁，代指京城。"],translation:"我依靠先祖留下的史官职位，得以在京城为官，至今二十多年了。"},{text:"所以自惟：上之，不能纳忠效信，有奇策材力之誉，自结明主；",annotations:["自惟：自己思索","效信：奉献忠诚","结：交好、获得赏识。"],translation:"我私下反思自己：对上，不能献上忠心、献出诚信，没有出奇谋略与出众才干的名声，获得君主赏识；"},{text:"次之，又不能拾遗补阙，招贤进能，显岩穴之士；",annotations:["拾遗补阙：弥补朝政疏漏","岩穴之士：隐居山野的贤才。"],translation:"其次，又不能辅佐君主弥补朝政过失，招揽贤能之人，使隐居山野的有才之士得到重用；"},{text:"外之，不能备行伍，攻城野战，有斩将搴旗之功；",annotations:["行伍：军队","搴(qiān)旗：拔下敌军军旗。"],translation:"对外，不能投身军队，上阵攻城野战，建立斩杀敌将、夺取军旗的战功；"},{text:"下之，不能积日累劳，取尊官厚禄，以为宗族交游光宠。",annotations:["交游：亲友朋友","光宠：荣耀。"],translation:"对下，不能长年累积功劳，获取高官厚禄，给宗族亲友增添荣光。"},{text:"四者无一遂，苟合取容，无所短长之效，可见于此矣。",annotations:["遂：实现","苟合取容：苟且迎合君主以求容身","短长：大小，指任何贡献。"],translation:"这四样事没有一件做成，只能苟且迎合君主勉强立身，没有任何尺寸功劳，由此就能看清我的无能。"},{text:"乡者，仆亦尝厕下大夫之列，陪外廷末议。",annotations:["乡：通“向”，从前","厕：夹杂、置身，谦辞","下大夫：汉代史官品级","末议：微不足道的议论。"],translation:"从前，我也曾置身下大夫的行列，在外朝参与一些微不足道的议论。"},{text:"不以此时引纲维，尽思虑，今已亏形为扫除之隶，在阘茸之中，乃欲仰首伸眉，论列是非，不亦轻朝廷、羞当世之士邪？",annotations:["纲维：国家法度","扫除之隶：如同奴仆","阘(tà)茸：卑微低劣的地位","论列：评议。"],translation:"不在那时伸张国家法度、竭尽思考，如今身体残缺，形同打杂奴仆，身处卑微底层，却想昂首扬眉评议是非，这不是轻视朝廷、羞辱当世贤士吗？"},{text:"嗟乎！嗟乎！如仆尚何言哉！尚何言哉！",annotations:[],translation:"唉！唉！像我这样的人还有什么可说！还有什么可说！"},{text:"且事本末未易明也。",annotations:["本末：前因后果。"],translation:"况且这件事的前因后果，不容易向外人讲清楚。"},{text:"仆少负不羁之才，长无乡曲之誉，主上幸以先人之故，使得奏薄技，出入周卫之中。",annotations:["负：怀有","不羁：不受拘束","乡曲：乡里","薄技：微薄技艺，指文史","周卫：皇宫禁卫，代指宫中。"],translation:"我年少时怀有出众不凡的才华，成年后却没有乡里人的称誉，幸亏君主看在先臣的份上，让我得以施展微薄的文史技艺，出入皇宫之中。"},{text:"仆以为戴盆何以望天，故绝宾客之知，忘室家之业，日夜思竭其不肖之材力，务一心营职，以求亲媚于主上。",annotations:["戴盆何以望天：头顶盆子就看不见天，比喻专心本职无暇分心","知：交往","营职：办好本职","亲媚：亲近取悦。"],translation:"我认为一心做一件事就不能兼顾其他，所以断绝与宾客的交往，放下家庭私事，日夜想倾尽自己平庸的才力，一心办好本职，希望能得到君主的喜爱信任。"},{text:"而事乃有大谬不然者！",annotations:["大谬：完全相反。"],translation:"可事情结果却完全出乎我的意料！"},{text:"夫仆与李陵俱居门下，素非能相善也。",annotations:["李陵：李广之孙","俱居门下：同属侍中","相善：交好。"],translation:"我和李陵同属侍中，平日里并不交好。"},{text:"趣舍异路，未尝衔杯酒，接殷勤之余欢。",annotations:["趣：通“取”","趣舍：取舍志向","衔杯酒：一同饮酒","殷勤：情意恳切。"],translation:"我们志向取舍完全不同，从未在一起饮酒，没有半点亲密交往。"},{text:"然仆观其为人，自守奇士，事亲孝，与士信，临财廉，取予义，分别有让，恭俭下人，常思奋不顾身，以徇国家之急。",annotations:["自守：坚守节操","下人：待人谦卑","徇：通“殉”，献身。"],translation:"但我观察他的为人，是坚守节操的出众之人：侍奉父母孝顺，对待士人诚信，面对财物清廉，取舍合乎道义，待人有礼谦让，恭敬谦卑，常常想着奋不顾身，为国赴难。"},{text:"其素所蓄积也，仆以为有国士之风。",annotations:["蓄积：平日品行修养","国士：一国顶尖贤才。"],translation:"从他平日的品行来看，我认为他具备天下顶尖贤才的风范。"},{text:"夫人臣出万死不顾一生之计，赴公家之难，斯已奇矣。",annotations:[],translation:"作为臣子，甘愿冒万死风险不顾自身安危，奔赴国家危难，这已经十分难得。"},{text:"今举事一不当，而全躯保妻子之臣随而媒孽其短，仆诚私心痛之。",annotations:["举事：行事","全躯：保全自身","媒孽：挑拨、夸大过错","妻子：妻子儿女。"],translation:"如今一次作战失利，那些只想着保全自身妻儿的大臣，就跟着夸大捏造他的过错，我私下实在痛心。"},{text:"且李陵提步卒不满五千，深践戎马之地，足历王庭，垂饵虎口，横挑强胡，仰亿万之师，与单于连战十有余日，所杀过当。",annotations:["提：率领","王庭：匈奴单于驻地","过当：斩杀敌军数量超过己方人数。"],translation:"况且李陵率领不足五千步兵，深入匈奴腹地，直达单于王庭，如同在虎口设下诱饵，主动挑战强大匈奴，直面数万敌军，和单于连续交战十几天，斩杀敌军数量超过己方士兵。"},{text:"虏救死扶伤不给，旃裘之君长咸震怖，乃悉征其左、右贤王，举引弓之民，一国共攻而围之。",annotations:["不给：来不及","旃(zhān)裘：毛毡皮衣，代指匈奴","悉征：全部征调","引弓之民：能拉弓作战的百姓。"],translation:"匈奴军队死伤无数，连救死扶伤都来不及，匈奴各首领全都震惊恐惧，于是征调左右贤王全部人马，发动全国能作战的百姓，举国合力包围李陵军队。"},{text:"转斗千里，矢尽道穷，救兵不至，士卒死伤如积。",annotations:[],translation:"转战千里，箭矢耗尽、无路可退，朝廷救兵迟迟不到，士兵死伤堆积如山。"},{text:"然陵一呼劳军，士无不起，躬自流涕，沬血饮泣，更张空弮，冒白刃，北乡争死敌者。",annotations:["劳军：慰劳士兵","沬(huì)血：脸上沾满血","弮(quān)：弓弦","乡：通“向”。"],translation:"可李陵一声号令慰劳军队，士兵无不起身，满脸是泪、满脸血污，拉开空弓，直面雪亮刀刃，面朝北方争相与敌军死战。"},{text:"陵未没时，使有来报，汉公卿王侯皆奉觞上寿。",annotations:["没：覆没","奉觞(shāng)上寿：举杯庆贺胜利。"],translation:"李陵军队尚未覆没时，有使者传回捷报，汉朝王公大臣全都举杯向君主庆贺。"},{text:"后数日，陵败书闻，主上为之食不甘味，听朝不怡。",annotations:["闻：使君主听闻","不怡：心中不悦。"],translation:"没过几天，李陵战败的消息传来，君主为此吃饭无味，上朝理政也满心烦闷。"},{text:"大臣忧惧，不知所出。",annotations:[],translation:"大臣们惶恐忧虑，不知该有什么对策。"},{text:"仆窃不自料其卑贱，见主上惨凄怛悼，诚欲效其款款之愚，以为李陵素与士大夫绝甘分少，能得人之死力，虽古之名将，不能过也。",annotations:["惨凄怛(dá)悼：哀伤悲痛","款款：诚恳","绝甘分少：有美食分给众人，自己不吃","死力：拼死效力。"],translation:"我不顾自己身份卑微，看见君主哀伤悲痛，真心想献上我诚恳浅陋的想法：李陵平日有美食都分给部下，能让士兵甘愿为他拼死，就算古代名将，也比不上他。"},{text:"身虽陷败，彼观其意，且欲得其当而报于汉。",annotations:["得其当：寻找合适时机立功抵罪。"],translation:"他虽然兵败被俘，看他本心，是想找到合适机会立功，报答汉朝。"},{text:"事已无可奈何，其所摧败，功亦足以暴于天下矣。",annotations:["摧败：重创敌军","暴(pù)：显露、昭示。"],translation:"战败已成无法挽回的事实，但他重创匈奴的战功，也足以昭示天下。"},{text:"仆怀欲陈之，而未有路，适会召问，即以此指，推言陵之功，欲以广主上之意，塞睚眦之辞。",annotations:["指：心意、观点","广：宽慰","睚眦(yá zì)之辞：仇家诬陷的谗言。"],translation:"我心中想把这番想法上奏，却没有机会，恰逢君主召见询问，就把这番心意说出，详述李陵的战功，想要宽慰君主，堵住那些借机诬陷的谗言。"},{text:"未能尽明，明主不晓，以为仆沮贰师，而为李陵游说，遂下于理。",annotations:["沮：诋毁","贰师：贰师将军李广利，汉武帝宠妃兄长","理：廷尉，司法监狱。"],translation:"没能把道理完全讲明白，君主没有领会我的本心，认为我诋毁李广利，替李陵开脱游说，于是把我交给廷尉治罪。"},{text:"拳拳之忠，终不能自列。",annotations:["拳拳：诚恳","列：申辩。"],translation:"我一片诚恳忠心，终究无法自我申辩清楚。"},{text:"因为诬上，卒从吏议。",annotations:["诬上：欺瞒君主","卒：最终","吏议：狱官判定的罪名。"],translation:"最终被判为欺君之罪，遵从狱官的判决定罪。"},{text:"家贫，货赂不足以自赎，交游莫救，左右亲近不为一言。",annotations:["货赂：钱财","汉代可出钱赎罪","左右亲近：君主身边近臣。"],translation:"我家中贫寒，钱财不足以赎罪，亲友没有一人出手相救，君主身边近臣也没有人为我说一句公道话。"},{text:"身非木石，独与法吏为伍，深幽囹圄之中，谁可告愬者！",annotations:["囹圄(líng yǔ)：监狱","愬：通“诉”，倾诉。"],translation:"人不是木头石块，独自和狱吏相伴，囚禁在幽深监狱里，又能向谁倾诉委屈！"},{text:"此真少卿所亲见，仆行事岂不然乎？",annotations:[],translation:"这些都是您亲眼能想到的，我的遭遇难道不是这样吗？"},{text:"李陵既生降，隤其家声，而仆又佴之蚕室，重为天下观笑。",annotations:["隤(tuí)：败坏","佴(ěr)：置身","蚕室：受宫刑后保暖的密室，代指宫刑。"],translation:"李陵投降匈奴，败坏自家世代名声，而我又身受宫刑，更被天下人耻笑。"},{text:"悲夫！悲夫！事未易一二为俗人言也。",annotations:["一二：逐条、详细。"],translation:"可悲啊！可悲啊！这件事的委屈，很难逐条向世俗之人讲明白。"},{text:"仆之先人非有剖符丹书之功，文史星历，近乎卜祝之间，固主上所戏弄，倡优畜之，流俗之所轻也。",annotations:["剖符丹书：功臣免罪铁券","卜祝：占卜祭祀小官","畜(xù)：蓄养，如同伶人一般豢养。"],translation:"我的先祖没有立下获赐丹书铁券的大功，掌管文史、星象历法，职位和占卜祭祀小吏相近，本就是君主消遣戏弄、如同伶人一般蓄养、被世俗轻视的职位。"},{text:"假令仆伏法受诛，若九牛亡一毛，与蝼蚁何以异？",annotations:["亡：通“无”","何以异：宾语前置，有什么区别。"],translation:"假如我伏法被杀，就像九头牛身上少一根毫毛，和蝼蚁死去有什么区别？"},{text:"而世又不与能死节者比，特以为智穷罪极，不能自免，卒就死耳。",annotations:["与：认可","死节：坚守气节赴死","特：只","卒：最终。"],translation:"世俗之人也不会把我和坚守气节赴死的人并列，只会认为我智计穷尽、罪大恶极，无法脱身，最终才送死罢了。"},{text:"何也？素所自树立使然也。",annotations:["素：平日","树立：立身的职业、身份。"],translation:"为什么？是我平日立身的职业、身份造成的。"},{text:"人固有一死，或重于泰山，或轻于鸿毛，用之所趋异也。",annotations:["固：本来","趋：追求、取舍。"],translation:"人本来都有一死，有的人死得比泰山还重，有的人死得比鸿雁羽毛还轻，是他们生死取舍的追求不同。"},{text:"太上不辱先，其次不辱身，其次不辱理色，其次不辱辞令；其次诎体受辱，其次易服受辱，其次关木索、被箠楚受辱，其次剔毛发、婴金铁受辱，其次毁肌肤、断肢体受辱，最下腐刑极矣！",annotations:["太上：最上等","理色：脸面尊严","诎(qū)：通“屈”","易服：囚服","关木索：戴枷锁","箠楚：棍棒拷打","剔：通“剃”","婴：缠绕","腐刑：宫刑，屈辱极致。"],translation:"最上等是不辱没先祖，其次不玷污自身，其次不丧失脸面尊严，其次不被言语羞辱；再次身体捆绑受辱，再次换上囚服受辱，再次戴枷锁、遭鞭打受辱，再次剃光头发、颈戴铁圈受辱，再次损毁皮肉、斩断肢体受辱，最下等就是宫刑，屈辱到顶点！"},{text:"传曰 “刑不上大夫。” 此言士节不可不勉厉也。",annotations:["传：古籍","勉厉：勉励坚守。"],translation:"古籍上说：刑罚不加于大夫身上。这是说士人的气节不能不自我勉励坚守。"},{text:"猛虎在深山，百兽震恐，及在槛阱之中，摇尾而求食，积威约之渐也。",annotations:["槛(jiàn)：兽笼","阱：陷阱","威约：威压约束","渐：慢慢浸染消磨烈性。"],translation:"猛虎身处深山，百兽全都恐惧，等到落入牢笼陷阱，就摇着尾巴乞求食物，是长期的威压约束渐渐磨掉了它的烈性。"},{text:"故士有画地为牢，势不可入；削木为吏，议不可对，定计于鲜也。",annotations:["鲜：早，事前早下定宁死不受辱的决心。"],translation:"所以有的士人，就算地上画圈当作牢房，也绝不踏入；削木头做成狱吏，也绝不面对审讯，事前早就下定宁死不受辱的决心。"},{text:"今交手足，受木索，暴肌肤，受榜箠，幽于圜墙之中。",annotations:["交手足：手脚捆绑","暴(pù)：裸露","榜箠：鞭打","圜(huán)墙：监狱围墙。"],translation:"如今手脚被捆绑，戴上枷锁，皮肉裸露遭受鞭打，囚禁在监狱高墙之内。"},{text:"当此之时，见狱吏则头抢地，视徒隶则心惕息。",annotations:["抢(qiāng)：撞","徒隶：狱卒","惕息：恐惧不敢喘气。"],translation:"在这种时候，看见狱吏就磕头碰地，看见狱卒就心惊胆战不敢喘气。"},{text:"何者？积威约之势也。",annotations:[],translation:"为什么？是长期威压约束形成的卑微态势。"},{text:"及以至是，言不辱者，所谓强颜耳，曷足贵乎！",annotations:["以：已","强颜：厚着脸皮","曷：何。"],translation:"已经到了这种地步，还说自己没有受辱，不过是厚着脸皮罢了，哪里值得推崇！"},{text:"且西伯，伯也，拘于羑里；李斯，相也，具于五刑；淮阴，王也，受械于陈；彭越、张敖，南面称孤，系狱抵罪；绛侯诛诸吕，权倾五伯，囚于请室；魏其，大将也，衣赭衣，关三木；季布为朱家钳奴；灌夫受辱于居室。",annotations:["西伯：周文王","羑(yǒu)里：纣王囚禁文王之地","五刑：全套酷刑","淮阴：韩信","械：刑具","绛侯：周勃","请室：待罪囚室","魏其：窦婴","赭衣：囚衣","三木：手、足、颈三套刑具","钳奴：颈戴铁圈奴仆","居室：汉代牢狱。"],translation:"再说周文王是一方诸侯，却被拘禁在羑里；李斯身为丞相，受尽五种酷刑；淮阴侯韩信是诸侯王，在陈地戴上刑具；彭越、张敖身为王侯，也被关进监狱抵罪；周勃平定吕氏叛乱，权势超过春秋五霸，却被囚禁待罪；窦婴身为大将军，身穿囚服、全套枷锁；季布曾剃发戴铁圈做朱家奴仆；灌夫在牢狱受尽屈辱。"},{text:"此人皆身至王侯将相，声闻邻国，及罪至罔加，不能引决自裁，在尘埃之中。",annotations:["罔：通“网”，法网","引决自裁：自杀","尘埃：污浊牢狱。"],translation:"这些人都身居王侯将相高位，名声传遍邻国，等到法网加身，却不能及时自杀，深陷牢狱污浊。"},{text:"古今一体，安在其不辱也？",annotations:["一体：同一个道理","安在：在哪里。"],translation:"古往今来道理相同，他们又怎能不受屈辱？"},{text:"由此言之，勇怯，势也；强弱，形也。",annotations:[],translation:"由此来说，勇敢还是怯懦，由所处形势决定；强大还是弱小，由外在处境决定。"},{text:"审矣，何足怪乎？",annotations:["审：明白清楚。"],translation:"道理十分明白，有什么值得奇怪？"},{text:"夫人不能早自裁绳墨之外，以稍陵迟，至于鞭箠之间，乃欲引节，斯不亦远乎！",annotations:["绳墨：法律刑罚","陵迟：志气消磨衰微","引节：守气节自杀。"],translation:"人如果不能在刑罚降临之前早早自杀，等到志气渐渐消磨，挨过鞭打拷打，才想保全气节赴死，这不也太晚了吗！"},{text:"古人所以重施刑于大夫者，殆为此也。",annotations:["重：慎重不忍轻易用刑","殆：大概。"],translation:"古人之所以对大夫慎重用刑，大概就是这个缘故。"},{text:"夫人情莫不贪生恶死，念父母，顾妻子，至激于义理者不然，乃有所不得已也。",annotations:["恶(wù)：厌恶","妻子：妻子儿女","激于义理：被动句式，被道义激发。"],translation:"人之常情没有不贪生怕死、挂念父母妻儿的；只有被道义激发的人不这样，是有迫不得已的苦衷。"},{text:"今仆不幸，早失父母，无兄弟之亲，独身孤立，少卿视仆于妻子何如哉？",annotations:["孤立：孤单无依靠。"],translation:"我不幸早年丧父母，没有兄弟亲人，孤身一人无依无靠，少卿您看我对妻儿又有什么牵挂？"},{text:"且勇者不必死节，怯夫慕义，何处不勉焉！",annotations:["慕义：向往道义","勉：自我勉励坚守大义。"],translation:"况且真正勇敢的人不一定非要以死守节，怯懦之人心中向往道义，随处都可以勉励自己坚守气节。"},{text:"仆虽怯懦，欲苟活，亦颇识去就之分矣，何至自沉溺缧绁之辱哉！",annotations:["去就：生死取舍的分寸","缧绁(léi xiè)：绳索，代牢狱刑罚。"],translation:"我虽然胆小懦弱、想苟活，也十分明白生死取舍的分寸，何至于甘愿深陷牢狱屈辱之中！"},{text:"且夫臧获婢妾，犹能引决，况仆之不得已乎？",annotations:["臧获：奴婢统称","引决：自杀。"],translation:"就连奴婢下人，尚且能受辱自尽，何况我还有不得已的苦衷？"},{text:"所以隐忍苟活，幽于粪土之中而不辞者，恨私心有所不尽，鄙陋没世，而文采不表于后也。",annotations:["粪土：污浊牢狱","恨：遗憾","没世：离世","表：显露流传。"],translation:"我之所以忍辱苟活，囚禁在污浊牢狱而不肯赴死，是心中遗憾理想未能完成，平庸离世，文章才华不能流传后世。"},{text:"古者富贵而名摩灭，不可胜记，唯倜傥非常之人称焉。",annotations:["摩：通“磨”","胜：尽","倜傥(tì tǎng)：卓越不凡","非常：不同寻常","称：被后世称颂。"],translation:"古时候富足显贵却姓名磨灭不传的人，多得数不清，只有那些卓越不凡、非同寻常的人能被后世称颂。"},{text:"盖文王拘而演《周易》；仲尼厄而作《春秋》；屈原放逐，乃赋《离骚》；左丘失明，厥有《国语》；孙子膑脚，《兵法》修列；不韦迁蜀，世传《吕览》；韩非囚秦，《说难》《孤愤》；《诗》三百篇，大底圣贤发愤之所为作也。",annotations:["演：推演","厄：困厄不得志","赋：创作","膑：名作动词，受膑刑","修列：编撰成书","迁：流放","底：通“抵”，大抵","发愤：抒发内心愤懑。"],translation:"周文王被拘禁，才推演出《周易》；孔子身处困厄，才创作《春秋》；屈原遭到流放，于是写下《离骚》；左丘明双目失明，才有《国语》传世；孙膑遭受膑刑，《孙膑兵法》才编撰完成；吕不韦流放蜀地，《吕氏春秋》流传世间；韩非被秦国囚禁，写下《说难》《孤愤》；《诗经》三百篇，大抵都是圣贤抒发愤懑而创作。"},{text:"此人皆意有所郁结，不得通其道，故述往事、思来者。",annotations:["郁结：苦闷积压","通其道：实现理想主张","思来者：寄望后世读懂自己。"],translation:"这些人心中都有苦闷积压，理想主张无法实现，所以记述过往史事，寄希望于后世之人理解自己。"},{text:"乃如左丘无目，孙子断足，终不可用，退而论书策，以舒其愤，思垂空文以自见。",annotations:["舒：抒发","垂：流传","空文：文章著作","见(xiàn)：通“现”，显露志向。"],translation:"就像左丘明失明、孙膑断足，终生不能被当权者重用，便退隐著书，抒发心中愤懑，希望通过文章流传后世，显露自身志向。"},{text:"仆窃不逊，近自托于无能之辞，网罗天下放失旧闻，略考其行事，综其终始，稽其成败兴坏之纪，上计轩辕，下至于兹，为十表，本纪十二，书八章，世家三十，列传七十，凡百三十篇。",annotations:["不逊：不自量力","放失(yì)：散失","稽：考察","纪：规律","轩辕：黄帝","兹：汉武帝当下","凡：总共。"],translation:"我私下不自量力，近来依托浅陋文笔，搜集天下散失的旧史传闻，简略考证史实，梳理事件始末，考察历代成败兴衰的规律，上从黄帝算起，下到当今时代，写成十篇年表、十二篇本纪、八篇书、三十篇世家、七十篇列传，总共一百三十篇。"},{text:"亦欲以究天人之际，通古今之变，成一家之言。",annotations:["究：探究","天人之际：天道与人事的关联","通：通晓。"],translation:"也想要借此探究天道与人事的关联，通晓从古至今的历史变革，形成独成一派的史学观点。"},{text:"草创未就，会遭此祸，惜其不成，是以就极刑而无愠色。",annotations:["就：完成","极刑：宫刑","愠(yùn)：怨恨。"],translation:"书稿草稿尚未完成，恰逢遭遇这场灾祸，我惋惜史书不能写完，因此承受宫刑也没有怨恨神色。"},{text:"仆诚以著此书，藏之名山，传之其人，通邑大都，则仆偿前辱之责，虽万被戮，岂有悔哉！",annotations:["其人：能理解、传承此书的后人","责：通“债”，代指宫刑屈辱","戮：羞辱、杀戮。"],translation:"如果我真能完成这部《史记》，把书稿藏在名山，传给可托付的后人，流传到四通八达的大城，那我就能偿还此前受宫刑的屈辱，就算遭受万般羞辱，又哪里会有悔恨！"},{text:"然此可为智者道，难为俗人言也！",annotations:["道：诉说讲明。"],translation:"可这番心思只能和明白人讲，很难对世俗之人说明白！"},{text:"且负下未易居，下流多谤议。",annotations:["负下：身负屈辱污名","下流：地位卑贱","谤议：非议诋毁。"],translation:"况且身负污辱的人难以立身，地位卑贱的人常常遭受非议。"},{text:"仆以口语遇遭此祸，重为乡党戮笑，以污辱先人，亦何面目复上父母之丘墓乎？",annotations:["口语：替李陵辩白的言论","重：深深","戮笑：耻笑。"],translation:"我因为替李陵辩白而遭遇这场灾祸，深深被同乡耻笑，玷污羞辱先祖，还有什么脸面再去父母坟前祭拜？"},{text:"虽累百世，垢弥甚耳！",annotations:["累：历经","垢：耻辱","弥：更加。"],translation:"就算历经百代，这份耻辱只会更加深重！"},{text:"是以肠一日而九回，居则忽忽若有所亡，出则不知其所往。",annotations:["九回：愁肠反复缠绕","忽忽：恍惚失神","亡：丢失。"],translation:"因此我整日内心愁肠百转，在家就恍惚失神像丢了魂魄，出门也不知道要去往何处。"},{text:"每念斯耻，汗未尝不发背沾衣也！",annotations:["斯：这","发背：从后背冒出冷汗。"],translation:"每次想到这份耻辱，后背总会冒出冷汗浸湿衣衫！"},{text:"身直为闺阁之臣，宁得自引深藏于岩穴邪？",annotations:["直：只不过","闺阁之臣：宦官一类刑余之人","自引：自行引退","岩穴：山林隐居之地。"],translation:"我只不过是形同宦官的刑余之人，又怎能自行退隐，深藏山林隐居？"},{text:"故且从俗浮沉，与时俯仰，以通其狂惑。",annotations:["浮沉、俯仰：随世俗周旋","通：抒发排解","狂惑：内心愤懑矛盾。"],translation:"所以只能暂且随世俗沉浮，顺应时势周旋，来排解心中的愤懑苦闷。"},{text:"今少卿乃教以推贤进士，无乃与仆私心剌谬乎？",annotations:["无乃……乎：恐怕……吧","剌(là)谬：违背、相悖。"],translation:"如今你反倒劝我推举贤才，这恐怕和我内心的想法完全相悖吧？"},{text:"今虽欲自雕琢，曼辞以自饰，无益，于俗不信，适足取辱耳。",annotations:["雕琢：美化自己","曼辞：华丽辞藻","适：只、仅仅。"],translation:"如今就算我想自我美化，用华丽言辞修饰自己，也毫无用处，世俗之人不会相信，只会自取羞辱。"},{text:"要之，死日然后是非乃定。",annotations:["要之：总而言之","乃：才。"],translation:"总而言之，人到死去那天，一生的是非功过才能盖棺定论。"},{text:"书不能悉意，故略陈固陋。",annotations:["悉：完整说尽","固陋：浅鄙想法。"],translation:"书信无法写尽全部心意，因此简略陈述我浅陋的想法。"},{text:"谨再拜。",annotations:["书信结尾敬语，恭敬拜上。"],translation:"恭敬再拜。"}]},19:{id:"19",title:"巫山巫峡",source:"《水经注》",paragraphs:[{text:"江水又东，迳巫峡，杜宇所凿以通江水也。",annotations:["东：名作状，向东",'迳：通"径"，经过',"杜宇：古蜀帝望帝。"],translation:"江水又向东流，经过巫峡，这是古蜀帝杜宇开凿来疏导江水的地方。"},{text:'郭仲产云："按地理志，巫山在县西南，而今县东有巫山，将郡县居治无恒故也！"',annotations:["按：依据","居治：治所驻地","无恒：不固定。"],translation:'郭仲产说："依据《地理志》，巫山在巫县西南，可如今县城东边也有巫山，大概是郡县治所迁移、驻地不固定的缘故！"'},{text:"江水历峡，东，迳新崩滩。",annotations:["历：流过","迳：经过。"],translation:"江水穿过巫峡，向东，流经新崩滩。"},{text:"此山汉和帝永元十二年崩，晋太元二年又崩。",annotations:["崩：山体崩塌。"],translation:"这座山体在汉和帝永元十二年崩塌，晋太元二年又一次崩塌。"},{text:"当崩之日，水逆流百余里，涌起数十丈。",annotations:[],translation:"山体崩塌那天，江水向西倒流一百多里，浪涛涌起几十丈高。"},{text:"今滩上有石，或圆如箪，或方似笥，若此者甚众，皆崩崖所陨，致怒湍流，故谓之新崩滩。",annotations:["箪(dān)：圆形竹筐","笥(sì)：方形竹箱","陨：坠落","怒：使……汹涌。"],translation:"如今滩上遍布石块，有的圆如竹筐，有的方似木箱，这样的石头非常多，全是崩塌山崖坠落下来的，使湍急江水汹涌激荡，所以此地叫新崩滩。"},{text:"其颓岩所余，比之诸岭，尚为竦桀。",annotations:["颓岩：崩塌后剩余山崖","竦(sǒng)桀：高耸突出。"],translation:"崩塌后残留的山崖，和周围山岭相比，依旧高耸挺拔。"},{text:"其下十余里，有大巫山，非惟三峡所无，乃当抗峰岷峨，偕岭衡疑；",annotations:["非惟：不只","抗峰：山峰可与……抗衡","岷峨：岷山、峨眉山","偕：并列","衡疑：衡山、九疑山。"],translation:"新崩滩往下十余里，有大巫山，它的山势不只是三峡其他山岭比不上，山峰高度足以和岷山、峨眉抗衡，能与衡山、九疑并列。"},{text:"其翼附群山，并概青云，更就霄汉辨其优劣耳！",annotations:["翼附：像翅膀一样簇拥依附","概：触及","霄汉：高空云天。"],translation:"大巫山像翅膀一样簇拥周围群山，山顶一同触碰青云，要到云天之上才能分辨它与群山的高下！"},{text:"神孟涂所处。",annotations:["处：居住、驻守。"],translation:"这里是天神孟涂驻守的地方。"},{text:'《山海经》曰："夏后启之臣孟涂，是司神于巴，巴人讼于孟涂之所，其衣有血者执之，是请生，居山上，在丹山西。"',annotations:["夏后启：夏朝君主启","司神：掌管神明事务","讼：打官司","执：抓捕","请生：好生不滥杀。"],translation:'《山海经》记载："夏朝君主启的臣子孟涂，在巴地掌管神明断案之事，巴人到孟涂处诉讼，只要衣服沾有血迹的人就抓捕，他心存好生之德，居住在这座山上，位置在丹山的西面。"'},{text:'郭景纯云："丹山在丹阳，属巴。"',annotations:["郭景纯：郭璞，字景纯","属巴：隶属于巴郡。"],translation:'郭璞说："丹山在丹阳，隶属于巴郡。"'},{text:"丹山西即巫山者也。",annotations:[],translation:"丹山的西面，就是这座巫山。"},{text:"又帝女居焉。",annotations:["帝女：天帝之女瑶姬。"],translation:"天帝的小女儿也居住在这里。"},{text:'宋玉所谓："天帝之季女，名曰瑶姬，未行而亡，封于巫山之阳。精魂为草，寔为灵芝。"',annotations:["季女：小女儿","未行：未出嫁","阳：山南面",'寔：通"实"，其实。'],translation:'宋玉文中所说："天帝最小的女儿名叫瑶姬，还未出嫁就去世了，葬在巫山南面。她的魂魄化作草木，实际就是灵芝。"'},{text:'所谓"巫山之女，高唐之阻，旦为行云，暮为行雨，朝朝暮暮，阳台之下。"',annotations:["高唐之阻：高唐险峻之处","旦：清晨","阳台：巫山南侧台地。"],translation:'也就是宋玉写的："巫山神女，栖身高唐险地，清晨化作流云，傍晚化作细雨，日日夜夜，徘徊在阳台之下。"'},{text:"旦早视之，果如其言。",annotations:[],translation:"清晨前去观望，景象果然和他说的一样。"},{text:"故为立庙，号朝云焉。",annotations:[],translation:"因此人们为她修建庙宇，命名为朝云庙。"},{text:"其间首尾百六十里，谓之巫峡，盖因山为名也。",annotations:["首尾：从峡头到峡尾","盖：大概","因山为名：依托巫山得名。"],translation:"从峡首到峡尾全长一百六十里，称作巫峡，大概是依托巫山而得名。"},{text:"自三峡七百里中，两岸连山，略无阙处。",annotations:['阙：通"缺"，缺口、空隙。'],translation:"在三峡七百里范围之内，两岸山连着山，完全没有一点空隙。"},{text:"重岩叠嶂，隐天蔽日；",annotations:["嶂：高峻像屏障的山。"],translation:"层层山崖、重重屏障似的山峰，遮蔽天空、挡住日光。"},{text:"自非亭午夜分，不见曦月。",annotations:["自非：如果不是","亭午：正午","夜分：半夜","曦：日光，代太阳。"],translation:"如果不是正午、半夜，就看不见太阳和月亮。"},{text:"至于夏水襄陵，沿溯阻绝；",annotations:["襄陵：水漫上山陵","沿：顺流而下","溯：逆流而上。"],translation:"到了夏季江水暴涨漫上山陵，顺流、逆流的航道全被阻断。"},{text:"或王命急宣，有时朝发白帝，暮到江陵，其间千二百里，虽乘奔御风，不以疾也。",annotations:["或：倘若","奔：飞奔的马","不以：不如。"],translation:"倘若有朝廷命令急需传达，有时清晨从白帝城出发，傍晚就能抵达江陵，两地相距一千二百里，就算骑着快马、驾着疾风，也没有江水行船快。"},{text:"春冬之时，则素湍绿潭，回清倒影；",annotations:["素湍：白色急流","潭：深水潭","回清：回旋的清波。"],translation:"春、冬两季，白色急流奔涌，碧绿深潭平静，回旋清波倒映两岸山色。"},{text:"绝巘多生怪柏，悬泉瀑布，飞漱其间；",annotations:["绝巘(yǎn)：极高的山峰","飞漱：飞速冲刷、飞溅。"],translation:"极高的山峰上生长着奇形怪状的柏树，悬空的泉水与瀑布，在山林间飞溅冲刷。"},{text:"清荣峻茂，良多趣味。",annotations:["清：水清","荣：树荣","峻：山高","茂：草盛","良：实在、很。"],translation:"江水清澈、树木繁茂、山峰高峻、草木丰茂，实在有很多趣味。"},{text:"每至晴初霜旦，林寒涧肃；",annotations:["晴初：雨后初晴","霜旦：下霜的清晨","肃：清冷寂静。"],translation:"每到雨后初晴、清晨下霜的日子，山林清冷，山涧寂静萧条。"},{text:"常有高猿长啸，属引凄异，空谷传响，哀转久绝。",annotations:["属(zhǔ)引：连续不断","凄异：凄凉怪异","绝：消散停止。"],translation:"时常有高处的猿猴拉长声音啼叫，叫声连续不断、凄凉怪异，空旷山谷传来回声，哀婉婉转很久才消散。"},{text:'故渔者歌曰："巴东三峡巫峡长，猿鸣三声泪沾裳！"',annotations:[],translation:'所以打鱼的人传唱歌谣："巴东三峡巫峡最长，猿啼几声，泪水就打湿衣裳！"'},{text:"江水又东径石门滩。",annotations:["径：经过。"],translation:"江水再向东流，经过石门滩。"},{text:"滩北岸有山，山上合下开，洞达东西，缘江步路所由，",annotations:["洞达：贯通","缘江：沿江","所由：通行的道路。"],translation:"石门滩北岸有一座山，山体上部合拢、下部分开，山洞东西贯通，是沿江步行道路必经之处。"},{text:"刘备为陆逊所破，走径此门，追者甚急，备乃烧铠断道。",annotations:["为……所：被动句式，被","铠：铠甲","断道：烧毁道路阻断追兵。"],translation:"刘备被陆逊打败，逃跑时经过这座石门，追兵追赶十分急迫，刘备就烧毁铠甲、阻断山路。"},{text:"孙桓为逊前驱，奋不顾命，斩上夔道，截其要径，",annotations:["前驱：先锋","夔道：通往夔州的道路","要径：要道。"],translation:"孙桓担任陆逊的先锋，奋勇作战不顾性命，一路冲杀到夔州要道，截断刘备必经之路。"},{text:"备逾山越险，仅乃得免，忿恚而叹曰：吾昔至京，桓尚小儿。而今迫孤，乃至于此。",annotations:["逾：翻越","忿恚(huì)：愤恨恼怒","孤：刘备自称。"],translation:"刘备翻过高山险隘，才勉强脱身脱险，愤恨叹息说：我当初到东吴京城时，孙桓还是个小孩子。如今竟逼迫我到这般境地。"},{text:"遂发愤而薨矣。",annotations:["薨(hōng)：古代王侯去世称薨。"],translation:"刘备最终心中愤懑，病逝白帝城。"}]},20:{id:"20",title:"张中丞传后叙",source:"韩愈",paragraphs:[{text:"元和二年四月十三日夜，愈与吴郡张籍阅家中旧书，得李翰所为《张巡传》。",annotations:["元和：唐宪宗年号","张籍：唐代诗人","李翰：张巡友人，曾写《张巡传》","为：撰写。"],translation:"元和二年四月十三日夜晚，我和吴郡人张籍翻阅家中旧藏书，看到李翰所写的《张巡传》。"},{text:"翰以文章自名，为此传颇详密。",annotations:["自名：自负、自许擅长文章","详密：详尽周密。"],translation:"李翰一向以擅长文章自许，这篇传记写得十分详尽周密。"},{text:"然尚恨有阙者：不为许远立传，又不载雷万春事首尾。",annotations:['阙：通"缺"，缺失',"许远：睢阳太守，与张巡同守睢阳","雷万春：张巡麾下猛将","首尾：始末完整事迹。"],translation:"可仍有遗憾缺失之处：没有为许远立传，也没有完整记载雷万春事迹的始末。"},{text:"远虽材若不及巡者，开门纳巡，位本在巡上，授之柄而处其下，无所疑忌，竟与巡俱守死，成功名。",annotations:["纳：接纳","柄：兵权","处其下：甘愿居于张巡之下","俱守死：一同守城殉国。"],translation:"许远才干看似比不上张巡，却打开城门接纳张巡，自己官位本在张巡之上，把兵权交给张巡，甘愿位居其下，没有丝毫猜忌，最终和张巡一同守城殉国，成就忠烈美名。"},{text:"城陷而虏，与巡死先后异耳。",annotations:["虏：被俘虏","异：只是先后不同。"],translation:"睢阳城破被俘，只是他和张巡牺牲时间有先后差别罢了。"},{text:"两家子弟材智下，不能通知二父志，以为巡死而远就虏，疑畏死而辞服于贼。",annotations:["通知：透彻理解","就虏：被俘","辞服：投降屈服。"],translation:"两家子弟才智低下，不能完全明白两位父亲的志向，认为张巡战死、许远被俘，怀疑许远贪生怕死，向叛贼投降。"},{text:"远诚畏死，何苦守尺寸之地，食其所爱之肉，以与贼抗而不降乎？",annotations:["诚：如果真","尺寸之地：狭小睢阳城","所爱之肉：指杀爱妾分肉给士兵充饥。"],translation:"许远倘若真的怕死，何苦死守这座小城，甚至杀掉自己爱妾分肉给士兵，奋力抵抗叛军而不肯投降？"},{text:"当其围守时，外无蚍蜉蚁子之援，所欲忠者，国与主耳。",annotations:["蚍蜉：蚂蚁，比喻微弱援军","主：君主。"],translation:"当睢阳被围困之时，城外连一丝微弱援军都没有，他心中所要效忠的，只有国家与君主。"},{text:"贼语以国亡主灭，远见救援不至，而贼来益众，必以其言为信。",annotations:["益众：越来越多","信：真实可信。"],translation:"叛贼对他宣称国家覆灭、君主身死，许远眼看救兵迟迟不到，叛军越来越多，本该相信叛贼的话。"},{text:"外无待而犹死守，人相食且尽，虽愚人亦能数日而知死处矣。",annotations:["待：指望援军","且尽：快要吃光","数(shǔ)日：算出时日。"],translation:"城外毫无指望，却依旧死守，城中人吃人都快要吃光，就算愚笨之人也能算出死期将近。"},{text:"远之不畏死亦明矣！乌有城坏其徒俱死，独蒙愧耻求活？虽至愚者不忍为。",annotations:["乌有：哪有","城坏：城池陷落","徒：部下","蒙愧耻：背负耻辱苟活。"],translation:"许远不怕死已经十分清楚！哪有城池陷落、部下全部殉难，唯独自己背负耻辱苟且偷生？就算最愚钝的人也不忍心做这种事。"},{text:"呜呼！而谓远之贤而为之邪！",annotations:[],translation:"唉！更何况许远这样贤明之人，难道会做出这种事吗！"},{text:"说者又谓远与巡分城而守，城之陷，自远所分始，以此诟远。",annotations:["分城而守：二人分守睢阳城两面","诟(gòu)：诋毁、指责。"],translation:"还有人说许远和张巡分守城池，城池失守是从许远分管的区域先攻破，拿这件事诋毁许远。"},{text:"此又与儿童之见无异。",annotations:[],translation:"这种看法又和小孩子见识没有区别。"},{text:"人之将死，其脏腑必有先受其病者；引绳而绝之，其绝必有处。",annotations:["引：拉扯","绝：断裂。"],translation:"人将要死时，内脏一定有先受损病变的地方；拉扯绳子把它扯断，绳子也一定有先断裂的位置。"},{text:"观者见其然，从而尤之，其亦不达于理矣。",annotations:["尤：怪罪","达：通晓。"],translation:"旁观之人看到这种结果，就去怪罪最先受损、断裂之处，这也是不通事理。"},{text:"小人之好议论，不乐成人之美如是哉！",annotations:["成人之美：成全别人的美名功业。"],translation:"小人喜好搬弄是非，不愿成全他人美名，竟到这种地步！"},{text:"如巡、远之所成就，如此卓卓，犹不得免，其他则又何说！",annotations:["卓卓：卓越出众","免：免于诋毁。"],translation:"像张巡、许远立下这般卓越功勋，尚且免不了被人诋毁，其他人还有什么可说！"},{text:"当二公之初守也，宁能知人之卒不救，弃城而逆遁？",annotations:["卒：最终","逆遁：预先逃跑。"],translation:"当初二公守城之时，怎能料到援军最终不来，就丢下城池预先逃走？"},{text:"苟此不能守，虽避之他处何益？",annotations:["苟：假如。"],translation:"假如睢阳守不住，就算逃到别处又有什么用处？"},{text:"及其无救而且穷也，将其创残饿羸之余，虽欲去，必不达。",annotations:["穷：陷入绝境","创残饿羸(léi)：受伤、瘦弱饥饿的士兵","去：撤离。"],translation:"等到救兵不至、陷入绝境，带着这群负伤饥饿的残兵，就算想撤退，也一定走不到安全之地。"},{text:"二公之贤，其讲之精矣！",annotations:["讲：谋划考量","精：周密周全。"],translation:"以二公的贤明，对局势早已谋划得十分周密！"},{text:"守一城，捍天下，以千百就尽之卒，战百万日滋之师，蔽遮江淮，沮遏其势，天下之不亡，其谁之功也！",annotations:["捍：保卫","就尽：濒临耗尽","日滋：日渐增多","蔽遮：掩护","沮遏：阻挡遏制叛军攻势。"],translation:"守住一座睢阳城，保卫整个天下，凭借千百名濒临绝境的士兵，对抗百万日渐增多的叛军，掩护江淮大地，遏制叛军南下势头，大唐没有覆灭，这是谁的功劳！"},{text:"当是时，弃城而图存者，不可一二数；擅强兵坐而观者，相环也。",annotations:["一二数：一一列举","擅：拥有","相环：到处都是。"],translation:"在那时，丢下城池只求自保的将领数不胜数；手握重兵坐视不救的人遍地都是。"},{text:"不追议此，而责二公以死守，亦见其自比于逆乱，设淫辞而助之攻也。",annotations:["追议：追责评判","自比于逆乱：把自己等同于叛贼","淫辞：歪曲不实的流言。"],translation:"不去追责批判这些逃兵、观望之人，反而指责二公死守城池，足见说这话的人等同于叛贼，编造不实流言帮叛军攻击忠良。"},{text:"余尝从事于汴徐二府，屡道于两府间，亲祭于其所谓双庙者。",annotations:["从事：任职幕僚","道：路过","双庙：后人合祀张巡、许远的祠庙。"],translation:"我曾经在汴州、徐州幕府任职，多次往返两州之间，亲自到当地人所说的双庙祭拜二公。"},{text:"其老人往往说巡、远时事，云：雷万春之将兵，有勇有谋。",annotations:[],translation:"当地老人常常说起张巡、许远守城旧事，说：雷万春领兵，有勇有谋。"},{text:"贼尝以弩射万春，面中六矢而不动。",annotations:["弩：弓弩","矢：箭。"],translation:"叛军曾用弓弩射雷万春，脸上中了六支箭，他仍旧屹立不动。"},{text:"贼遥识之，以为木人，及审知其为万春，大惊。",annotations:["审知：仔细看清。"],translation:"叛军远远望见，以为是木头人，等看清是雷万春本人，大为惊骇。"},{text:"又有于嵩者，少依于巡；及巡起事，嵩常在围中。",annotations:["于嵩：张巡部下","依：依附跟随","起事：起兵抗贼。"],translation:"还有一位叫于嵩的人，年少跟随张巡；张巡起兵抗敌时，于嵩一直被困在睢阳围城之中。"},{text:"大历中，余过宋州，嵩尚在，问巡事甚悉。",annotations:["大历：唐代宗年号","悉：详尽完整。"],translation:"大历年间，我路过宋州，于嵩还在世，我向他详细询问张巡的事迹。"},{text:"嵩云：巡长七尺余，须髯若神。",annotations:["须髯：胡须。"],translation:"于嵩说：张巡身高七尺多，胡须长得如同天神一般威严。"},{text:'尝见嵩读《汉书》，谓嵩曰："何为久读此？"',annotations:[],translation:'曾经看见于嵩读《汉书》，对他说："为什么长久读这部书？"'},{text:'嵩曰："未熟也。"',annotations:[],translation:'于嵩说："还没有读熟。"'},{text:'巡曰："吾于书，读不过三遍，终身不忘也。"',annotations:[],translation:"张巡说：我读书，不超过三遍，一辈子都不会忘记。"},{text:"因诵嵩所读书，尽卷不错一字。",annotations:["尽卷：整卷书。"],translation:"随即背诵于嵩正在读的书卷，整卷一字不差。"},{text:"嵩惊，以为巡偶熟此卷，因乱抽他帙以试，无不尽然。",annotations:["帙(zhì)：书卷","尽然：全都背诵无误。"],translation:"于嵩十分吃惊，以为张巡只是恰好熟悉这一卷，于是随意抽取其他书卷测试，张巡全都能完整背诵。"},{text:"嵩又取架上诸书，试以问巡，巡应口诵无疑。",annotations:["应口：随口","无疑：毫无迟疑。"],translation:"于嵩又拿书架上各类书籍，出题考张巡，张巡随口背诵，没有一丝迟疑。"},{text:"嵩从巡久，亦不见巡常读书也。",annotations:[],translation:"于嵩跟随张巡多年，平时却很少看见张巡刻意读书。"},{text:"为文章，操纸笔立书，未尝起草。",annotations:["立书：提笔立刻写成。"],translation:"写文章时，拿起纸笔一挥而就，从不打草稿。"},{text:"初守睢阳时，士卒仅万人，城中居人户，亦且数万，巡因一见问姓名，其后无不识者。",annotations:["仅万人：近万人","且数万：将近数万","因一见：只要见过一次。"],translation:"刚守睢阳时，士兵近万人，城中百姓也有数万，张巡只要见过一面、问过姓名，之后没有不认得的。"},{text:"巡怒，须髯辄张。",annotations:["辄：立刻","张：张开竖起。"],translation:"张巡发怒时，胡须全都竖起来。"},{text:"及城陷，贼缚巡等数十人坐，且将戮。",annotations:["戮：处死。"],translation:"等到城池陷落，叛军捆绑张巡等几十人让他们坐着，即将行刑。"},{text:"巡起旋，其众见巡起，或起或泣。",annotations:["起旋：起身转圈","泣：落泪。"],translation:"张巡起身转身，部下看见他站起来，有的起身、有的落泪。"},{text:'巡曰："汝勿怖！死，命也。"众泣不能仰视。',annotations:["怖：害怕。"],translation:"张巡说：你们不要害怕！为国赴死，是命中注定。众人痛哭，不敢抬头看他。"},{text:"巡就戮时，颜色不乱，阳阳如平常。",annotations:["颜色不乱：神色不变","阳阳：从容安详。"],translation:"张巡赴死之时，神色丝毫不变，从容平和如同平日。"},{text:"远宽厚长者，貌如其心；与巡同年生，月日后于巡，呼巡为兄，死时年四十九。",annotations:[],translation:"许远是宽厚长者，外貌和心性一样温和；和张巡同年出生，生辰比张巡晚，称张巡为兄长，牺牲时四十九岁。"},{text:"嵩贞元初死于亳宋间。或传嵩有田在亳宋间，武人夺而有之，嵩将诣州讼理，为所杀。",annotations:["诣：前往","讼理：告状申诉","为所杀：被动句，被武人杀害。"],translation:"于嵩贞元初年死在亳州、宋州一带。有人说于嵩在当地有田地，被武将强占，于嵩准备去州府告状，被那名武将杀害。"},{text:"嵩无子。张籍云。",annotations:[],translation:"于嵩没有后代。以上都是张籍告诉我的。"}]},21:{id:"21",title:"钴鉧潭西小丘记",source:"柳宗元",paragraphs:[{text:"得西山后八日，寻山口西北道二百步，又得钴鉧潭。",annotations:["得：寻访发现","道：名作动词，行走","步：古代长度单位","钴鉧(gǔ mǔ)潭：潭形如熨斗得名。"],translation:"发现西山后的第八天，沿着山口向西北走两百步，又寻见了钴鉧潭。"},{text:"西二十五步，当湍而浚者为鱼梁。",annotations:["湍：湍急水流","浚(jùn)：水深","鱼梁：拦水捕鱼的石堰。"],translation:"潭西边二十五步，在水流湍急、水深之处筑有捕鱼石堰。"},{text:"梁之上有丘焉，生竹树。",annotations:[],translation:"石堰上方有一座小土丘，上面长满竹子树木。"},{text:"其石之突怒偃蹇，负土而出，争为奇状者，殆不可数。",annotations:["突怒：山石突兀耸立","偃蹇(yǎn jiǎn)：高耸盘曲","殆：几乎。"],translation:"丘上的山石突兀高耸、盘曲起伏，顶着泥土破土而出，竞相呈现奇特姿态，几乎数不清。"},{text:"其嵚然相累而下者，若牛马之饮于溪；",annotations:["嵚(qīn)然：高耸的样子","相累：层层堆叠","饮于溪：状语后置，在溪边饮水。"],translation:"那些层层堆叠、向下倾斜的石头，好像牛马俯身到溪边饮水；"},{text:"其冲然角列而上者，若熊罴之登于山。",annotations:["冲然：向前突起","角列：像兽角并列","罴(pí)：大熊。"],translation:"那些向前高耸、如兽角并列向上的石头，如同熊罴向山上攀登。"},{text:"丘之小不能一亩，可以笼而有之。",annotations:["不能：不足","笼：名作动词，装进笼子，形容极小。"],translation:"小丘面积不足一亩，小得仿佛可以整个装起来占有。"},{text:'问其主，曰："唐氏之弃地，货而不售。"',annotations:["货：名作动词，出售","售：卖出。"],translation:'我询问土地主人，主人说："这是唐家废弃的土地，想卖却一直卖不出去。"'},{text:'问其价，曰："止四百。"',annotations:["止：只，仅仅。"],translation:'我询问地价，主人说："只卖四百文。"'},{text:"余怜而售之。",annotations:["怜：喜爱、怜惜","售之：使动，把它买下来。"],translation:"我十分喜爱这座小丘，就把它买了下来。"},{text:"李深源、元克己时同游，皆大喜，出自意外。",annotations:[],translation:"李深源、元克己当时和我一同游览，全都十分欢喜，完全出乎意料。"},{text:"即更取器用，铲刈秽草，伐去恶木，烈火而焚之。",annotations:["更取：轮番拿来","刈(yì)：割","秽草、恶木：杂乱野草、劣质杂树","烈火：名作动词，燃起大火。"],translation:"我们立刻轮番拿来农具，铲除杂草，砍掉难看杂树，燃起大火把它们烧掉。"},{text:"嘉木立，美竹露，奇石显。",annotations:["嘉：美好。"],translation:"好看的树木挺立出来，秀美的竹子显露身姿，奇特山石完全展现出来。"},{text:"由其中以望，则山之高，云之浮，溪之流，鸟兽之遨游，举熙熙然回巧献技，以效兹丘之下。",annotations:["举：全","熙熙然：和乐自在","回巧献技：轮番展现美好姿态","效：呈献。"],translation:"站在丘中远望，高耸的群山、漂浮的云彩、流淌的溪水、自在游荡的鸟兽，全都和乐地轮番展示天然妙态，在这座小丘之下呈献美景。"},{text:"枕席而卧，则清泠之状与目谋，瀯瀯之声与耳谋，悠然而虚者与神谋，渊然而静者与心谋。",annotations:["枕席：名作动词，铺枕席躺下","清泠(líng)：清凉明净","谋：相融、相会","瀯(yíng)瀯：溪水潺潺声","渊然：幽深沉静。"],translation:"铺席躺卧在丘上，清凉明净的风光映入眼帘，潺潺流水之声萦绕耳畔，悠远空阔的意境与精神相融，幽深静谧的氛围贴合内心。"},{text:"不匝旬而得异地者二，虽古好事之士，或未能至焉。",annotations:["匝(zā)旬：满十天","异地：奇异胜地","好事之士：喜爱山水、寻访美景的人。"],translation:"不到十天就寻得两处奇异美景，就算古时酷爱山水的人，或许也难有这般际遇。"},{text:"噫！以兹丘之胜，致之沣、镐、鄠、杜，则贵游之士争买者，日增千金而愈不可得。",annotations:["胜：美景","沣(fēng)、镐(hào)、鄠(hù)、杜：长安周边贵族聚居之地","贵游之士：达官贵人","千金：大量钱财。"],translation:"唉！凭这座小丘的优美景致，如果把它放到长安近郊沣、镐、鄠、杜一带，达官贵人定会争相购买，就算每日加价千金，也越发难以买到。"},{text:"今弃是州也，农夫渔父，过而陋之，贾四百，连岁不能售。",annotations:["陋：意动，以……为粗劣、看不起",'贾(jià)：通"价"，价格',"连岁：连年。"],translation:"如今它被遗弃在永州，农夫渔夫路过都看不起它，地价仅四百文，连年都卖不出去。"},{text:"而我与深源、克己独喜得之，是其果有遭乎！",annotations:["遭：际遇、赏识它的机遇。"],translation:"可唯独我和深源、克己欣喜地得到它，这座小丘果真遇上了赏识它的机缘啊！"},{text:"书于石，所以贺兹丘之遭也。",annotations:["书：书写","所以：用来……的方式。"],translation:"把这篇文章刻写在石头上，用来庆贺这座小丘遇上了赏识它的机遇。"}]},22:{id:"22",title:"六国论",source:"苏洵",paragraphs:[{text:"六国破灭，非兵不利，战不善，弊在赂秦。",annotations:["兵：兵器","利：锋利","弊：弊病","赂(lù)秦：割地贿赂秦国。"],translation:"六国灭亡，不是兵器不锋利，仗打得不好，弊病在于割地贿赂秦国。"},{text:"赂秦而力亏，破灭之道也。",annotations:["亏：亏损、削弱","道：原因","判断句。"],translation:"贿赂秦国就使自身国力削弱，这是灭亡的原因。"},{text:"或曰：六国互丧，率赂秦耶？",annotations:["或：有人","互丧：相继灭亡","率：全都、一概。"],translation:"有人问：六国相继灭亡，全都是因为贿赂秦国吗？"},{text:"曰：不赂者以赂者丧。",annotations:["以：因为。"],translation:"回答说：不贿赂秦国的国家因为贿赂秦国的国家而灭亡。"},{text:"盖失强援，不能独完。",annotations:["盖：表原因，是因为","完：保全。"],translation:"因为失去了强大的外援，不能独自保全。"},{text:"故曰：弊在赂秦也。",annotations:[],translation:"所以说：弊病在于割地贿赂秦国。"},{text:"秦以攻取之外，小则获邑，大则得城。",annotations:["以：凭借","攻取：战争夺取","邑：小城邑。"],translation:"秦国除了靠战争夺取土地之外，（诸侯主动割地）小的就得到邑镇，大的就得到城池。"},{text:"较秦之所得，与战胜而得者，其实百倍；",annotations:["实：实际数量。"],translation:"把秦国受贿得来的土地，和战胜夺取的土地相比，前者实际是后者的百倍；"},{text:"诸侯之所亡，与战败而亡者，其实亦百倍。",annotations:["亡：丢失（土地）。"],translation:"诸侯割地失去的土地，和战败丢失的土地相比，前者实际也是后者的百倍。"},{text:"则秦之所大欲，诸侯之所大患，固不在战矣。",annotations:["固：本来。"],translation:"那么秦国最大的欲望，诸侯最大的祸患，本来就不在于战争。"},{text:"思厥先祖父，暴霜露，斩荆棘，以有尺寸之地。",annotations:["厥：他们的","先祖父：祖辈父辈","暴(pù)：暴露，冒着","以：才。"],translation:"想想他们的祖辈父辈，冒着霜露，披荆斩棘，才得到一点点土地。"},{text:"子孙视之不甚惜，举以予人，如弃草芥。",annotations:["举：全部拿出来","草芥：小草，比喻微不足道之物。"],translation:"子孙看待这些土地却不怎么爱惜，拿来送给别人，如同丢弃小草。"},{text:"今日割五城，明日割十城，然后得一夕安寝。",annotations:[],translation:"今天割五座城，明天割十座城，换来一夜安稳睡眠。"},{text:"起视四境，而秦兵又至矣。",annotations:[],translation:"可第二天起来看四方边境，秦国军队又打过来了。"},{text:"然则诸侯之地有限，暴秦之欲无厌，奉之弥繁，侵之愈急。",annotations:['厌：通"餍"，满足',"奉：敬献","弥：越","急：猛烈。"],translation:"既然这样，诸侯的土地有限，残暴秦国的欲望永不满足，献给它的土地越多，它侵略各国就越急迫。"},{text:"故不战而强弱胜负已判矣。",annotations:["判：分清、确定。"],translation:"所以不用交战，强弱胜负就已经分明。"},{text:"至于颠覆，理固宜然。",annotations:["颠覆：灭亡","宜然：本该这样。"],translation:"走到灭亡的结局，道理本就该如此。"},{text:'古人云："以地事秦，犹抱薪救火，薪不尽，火不灭。"此言得之。',annotations:["事：侍奉、讨好","薪：柴草","得之：说中这个道理。"],translation:'古人说："用土地讨好秦国，就像抱着柴草救火，柴草不烧完，火就不会熄灭。"这话十分中肯。'},{text:"齐人未尝赂秦，终继五国迁灭，何哉？",annotations:["未尝：不曾","迁灭：灭亡。"],translation:"齐国不曾贿赂秦国，最终也跟着五国灭亡，为什么？"},{text:"与嬴而不助五国也。",annotations:["与：交好、依附","嬴：秦王嬴姓，代指秦国。"],translation:"因为它依附秦国，不援助其他五国。"},{text:"五国既丧，齐亦不免矣。",annotations:["既：已经","不免：无法幸免。"],translation:"五国灭亡之后，齐国也无法幸免。"},{text:"燕赵之君，始有远略，能守其土，义不赂秦。",annotations:["远略：长远谋略","义：坚持道义。"],translation:"燕国、赵国的君主，起初有长远谋略，能守住国土，坚守道义不贿赂秦国。"},{text:"是故燕虽小国而后亡，斯用兵之效也。",annotations:["是故：因此","效：成效。"],translation:"所以燕国虽是小国却最后灭亡，这是用兵抵抗的成效。"},{text:"至丹以荆卿为计，始速祸焉。",annotations:["丹：燕太子丹","荆卿：荆轲","速：招致。"],translation:"等到太子丹把派荆轲刺秦当作对策，才招致祸患。"},{text:"赵尝五战于秦，二败而三胜。",annotations:["状语后置，赵尝于秦五战。"],translation:"赵国曾经和秦国五次交战，两败三胜。"},{text:"后秦击赵者再，李牧连却之。",annotations:["再：两次","却：使动，使……退却，击退。"],translation:"后来秦国两次攻打赵国，李牧接连击退秦军。"},{text:"洎牧以谗诛，邯郸为郡，惜其用武而不终也。",annotations:["洎(jì)：等到","以谗诛：因谗言被杀","邯郸：赵国都城，代赵国","不终：不能坚持到底。"],translation:"等到李牧因谗言被杀害，赵国都城邯郸才变成秦国郡县，可惜赵国武力抗秦没能坚持到底。"},{text:"且燕赵处秦革灭殆尽之际，可谓智力孤危，战败而亡，诚不得已。",annotations:["革灭：消灭","殆：几乎","智力：古今异义，智谋与力量","诚：实在。"],translation:"况且燕、赵两国处在秦国把其他国家几乎消灭干净的时候，可以说是智谋和力量孤立危急，战败灭亡，实在迫不得已。"},{text:"向使三国各爱其地，齐人勿附于秦，刺客不行，良将犹在，则胜负之数，存亡之理，当与秦相较，或未易量。",annotations:["向使：假使","三国：韩、魏、楚","数、理：命运","量：估量、判断。"],translation:"假使韩、魏、楚三国各自爱惜国土，齐国不依附秦国，荆轲不前去行刺，李牧这样的良将还活着，那么胜负存亡的命运，倘若和秦国相较量，或许还不容易估量。"},{text:"呜呼！以赂秦之地封天下之谋臣，以事秦之心礼天下之奇才，并力西向，则吾恐秦人食之不得下咽也。",annotations:["礼：名作动，礼遇","西向：向西对抗秦国","下咽：吞下饭菜。"],translation:"唉！如果用贿赂秦国的土地封赏天下谋臣，用侍奉秦国的诚心礼遇天下奇才，合力向西对抗秦国，我恐怕秦国人连吃饭都咽不下去。"},{text:"悲夫！有如此之势，而为秦人积威之所劫，日削月割，以趋于亡。",annotations:["为……所：被动句式","积威：长期积累的威势","劫：胁迫","日、月：名作状，每日、每月。"],translation:"可悲啊！拥有这样有利的局势，却被秦国长期的威势胁迫，每日每月割让土地，一步步走向灭亡。"},{text:"为国者无使为积威之所劫哉！",annotations:["为国者：治理国家的人。"],translation:"治理国家的人千万不要让自己被别国长期威势胁迫啊！"},{text:"夫六国与秦皆诸侯，其势弱于秦，而犹有可以不赂而胜之之势。",annotations:["弱于秦：状语后置，比秦国弱","可以：古今异义，可以凭借。"],translation:"六国和秦国都是诸侯国，他们的势力比秦国弱，却还有不靠贿赂、战胜秦国的可能。"},{text:"苟以天下之大，下而从六国破亡之故事，是又在六国下矣。",annotations:["苟：假如","天下之大：指北宋一统天下","故事：古今异义，旧例、前车之鉴","下：比不上。"],translation:"假如凭着一统天下的大国，却自取下策，重蹈六国灭亡的旧路，这就连六国都比不上了。"}]},23:{id:"23",title:"留侯论",source:"苏轼",paragraphs:[{text:"古之所谓豪杰之士者，必有过人之节。",annotations:["节：节操、气度。"],translation:"古代所说的英雄豪杰，一定有超出常人的气度。"},{text:"人情有所不能忍者，匹夫见辱，拔剑而起，挺身而斗，此不足为勇也。",annotations:["匹夫：普通人","见辱：被动，被羞辱。"],translation:"常人遇到难以忍受的事，普通人一旦受辱，就拔剑起身，挺身搏斗，这算不上真正的勇敢。"},{text:"天下有大勇者，卒然临之而不惊，无故加之而不怒。",annotations:['卒：通"猝"，突然',"临之：祸事降临头上","加之：把侮辱加在身上。"],translation:"天下真正大勇的人，灾祸突然降临却不惊慌，无端遭受侮辱也不发怒。"},{text:"此其所挟持者甚大，而其志甚远也。",annotations:["挟持：心中怀抱的抱负、胸襟。"],translation:"这是因为他胸中怀抱宏大抱负，志向十分高远。"},{text:"夫子房受书于圯上之老人也，其事甚怪；",annotations:["子房：张良字","圯(yí)：桥","圯上老人：黄石公","状语后置，于圯上老人受书。"],translation:"张良从桥上老人那里得到兵书，这件事看起来十分离奇；"},{text:"然亦安知其非秦之世，有隐君子者出而试之。",annotations:["安知：怎么知道","隐君子：隐居的有德高人","试之：考验张良。"],translation:"可又怎么能断定，这不是秦朝一位隐居高士出来考验他呢。"},{text:"观其所以微见其意者，皆圣贤相与警戒之义；",annotations:["微见(xiàn)：含蓄流露","相与：相互。"],translation:"看老人用来含蓄表露心意的举动，全是圣贤之间互相劝诫、警示的道理；"},{text:"而世不察，以为鬼物，亦已过矣。",annotations:["察：明白","过：错误。"],translation:"世人不明白其中深意，把老人当成鬼怪，实在是错了。"},{text:"且其意不在书。",annotations:[],translation:"况且老人真正用意，并不只在于传授兵书。"},{text:"当韩之亡，秦之方盛也，以刀锯鼎镬待天下之士。",annotations:["方盛：正强盛","刀锯鼎镬(huò)：酷刑，代指残暴杀戮。"],translation:"韩国灭亡、秦国正强盛之时，秦王用各种酷刑对待天下有才之士。"},{text:"其平居无罪夷灭者，不可胜数。",annotations:["平居：平日居家","夷灭：灭族","胜数：数尽。"],translation:"许多百姓平日毫无罪过却遭灭族，多得数不清。"},{text:"虽有贲、育，无所复施。",annotations:["贲(bēn)、育：孟贲、夏育，古代著名勇士","施：施展勇力。"],translation:"就算有孟贲、夏育那样的勇力，也无处施展。"},{text:"夫持法太急者，其锋不可犯，而其势未可乘。",annotations:["持法太急：执法严苛暴虐","锋：锋芒、威势","乘：趁机发难。"],translation:"执法过于严苛暴虐的政权，它的锋芒威势不可触犯，也找不到可乘之机。"},{text:"子房不忍忿忿之心，以匹夫之力而逞于一击之间；",annotations:["忿忿：愤恨","一击：张良博浪沙刺杀秦始皇。"],translation:"张良按捺不住心中愤恨，凭着普通人的一己之力，想要靠一次刺杀泄愤；"},{text:"当此之时，子房之不死者，其间不能容发，盖亦已危矣。",annotations:["间不能容发：间隙容不下一根头发，形容万分危险。"],translation:"在那个时刻，张良能不死，简直是千钧一发，处境危险到极点。"},{text:"千金之子，不死于盗贼，何者？",annotations:["千金之子：富贵人家子弟。"],translation:"富贵人家的子弟，不会死在和盗贼搏斗上，为什么？"},{text:"其身之可爱，而盗贼之不足以死也。",annotations:["可爱：值得珍惜","不足以死：不值得为盗贼送死。"],translation:"他的性命值得珍惜，不值得为盗贼丢掉性命。"},{text:"子房以盖世之才，不为伊尹、太公之谋，而特出于荆轲、聂政之计，以侥幸于不死，此圯上老人所为深惜者也。",annotations:["盖世：冠绝当世","伊尹、太公：古代贤臣，以智谋安天下","特：只","荆轲、聂政：刺客","为：替、对。"],translation:"张良拥有冠绝天下的才能，不去效仿伊尹、姜太公安邦定国的谋略，反倒只采用荆轲、聂政行刺的下策，侥幸才没有死去，这正是桥上老人深深惋惜的地方。"},{text:"是故倨傲鲜腆而深折之。",annotations:["倨傲鲜腆(xiǎn tiǎn)：傲慢无礼、毫不客气","折：挫磨、羞辱，磨炼他的忍性。"],translation:"所以老人故意傲慢无礼，狠狠挫磨他少年刚锐的心性。"},{text:'彼其能有所忍也，然后可以就大事，故曰："孺子可教也。"',annotations:["孺子：年轻人","就：成就。"],translation:"他能忍受这种屈辱，之后才能够成就大事业，所以老人说：这年轻人值得教导。"},{text:"楚庄王伐郑，郑伯肉袒牵羊以逆；",annotations:["肉袒：脱去上衣露肩，表示请罪","逆：迎接、请降。"],translation:"楚庄王攻打郑国，郑襄公脱去上衣、牵着羊出城请降；"},{text:'庄王曰："其君能下人，必能信用其民矣。"遂舍之。',annotations:["下人：放下身段谦卑待人","舍之：放弃灭掉郑国。"],translation:"楚庄王说：一国君主能屈己待人，一定能获得百姓信任拥护。于是放弃灭郑。"},{text:"勾践之困于会稽，而归臣妾于吴者，三年而不倦。",annotations:["困于会稽：被动，被困会稽山","归臣妾：自称吴国臣仆、献上妻妾侍奉吴王。"],translation:"勾践被困会稽山，向吴国称臣，君臣妻妾都去吴国做奴仆，三年不曾倦怠屈服。"},{text:"且夫有报人之志，而不能下人者，是匹夫之刚也。",annotations:["报人：报仇","下人：屈身忍让","匹夫之刚：普通人的小刚强，逞一时血气。"],translation:"心中有报仇大志，却不能屈己忍让，这只是普通人逞一时血气的刚强。"},{text:"夫老人者，以为子房才有余，而忧其度量之不足，故深折其少年刚锐之气，使之忍小忿而就大谋。",annotations:["度量：胸襟气量","忿：愤恨。"],translation:"那位桥上老人，知道张良才能出众，却担忧他胸襟气量不足，所以狠狠挫掉他少年刚锐的脾气，让他忍住小的愤恨，成就长远大计。"},{text:"何则？非有生平之素，卒然相遇于草野之间，而命以仆妾之役，油然而不怪者，此固秦皇之所不能惊，而项籍之所不能怒也。",annotations:["素：旧交情","仆妾之役：让张良捡鞋这类奴仆般差事","油然：平和坦然","固：本来。"],translation:"为什么这么说？两人素不相识，在乡野间突然相遇，老人让他做奴仆般的琐事，他却坦然不怪罪，这份隐忍，本就是秦始皇的威势不能惊扰、项羽的暴怒无法激怒的定力。"},{text:"观夫高祖之所以胜，而项籍之所以败者，在能忍与不能忍之间而已矣。",annotations:[],translation:"看汉高祖取胜、项羽失败的原因，只在于能忍耐和不能忍耐的区别罢了。"},{text:"项籍唯不能忍，是以百战百胜而轻用其锋；",annotations:["锋：锐气、兵力。"],translation:"项羽只因不能忍耐，所以就算百战百胜，也轻易耗尽自己的锐气兵力；"},{text:"高祖忍之，养其全锋而待其弊，此子房教之也。",annotations:["弊：疲敝、衰败。"],translation:"刘邦懂得忍耐，保全全部锐气等待对方衰败，这是张良教他的。"},{text:"当淮阴破齐而欲自王，高祖发怒，见于词色。",annotations:["淮阴：淮阴侯韩信","自王(wàng)：自立齐王",'见：通"现"，显露。'],translation:"当年韩信平定齐地，想要自立齐王，刘邦大怒，怒火从言语神色上表露出来。"},{text:"由此观之，犹有刚强不忍之气，非子房其谁全之？",annotations:["全之：保全他，劝阻他、助他克制怒火。"],translation:"从这件事能看出，刘邦原本也有刚烈不能忍的脾气，如果不是张良，谁能保全他、克制他的冲动？"},{text:"太史公疑子房以为魁梧奇伟，而其状貌乃如妇人女子，不称其志气。",annotations:["太史公：司马迁","魁梧奇伟：高大威猛","称(chèn)：匹配、相称。"],translation:"司马迁原本猜想张良一定高大威猛，可他的样貌竟像柔弱女子，和他的胸襟志气看上去不相称。"},{text:"呜呼！此其所以为子房欤！",annotations:[],translation:"唉！这恰恰就是张良之所以为张良的过人之处啊！"}]},24:{id:"24",title:"传是楼记",source:"汪琬",paragraphs:[{text:"昆山徐健庵先生，筑楼于所居之后，凡七楹。",annotations:["徐健庵：徐乾学，字原一，号健庵","楹：房屋一间为一楹","状语后置，于所居之后筑楼。"],translation:"昆山人徐健庵先生，在自家住宅后方建造一座藏书楼，一共七间。"},{text:"间命工斫木为橱，贮书若干万卷，区为经史子集四种。",annotations:["斫(zhuó)：砍伐、加工木材","区：划分分类","经史子集：古籍四部分类法。"],translation:"时常吩咐工匠伐木制作书橱，收藏书籍数万卷，把书划分为经、史、子、集四大类。"},{text:"经则传注义疏之书附焉，",annotations:["传注、义疏：解释儒家经书的各类注解著作","附：附藏在经部。"],translation:"经部之内，附带收藏各类对经书作传、作注、释义、疏解的典籍；"},{text:"史则日录、家乘、山经、野史之书附焉，",annotations:["日录：每日记录史料","家乘：家谱","山经：地理方志","野史：私人记载杂史。"],translation:"史部附带收藏日记史料、家谱、地理志、民间野史；"},{text:"子则附以卜筮、医药之书，",annotations:["卜筮：占卜算卦类典籍。"],translation:"子部附带收藏占卜、医药类书籍；"},{text:"集则附以乐府、诗余之书。",annotations:["乐府：乐府诗集","诗余：词集。"],translation:"集部附带收录乐府诗集、词集。"},{text:"凡为橱者七十有二，部居类汇，各以其次，素标缃帙，启钥灿然。",annotations:['有：通"又"',"部居类汇：按部归类集中摆放","素标：白色书签","缃(xiāng)帙：浅黄色书套","灿然：光彩整齐。"],translation:"一共做了七十二个书橱，按门类归类集中，各有次序，白色书签、浅黄书套整齐分明，打开锁一看满目整齐灿烂。"},{text:'于是先生召诸子登斯楼而诏之曰："吾何以传女曹哉？',annotations:["诸子：众子弟","诏：告诫",'女：通"汝"',"女曹：你们这些晚辈。"],translation:"于是先生召集一众子弟登上这座楼，告诫他们说：我拿什么传给你们呢？"},{text:"吾徐先世，故以清白起家，吾耳目濡染旧矣。",annotations:["先世：先祖","故：本来","濡染：耳濡目染","旧：长久以来。"],translation:"我们徐家先祖，本来靠清白品行起家，我从小耳濡目染早已熟知家风。"},{text:"盖尝慨夫为人之父祖者，每欲传其土田货财，而子孙未必能世富也；",annotations:["慨：感慨","货财：财物","世富：世代保有富足。"],translation:"我常常感慨世间做父辈祖辈的人，总想把田地财物传给后代，但子孙未必能世代守住富足；"},{text:"欲传其金玉珍玩、鼎彝尊斝之物，而又未必能世宝也；",annotations:["鼎彝(yí)尊斝(jiǎ)：各类青铜礼器古玩","宝：意动，珍藏爱惜。"],translation:"想传给后代金玉古玩、青铜礼器，后代也未必能世代爱惜珍藏；"},{text:"欲传其园池台榭、舞歌舆马之具，而又未必能世享其娱乐也。",annotations:[],translation:"想把园林楼台、歌舞车马享乐之物传给子孙，子孙也未必能长久享受这份安乐。"},{text:'吾方以此为鉴，然则吾何以传女曹哉？"',annotations:["鉴：借鉴、教训","然则：既然这样那么。"],translation:"我把这些当作前车之鉴，既然如此，我该拿什么传给你们？"},{text:'因指书而欣然笑曰："所传者惟是矣！"',annotations:["是：代词，指书籍。"],translation:"于是指着满架书籍欣然笑道：我要传给你们的，只有这些书！"},{text:'遂名其楼为"传是"，而问记于琬。',annotations:["名：名作动，命名","问记于琬：状语后置，向我求一篇记文。"],translation:'于是给这座楼取名"传是楼"，并嘱托我汪琬写一篇楼记。'},{text:"琬衰病不及为，则先生屡书督之，最后复于先生曰：",annotations:["衰病：年老体弱多病","屡书：多次写信","复：回信答复。"],translation:"我年老多病迟迟没能动笔，先生多次写信催促我，最后我回信答复先生说："},{text:"甚矣，书之多厄也！",annotations:["厄：灾祸、损毁流失","主谓倒装，书之多厄甚矣。"],translation:"书籍遭受的灾祸实在太多了！"},{text:"由汉氏以来，人主往往重官赏以购之，",annotations:["人主：帝王","重官赏：拿出高官厚禄","购：征集、收购典籍。"],translation:"从汉代以来，帝王常常拿出高官厚禄来征集天下典籍；"},{text:"其下名公贵卿，又往往厚金帛以易之；",annotations:["厚金帛：丰厚金银绸缎","易：交换收购。"],translation:"朝中名臣权贵，也常常花费重金收购书籍；"},{text:"或亲操翰墨，及分命笔吏以缮录之。",annotations:["翰墨：笔墨","笔吏：抄写文书的小吏","缮录：誊写抄录。"],translation:"有的帝王亲自执笔抄写，也分派文吏誊录典籍。"},{text:"然且裒聚未几，而辄至于散佚，以是知藏书之难也。",annotations:["裒(póu)聚：搜集汇聚","未几：没多久","辄：就","散佚：散失亡佚。"],translation:"可是往往搜集收藏没多长时间，典籍就散失损毁，由此可知藏书十分艰难。"},{text:"琬顾谓藏之之难不若守之之难，守之之难不若读之之难，尤不若躬体而心得之之难。",annotations:["顾：反而","躬体：亲身实践体会","心得：内心真正领悟。"],translation:"我反而认为：藏书难，不如守住藏书难；守住藏书难，又不如认真读书难；读书更难不过亲身实践、内心真正领悟书中道理。"},{text:"是故藏而勿守，犹勿藏也；守而弗读，犹勿守也。",annotations:[],translation:"所以只藏书却不守护，等于没有藏书；只守护藏书却不研读，等于没有守住。"},{text:"夫既已读之矣，而或口与躬违，心与迹忤，采其华而忘其实，",annotations:["躬：自身行为","迹：行事","忤：相悖","华：华丽辞藻","实：书中义理、实用之道。"],translation:"就算已经读过书，可有的人嘴上说一套、行为另一样，内心所想与所作所为相悖，只摘取华丽文辞，却遗忘书中根本义理；"},{text:"是则呻占记诵之学所为哗众而窃名者也，与弗读奚以异哉？",annotations:["呻占(zhān)：诵读死记","哗众：博取众人眼球","窃名：盗取名声","奚以异：有什么区别。"],translation:"这种只会死记硬背、卖弄文字哗众取宠盗取名声的读书，和不读书又有什么两样？"},{text:"古之善读书者，始乎博，终乎约。",annotations:["博：博览群书","约：提纲挈领，把握核心要义。"],translation:"古代善于读书的人，从博览群书起步，最终归于精炼把握要义。"},{text:"博之而非夸多斗靡也，约之而非保残安陋也。",annotations:["夸多斗靡：夸耀读书多、攀比辞藻华丽","保残安陋：固守残缺浅陋的见识不求精进。"],translation:"博览群书不是为了夸耀学识、攀比浮华；提纲挈领也不是固守浅陋残缺的见解、不求深造。"},{text:"善读书者，根柢于性命而究极于事功，",annotations:["根柢(dǐ)：扎根、立足","性命：人性天理","事功：治国济世的实际功业。"],translation:"真正会读书的人，以天理人性为根本，又深究济世立业的实用功业；"},{text:"沿流以溯源，无不探也；明体以适用，无不达也。",annotations:["沿流溯源：顺着支流追溯本源","体：根本义理","用：现实应用","达：通达贯通。"],translation:"顺着典籍支流追溯思想本源，没有不深入探究的；明白根本道理又能运用于现实，处处通达无碍。"},{text:"尊所闻，行所知，非善读书者而能如是乎？",annotations:[],translation:"尊重书中所学、践行所知道理，如果不是真正善读书的人，能做到这样吗？"},{text:"今健庵先生既出其所得于书者，上为天子之所器重，次为中朝士大夫之所矜式，",annotations:["出其所得：把书中所学施展出来","为……所：被动句式","矜式：敬仰、效法的楷模。"],translation:"如今徐健庵先生把从书中习得的学识施展出来，上被天子器重，其次被朝中百官敬仰效法；"},{text:"藉是以润色大业，对扬休命，有余矣。",annotations:["藉是：凭借读书学识","润色大业：辅佐美化国家大业","对扬休命：称颂、践行帝王美善诏命。"],translation:"凭借学识辅佐朝廷大业，承接帝王美善政令，绰绰有余。"},{text:"而又推之以训敕其子姓，俾后先跻巍科、取膴仕，翕然有名于当世，",annotations:["训敕：教诲告诫","俾：使","跻巍科：登上高科、科举高中","膴(wǔ)仕：高官厚禄","翕(xī)然：接连、一同。"],translation:"又把读书之道推广，教诲自家子弟，让后辈接连科举高中、身居高官，在当世全都享有美名；"},{text:"琬然后喟焉太息，以为读书之益弘矣哉！",annotations:["喟焉太息：长叹","弘：宏大深远。"],translation:"我见此情景不禁长叹，读书带来的益处实在宏大深远啊！"},{text:"循是道也，虽传诸子孙世世，何不可之有？",annotations:["循：遵循","是道：这条读书修身立业之道","何不可之有：宾语前置，有什么不可以。"],translation:"如果遵循这条读书正道，就算把藏书与治学之道代代传给子孙，又有什么行不通的呢？"},{text:"若琬则无以与于此矣。",annotations:["无以与于此：没办法达到这种境界。"],translation:"至于我汪琬，是达不到这种境界的。"},{text:"居平质驽才下，患于有书而不能读。",annotations:["居平：平日","质驽：资质愚钝。"],translation:"我平日资质愚钝，就算有书也不能好好研读。"},{text:"延及暮年，则又跧伏穷山僻壤之中，耳目固陋，旧学消亡，",annotations:["跧(quán)伏：蜷曲隐居","固陋：闭塞浅陋","旧学：往日所学学问。"],translation:"到了晚年，又隐居在偏僻山野，见闻闭塞浅陋，往日所学也渐渐荒废；"},{text:"盖本不足以记斯楼。",annotations:["本：本来","不足以：不配。"],translation:"我本来不配为这座传是楼写记。"},{text:"不得已勉承先生之命，姑为一言复之，先生亦恕其老悖否耶？",annotations:["姑：姑且","一言：一篇文字","老悖：年老糊涂。"],translation:"不得已勉强承接先生嘱托，姑且写下这篇文字回复您，还望先生宽恕我年老糊涂吧？"}]},25:{id:"25",title:"小翠",source:"蒲松龄《聊斋志异》",paragraphs:[{text:"王太常，越人。",annotations:["太常：太常寺官职","越：浙江古越地。"],translation:"王太常是浙江人。"},{text:"总角时，昼卧榻上。",annotations:["总角：童年。"],translation:"他小时候，白天躺在床榻上休息。"},{text:"忽阴晦，巨霆暴作，一物大于猫，来伏身下，展转不离。",annotations:["巨霆：惊雷","展转：辗转，不肯离开。"],translation:"忽然天色昏暗，惊雷大作，一只比猫大的动物跑来趴在他身下，辗转不肯离开。"},{text:"移时晴霁，物即径出。",annotations:["移时：过了一会儿","霁：天晴。"],translation:"过了一会儿雨过天晴，那东西径直跑出去了。"},{text:"视之，非猫，始怖，隔房呼兄。",annotations:[],translation:"他仔细一看，不是猫，才感到害怕，隔着屋子呼喊兄长。"},{text:'兄闻，喜曰："弟必大贵，此狐来避雷霆劫也。"',annotations:["雷霆劫：狐狸遭天雷劫难，借人庇护。"],translation:"兄长听说后高兴地说：弟弟将来必定大富大贵，这是狐狸来躲避天雷劫难。"},{text:"后果少年登进士，以县令入为侍御。",annotations:["登进士：考中进士","侍御：御史。"],translation:"后来他果然年纪轻轻考中进士，从县令升任御史。"},{text:"生一子，名元丰，绝痴，十六岁不能知牝牡，因而乡党无与为婚。",annotations:["绝痴：极度痴呆","牝牡：男女","乡党：同乡邻里。"],translation:"他生了一个儿子叫元丰，十分痴呆，十六岁还分不清男女，同乡没人愿意把女儿嫁给他。"},{text:"王忧之。",annotations:[],translation:"王太常十分为此忧愁。"},{text:"适有妇人率少女登门，自请为妇。",annotations:["适：恰好","登门：上门。"],translation:"恰好有一位妇人带着少女上门，主动提出把女儿许配给元丰做媳妇。"},{text:"视其女，嫣然展笑，真仙品也。",annotations:["嫣然：笑容娇美","仙品：仙女一般的容貌。"],translation:"看那少女，笑起来娇美动人，真是仙女一样的容貌。"},{text:'喜问姓名。自言："虞氏。女小翠，年二八矣。"',annotations:["二八：十六岁。"],translation:"王太常欢喜地询问母女姓名。妇人自称姓虞，女儿名叫小翠，今年十六岁。"},{text:'与议聘金。曰："是从我糠覈不得饱，一旦置身广厦，役婢仆，厌膏粱，彼意适，我愿慰矣，岂卖菜也而索直乎！"',annotations:["糠覈(hé)：粗劣粗粮","广厦：高大宅院","厌膏粱：饱食精美肉食",'直：通"值"，价钱。'],translation:"王太常和她商议聘礼。妇人说：这孩子跟着我连粗粮都吃不饱，如今住进大宅院里，使唤婢女仆人，天天吃美食，她心里舒心，我的心愿也就满足了，我又不是卖菜，哪里会索要钱财！"},{text:"夫人大悦，优厚之。",annotations:[],translation:"王夫人十分欢喜，优厚款待母女二人。"},{text:'妇即命女拜王及夫人，嘱曰："此尔翁姑，奉侍宜谨。我大忙，且去，三数日当复来。"',annotations:["翁姑：公婆","谨：恭敬谨慎。"],translation:"妇人当即叫小翠拜见王太常与夫人，叮嘱她说：这是你的公婆，侍奉一定要恭敬谨慎。我事务繁多，暂且先走，三五天就再来。"},{text:'王命仆马送之。妇言："里巷不远，无烦多事。"遂出门去。',annotations:[],translation:"王太常吩咐仆人备马送她。妇人说：住得不远，不必麻烦。说完就出门离开了。"},{text:"小翠殊不悲恋，便即奁中翻取花样。夫人亦爱乐之。",annotations:["奁(lián)：梳妆匣子","殊：完全。"],translation:"小翠一点也不悲伤留恋母亲，立刻在梳妆匣里翻找刺绣花样。王夫人也十分喜爱她。"},{text:"数日，妇不至。以居里问女，女亦憨然不能言其道路，遂治别院，使夫妇成礼。",annotations:["憨然：懵懂天真","治别院：收拾偏院","成礼：成婚。"],translation:"过了好几天，那妇人没有再来。夫人问小翠家住哪里，小翠懵懂说不出路线，于是王家收拾偏院，让元丰和小翠成婚。"},{text:"诸戚闻拾得贫家儿作新妇，共笑姗之；见女皆惊，群议始息。",annotations:["戚：亲戚","笑姗(shān)：嘲笑。"],translation:"各位亲戚听说王家捡了个穷人家女孩做儿媳，全都嘲笑；可见到小翠容貌后都大吃一惊，流言才平息。"},{text:"女又甚慧，能窥翁姑喜怒。王公夫妇，宠惜过于常情，然惕惕焉，惟恐其憎子痴；而女殊欢笑，不为嫌。",annotations:["慧：聪慧","惕惕：忧心","嫌：嫌弃。"],translation:"小翠又十分聪慧，能察看出公婆的喜怒。王太常夫妇疼爱她远超常人，却一直忧心她会嫌弃儿子痴呆；可小翠终日欢笑，一点也不嫌弃元丰。"},{text:"第善谑，刺布作圆，蹋蹴为笑。",annotations:["第：只是","谑：嬉戏玩笑","蹋蹴：踢球。"],translation:"只是她十分爱玩耍，用布缝制圆球，踢来踢去取乐。"},{text:"着小皮靴，蹴去数十步，绐公子奔拾之，公子及婢恒流汗相属。",annotations:["绐(dài)：哄骗","相属：接连不断。"],translation:"她穿着小皮靴，把球踢出去几十步远，哄元丰跑去捡，元丰和婢女常常跑来跑去满身大汗。"},{text:"一日，王偶过，圆訇然来，直中面目。女与婢俱敛迹去，公子犹踊跃奔逐之。",annotations:["訇(hōng)：撞击巨响","敛迹：悄悄躲开。"],translation:"一天，王太常偶然路过，布球轰然飞来，正中他脸上。小翠和婢女连忙躲开，元丰还蹦跳着追球。"},{text:"王怒，投之以石，始伏而啼。",annotations:[],translation:"王太常大怒，捡起石子扔元丰，元丰才趴在地上哭泣。"},{text:"王以告夫人，夫人往责女，女俯首微笑，以手刓床。",annotations:["刓(wán)：用手指划床沿，满不在乎。"],translation:"王太常把这事告诉夫人，夫人去责备小翠，小翠低头微笑，只用手指划着床沿，毫不在意。"},{text:"既退，憨跳如故，以脂粉涂公子，作花面如鬼。",annotations:[],translation:"夫人走后，她依旧天真蹦跳，拿脂粉给元丰涂脸，画得花花绿绿像鬼怪。"},{text:"夫人见之，怒甚，呼女垢骂。女倚几弄带，不惧，亦不言。",annotations:["垢骂：痛骂","几：桌案。"],translation:"夫人看见后怒火冲天，叫来小翠痛骂。小翠靠着桌案把玩衣带，一点不害怕，也不辩解。"},{text:"夫人无奈之，因杖其子。元丰大号，女始色变，屈膝乞宥。",annotations:["杖：名作动，用棍子打","宥：宽恕。"],translation:"夫人拿她没办法，就拿棍子打元丰。元丰放声大哭，小翠才变了神色，跪下请求夫人宽恕。"},{text:"夫人怒顿解，释杖去。",annotations:[],translation:"夫人怒火顿时消散，放下棍子离开了。"},{text:"女笑拉公子入室，代扑衣上尘，拭眼泪，摩挲杖痕，饵以枣栗。公子乃收涕以忻。",annotations:["摩挲：轻轻抚摸","饵：喂","忻：开心。"],translation:"小翠笑着拉元丰进屋，替他拍掉衣服灰尘，擦去眼泪，轻轻抚摸被棍子打出来的伤痕，拿枣子栗子给他吃。元丰才止住眼泪开心起来。"},{text:"女阖庭户，复装公子作霸王，作沙漠人；己乃艳服，束细腰，婆娑作帐下舞；或髻插雉尾，拨琵琶，丁丁缕缕然，喧笑一室，日以为常。",annotations:["阖：关上","婆娑：轻盈起舞","丁丁缕缕：琵琶清脆连绵的乐声。"],translation:"小翠关上院门，又装扮元丰扮项羽、塞外胡人；自己穿上艳丽衣裙，束紧细腰，像军帐舞姬一样起舞；有时发髻插上野鸡尾羽，弹起琵琶，乐声清脆连绵，满屋嬉笑打闹，天天如此。"},{text:"王公以子痴，不忍过责妇；即微闻焉，亦若置之。",annotations:["微闻：隐约听说","置之：放下不管。"],translation:"王太常因为儿子痴呆，不忍心严厉责备儿媳；就算隐约听说二人嬉闹，也只当没看见。"},{text:"同巷有王给谏者，相隔十余户，然素不相能。",annotations:["给谏：官职","不相能：素来不和、互相敌视。"],translation:"同巷住着一位王给谏，两家相隔十几户，两人素来水火不容。"},{text:"时值三年大计吏，忌公握河南道篆，思中伤之。",annotations:["大计吏：朝廷三年一次官员考核","篆：官印，代职权","中伤：陷害。"],translation:"恰逢朝廷三年一次官员大考核，王给谏忌惮王太常手握河南道监察大权，想要陷害他。"},{text:"公知其谋，忧虑无所为计。",annotations:[],translation:"王太常知道他的阴谋，满心忧虑无计可施。"},{text:'一夕，早寝。女冠带，饰冢宰状，剪素丝作浓髭，又以青衣饰两婢为虞候，窃跨厩马而出，戏云："将谒王先生。"',annotations:["冢宰：宰相","虞候：高官随从侍卫","厩马：家中马厩马匹。"],translation:"一天晚上，王太常早早休息。小翠穿戴官帽官服，装扮成宰相模样，剪下白丝做成浓密胡须，又让两个婢女穿上青衣扮作侍卫，偷偷骑上马出门，开玩笑说：我要去拜见王给谏。"},{text:'驰至给谏之门，即又鞭挝从人，大言曰："我谒侍御王，宁谒给谏王耶！"回辔而归。',annotations:["挝：鞭打","辔：马缰绳。"],translation:"骑马冲到王给谏家门口，又假意鞭打随从，大声说：我是来拜见御史王大人，哪里是拜见给谏王大人！说完调转马头回家。"},{text:"比至家门，门者误以为真，奔白王公。公急起承迎，方知为子妇之戏。",annotations:["比：等到","白：禀报","承迎：出门迎接。"],translation:"等她回到自家门口，守门仆人当真以为宰相到访，连忙跑去禀报王太常。王太常慌忙起身出门迎接，才知道是儿媳恶作剧。"},{text:'怒甚，谓夫人曰："人方蹈我之瑕，反以闺阁之丑，登门而告之。余祸不远矣！"',annotations:["蹈我之瑕：抓住我的把柄","闺阁之丑：家中荒唐闹剧。"],translation:"王太常大怒，对夫人说：那人正想方设法抓我的把柄，她反倒把家中荒唐事闹到对方门前，我的灾祸快要来了！"},{text:"夫人怒，奔女室，诟让之。女惟憨笑，并不一置词。",annotations:["诟让：斥责","置词：辩解一句。"],translation:"夫人怒气冲冲跑到小翠房中斥责她。小翠只是天真傻笑，一句辩解的话也不说。"},{text:"挞之，不忍；出之，则无家：夫妻懊怨，终夜不寝。",annotations:["挞：鞭打","出之：休弃她","懊怨：烦闷懊恼。"],translation:"想打她，又于心不忍；想把她赶走，她又无家可归：夫妻二人烦闷懊恼，整夜无法入睡。"},{text:"时冢宰某公赫甚，其仪采服从，与女伪装无少殊别，王给谏亦误为真。",annotations:["赫：权势显赫","无少殊别：没有一点差别。"],translation:"当时那位宰相权势极大，他的仪容服饰，和小翠装扮出来的一模一样，王给谏竟当真以为宰相到访。"},{text:"屡侦公门，中夜而客未出，疑冢宰与公有阴谋。",annotations:["侦：打探","中夜：半夜。"],translation:"他多次派人打探王家动静，半夜看见客人迟迟不离开，怀疑宰相和王太常私下勾结谋划。"},{text:'次日早朝，见而问曰："夜，相公至君家耶？"公疑其相讥，惭言唯唯，不甚响答。',annotations:["相公：宰相","唯唯：含糊应付。"],translation:"第二天早朝，王给谏见到王太常问道：昨夜宰相到你家去了？王太常以为他在讥讽自己，羞愧地含糊应付，不敢大声答话。"},{text:"给谏愈疑，谋遂寝，由此益交欢公。",annotations:["寝：搁置、作罢","交欢：刻意交好。"],translation:"王给谏疑心更重，陷害王太常的计划就此搁置，从此反而主动和王太常交好。"},{text:"公探知其情，窃喜，而阴嘱夫人，劝女改行；女笑应之。",annotations:["探知：打探清楚","阴：私下","改行：收敛嬉闹行为。"],translation:"王太常打探清楚前因后果，暗自欣喜，私下嘱咐夫人劝小翠收敛贪玩性子，小翠笑着答应。"},{text:"逾岁，首相免，适有以私函致公者，误投给谏。",annotations:["逾岁：过了一年","致：寄给。"],translation:"过了一年，当朝宰相被罢免，恰好有人给王太常寄私信，错投到王给谏家中。"},{text:"给谏大喜，先托善公者往假万金，公拒之。",annotations:["善公：和王太常交好的人","假：借。"],translation:"王给谏大喜，先托和王太常交好的人上门借一万两白银，王太常拒绝了。"},{text:"给谏自诣公所。公觅巾袍，并不可得；给谏伺候久，怒公慢，愤将行。",annotations:["诣：登门","觅：寻找","慢：怠慢。"],translation:"王给谏亲自登门拜访。王太常慌忙找官帽官袍，却一件都找不到；王给谏等候许久，恼怒王太常怠慢自己，愤懑准备离开。"},{text:"忽见公子衮衣旒冕，有女子自门内推之以出，大骇。",annotations:["衮衣旒冕：帝王龙袍皇冠。"],translation:"忽然看见元丰穿着帝王的龙袍皇冠，一个女子从门里把他推了出来，王给谏大吃一惊。"},{text:"已而笑抚之，脱其服冕而去。公急出，则客去远。",annotations:[],translation:"随后小翠笑着安抚元丰，脱下他身上的皇冠龙袍。王太常急忙出门，王给谏已经走远。"},{text:'闻其故，惊颜如土，大哭曰，"此祸水也！指日赤吾族矣！"',annotations:["惊颜如土：脸色惨白","赤吾族：灭我全族。"],translation:"听完事情经过，王太常吓得面如土色，大哭道：这是惹祸的灾星！用不了多久就要连累全家灭门！"},{text:"与夫人操杖往。女已知之，阖扉任其诟厉。",annotations:["操杖：拿棍棒","阖扉：关上门","诟厉：痛骂斥责。"],translation:"他和夫人拿着棍棒前往小翠房中。小翠早已知道，关上房门任凭二人痛骂。"},{text:'公怒，斧其门。女在内，含笑而告之曰："翁无烦怒。有新妇在，刀锯斧钺，妇自受之，必不令贻害双亲。翁若此，是欲杀妇以灭口耶？"',annotations:["斧：名作动，拿斧子劈门","贻害：连累祸害。"],translation:"王太常怒火冲天，拿斧子劈房门。小翠在屋内含笑说道：公公不必动怒。有我在，所有刑罚罪责我一人承担，绝不会连累二老。您这般动怒，难道是想杀我灭口吗？"},{text:"公乃止。",annotations:[],translation:"王太常这才停下。"},{text:"给谏归，果抗疏揭王不轨，衮冕作据。",annotations:["抗疏：上奏弹劾","不轨：图谋造反","据：证据。"],translation:"王给谏回家后，果然上奏弹劾王太常图谋造反，拿元丰穿龙袍一事作为证据。"},{text:"上惊验之，其旒冕乃粱秸心所制，袍则败布黄袱也。",annotations:["粱秸：高粱秆","败布黄袱：破旧黄布包袱。"],translation:"皇帝震惊，派人查验物证，皇冠是高粱秆芯做的，龙袍只是破旧黄布包袱。"},{text:'上怒其诬。又召元丰至，见其憨状可掬，笑曰："此可以作天子耶？"',annotations:["诬：诬告","憨状可掬：一副痴呆模样。"],translation:"皇帝怒斥王给谏诬告。又召元丰上殿，看见他一副痴傻模样，笑着说：这样的人怎么可能图谋做天子？"},{text:"乃下之法司。给谏又讼公家有妖人，法司严诘臧获，并言无他，惟颠妇痴儿，日事戏笑；邻里亦无异词。",annotations:["法司：司法衙门","臧获：家中奴仆","颠妇：疯癫女子，指小翠。"],translation:"于是把王给谏交给司法官审问。王给谏又控诉王家藏妖人，官府严厉审问王家奴仆，奴仆都说没有怪事，只有疯癫儿媳、痴呆公子终日嬉闹；邻里证词也完全一致。"},{text:"案乃定，以给谏充云南军。王由是奇女。",annotations:["充军：流放","奇：意动，以……为奇，十分看重。"],translation:"案件判定，王给谏被流放云南。王太常从此十分看重小翠。"},{text:"又以母久不至，意其非人。使夫人探诘之，女但笑不言。",annotations:["探诘：试探追问","非人：不是凡人。"],translation:"又因为小翠母亲许久不来，王太常猜想她不是凡人。让夫人试探追问，小翠只是笑不说话。"},{text:'再复穷问，则掩口曰："儿玉皇女，母不知耶？"',annotations:["穷问：追问到底","玉皇女：玉皇大帝的女儿。"],translation:"夫人再三追问到底，小翠掩口笑道：我是玉皇大帝的女儿，母亲难道不知道吗？"},{text:"无何，公擢京卿。五十余，每患无孙。",annotations:["无何：没过多久","擢：提拔","京卿：京城高官。"],translation:"没过多久，王太常升任京城高官。夫妻五十多岁，常常担忧没有孙辈。"},{text:"女居三年。夜夜与公子异寝，似未尝有所私。",annotations:["异寝：分床睡","私：夫妻亲密同房。"],translation:"小翠嫁入王家三年，每晚都和元丰分床而睡，从来没有夫妻亲密之事。"},{text:"夫人舁榻去，嘱公子与妇同寝。",annotations:["舁(yú)：抬走。"],translation:"夫人让人把小翠的床抬走，嘱咐元丰和小翠同床。"},{text:'过数日，公子告母曰："借榻去，悍不还！小翠夜夜以足股加腹上，喘气不得；又惯掐人股里。"婢妪无不粲然。夫人呵拍令去。',annotations:["股：大腿","粲然：发笑","呵拍：呵斥拍打元丰。"],translation:"过了几天，元丰告诉母亲：床被抬走后她蛮横不肯还给我！小翠每晚把腿压在我肚子上，让我喘不过气，还总掐我大腿内侧。婢女老仆全都发笑。夫人呵斥拍打元丰，让他走开。"},{text:"一日，女浴于室，公子见之，欲与偕；女笑止之，谕使姑侍。",annotations:["偕：一同洗澡","谕：告知","姑侍：先等一等。"],translation:"一天，小翠在室内洗澡，元丰看见想要和她一起洗；小翠笑着制止，叫他在一旁等候。"},{text:"既出，乃更泻热汤于瓮，解其袍袴，与婢扶之入。",annotations:["瓮：大浴桶","袍袴：衣裤。"],translation:"元丰洗完出来后，小翠又往浴桶加满热水，脱下元丰衣裤，和婢女扶他进桶洗澡。"},{text:"公子觉蒸闷，大呼欲出。女不听，以衾蒙之。",annotations:["衾：被子","蒙：盖住。"],translation:"元丰觉得闷热窒息，大喊想要出来。小翠不听，拿被子盖住浴桶。"},{text:"少时，无声，启视，已绝。",annotations:["少时：片刻","绝：昏死过去。"],translation:"片刻后桶内没了动静，掀开被子一看，元丰已经昏死。"},{text:"女坦笑不惊，曳置床上，拭体干洁，加复被焉。",annotations:["坦笑：坦然微笑","曳：拖拽。"],translation:"小翠坦然一笑毫不惊慌，把元丰拖到床上，擦干净身体，盖上厚被子。"},{text:'夫人闻之，哭而入，骂曰："狂婢何杀吾儿！"',annotations:[],translation:"夫人听闻此事哭着冲进房间，骂道：疯丫头为何害死我儿子！"},{text:'女冁然曰："如此痴儿，不如勿有。"',annotations:["冁(chǎn)然：含笑。"],translation:"小翠含笑说：这样痴呆的儿子，不如没有。"},{text:"夫人益恚，以首触女；婢辈争曳劝之。",annotations:["恚：愤怒","触：撞","曳：拉扯分开。"],translation:"夫人更加愤怒，拿头去撞小翠；婢女连忙拉扯劝解二人。"},{text:'方纷噪间，一婢告曰："公子呻矣！"',annotations:["纷噪：吵闹混乱","呻：呻吟。"],translation:"正吵闹不休时，一个婢女禀报：公子发出呻吟声了！"},{text:"夫人辍涕抚之，则气息休休，而大汗浸淫，沾浃裀褥。",annotations:["辍涕：停止哭泣","浸淫：淋漓湿透","裀褥：被褥。"],translation:"夫人止住哭声抚摸元丰，只见他气息舒缓，大汗淋漓，把被褥全都浸湿。"},{text:'食顷，汗已，忽开目四顾，遍视家人，似不相识，曰："我今回忆往昔，都如梦寐，何也？"',annotations:["食顷：一顿饭功夫","梦寐：梦境。"],translation:"一顿饭功夫，汗止住了，元丰忽然睁眼环顾四周，看着全家人仿佛不认识，说：我回想从前的事，全都像一场梦，这是为什么？"},{text:"夫人以其言语不痴，大异之。携参其父，屡试之，果不痴。大喜，如获异宝。",annotations:["异：诧异","参：带去见。"],translation:"夫人见他说话不再痴呆，十分诧异，带他去见王太常，反复试探，元丰果真清醒不痴了。夫妻大喜，如同得到稀世珍宝。"},{text:"至晚，还榻故处，更设衾枕以觇之。公子入室，尽遣婢去。早窥之，则塌虚设。",annotations:["觇：观察","虚设：床上空无一人。"],translation:"到了晚上，夫人把小翠的床放回原处，重新铺好被褥暗中观察。元丰进屋后，把婢女全都支开。清晨偷偷一看，床上空无一人。"},{text:"自此痴颠皆不复作，而琴瑟静好，如形影焉。",annotations:["琴瑟静好：夫妻和睦","形影：形影不离。"],translation:"从此元丰再也不痴呆疯癫，夫妻二人恩爱和睦，形影不离。"},{text:"年余，公为给谏之党奏劾免官，小有罣误。",annotations:["劾：弹劾","罣(guà)误：受牵连获罪。"],translation:"过了一年多，王太常被王给谏的同党弹劾，罢官免职，受了牵连。"},{text:"旧有广西中丞所赠玉瓶，价累千金，将出以贿当路。",annotations:["累千金：价值上千两白银","当路：掌权官员。"],translation:"家中原有广西中丞赠送的玉瓶，价值上千两白银，王太常打算拿它贿赂当权官员。"},{text:"女爱而把玩之，失手堕碎，惭而自投。",annotations:["堕碎：摔碎","自投：主动上前请罪。"],translation:"小翠十分喜爱时常把玩玉瓶，失手将它摔碎，愧疚地上前请罪。"},{text:"公夫妇方以免官不快，闻之，怒，交口呵骂。",annotations:[],translation:"王太常夫妇正因罢官心中烦闷，听说玉瓶打碎，怒火冲天，一同痛骂小翠。"},{text:'女忿而出，谓公子曰："我在汝家，所保全者不止一瓶，何遂不少存面目？',annotations:["忿：愤懑","存面目：留一点情面。"],translation:"小翠愤懑走出房门，对元丰说：我在你家，保全你们全家灾祸无数，不过碎一个瓶子，你们为何一点情面都不留？"},{text:"实与君言：我非人也。以母遭雷霆之劫，深受而翁庇翼；又以我两人有五年夙分，故以我来报曩恩、了夙愿耳。",annotations:["而翁：你的父亲","庇翼：庇护","夙分：前世五年姻缘","曩恩：往日恩情。"],translation:"实话对你说，我不是凡人。当年母亲遭遇天雷劫难，受你父亲庇护；又因我和你有五年前世姻缘，所以我来报答当年恩情、了结前世缘分。"},{text:'身受唾骂，擢发不足以数，所以不即行者，五年之爱未盈。今何可以暂止乎！"',annotations:["擢发：拔光头发都数不清","盈：满。"],translation:"我承受你们无数唾骂羞辱，罪过多得拔光头发都数不完，之所以没有立刻离开，是五年情缘尚未期满。如今还有什么理由留下来！"},{text:"盛气而出，追之已杳。",annotations:["杳：无影无踪。"],translation:"说完怒气冲冲出门，元丰追赶出去，早已不见踪影。"},{text:"公爽然自失，而悔无及矣。",annotations:["爽然自失：茫然失落。"],translation:"王太常茫然失落，后悔已经来不及。"},{text:"公子入室，睹其剩粉遗钩，恸哭欲死；寝食不甘，日就羸瘁。",annotations:["遗钩：遗留首饰","羸瘁：瘦弱憔悴。"],translation:"元丰走进小翠房间，看见她遗留的脂粉首饰，痛哭得几乎寻死；茶饭不思，日渐瘦弱憔悴。"},{text:"公大忧，急为胶续以解之，而公子不乐。",annotations:["胶续：续弦，再娶妻子。"],translation:"王太常十分忧心，急忙打算为元丰再娶，消解他的悲痛，可元丰心中不愿。"},{text:"惟求良工画小翠像，日夜浇祷其下，几二年。",annotations:["浇祷：摆酒祭拜","几：将近。"],translation:"他只请画师画小翠肖像，日夜在画像前摆酒祭拜，这样将近两年。"},{text:"偶以故自他里归，明月已皎，村外有公家亭园，骑马墙外过，闻笑语声，停辔，使厩卒捉鞚；登鞍一望，则二女郎游戏其中。",annotations:["皎：皎洁","鞚：马缰绳。"],translation:"一次元丰有事从外地回乡，月色皎洁，村外自家亭园墙外骑马经过，听见园内女子说笑，停下马，让仆人拉住缰绳，登高望去，两个女子在园中游玩。"},{text:'云月昏蒙，不甚可辨，但闻一翠衣者曰："婢子当逐出门！"一红衣者曰："汝在吾家园亭，反逐阿谁？"',annotations:[],translation:"月色朦胧看不清晰，只听见穿翠色衣衫的女子说：你这丫头该赶出门！红衣女子答道：你在我家亭园，反倒要赶谁？"},{text:'翠衣人曰："婢子不羞，不能作妇，被人驱遣，犹冒认物产也？"红衣者曰："索胜老大婢无主顾者！"',annotations:["索胜：总好过。"],translation:"翠衣女子说：你不知羞耻，做不好媳妇被婆家赶走，还敢说园子是你的？红衣女子说：总好过到老无家可归、没人收留的孤女！"},{text:'听其音，酷类小翠，疾呼之。翠衣人去曰："姑不与若争，汝汉子来矣。"',annotations:["酷类：极像","汉子：指元丰。"],translation:"元丰听声音极像小翠，连忙呼喊她。翠衣女子转身躲开，说：暂且不和你争辩，你的夫君来了。"},{text:"既而红衣人来，果小翠。喜极。",annotations:[],translation:"片刻红衣女子走来，果然是小翠。元丰欣喜到极点。"},{text:'女令登垣，承接而下之，曰："二年不见，骨瘦一把矣！"',annotations:["垣：围墙","承接：伸手拉元丰翻墙下来。"],translation:"小翠让元丰爬上围墙，伸手拉他下来，说：两年不见，你瘦得只剩一把骨头！"},{text:"公子握手泣下，具道相思。",annotations:[],translation:"元丰握住她的手落泪，细细诉说两年思念。"},{text:'女言："妾亦知之，但无颜复见家人。今与大姊游戏，又相邂逅，足知前因不可逃也。"',annotations:["邂逅：偶然相逢","前因：前世缘分。"],translation:"小翠说：我也知道你思念我，只是我无颜再见公婆。今日和姐姐游玩，与你偶遇，可见前世缘分无法躲开。"},{text:"请与同归，不可；请止园中，许之。",annotations:[],translation:"元丰请求小翠一同回家，小翠不肯；请求她留在亭园，小翠答应。"},{text:"公子遣仆奔白夫人。夫人惊起，驾肩舆而往，启钥入亭。",annotations:["肩舆：轿子","启钥：开门。"],translation:"元丰派仆人飞奔禀报夫人。夫人连夜起身，坐轿子赶到亭园，开门进园。"},{text:'女即趋下迎拜；夫人捉臂流涕，力白前过，几不自容，曰："若不少记榛梗，请偕归，慰我迟暮。"',annotations:["榛梗：过往嫌隙","迟暮：晚年。"],translation:"小翠连忙上前跪拜迎接；夫人拉住她手臂流泪，反复诉说从前自己的过错，羞愧无地，说：你若不记往日仇怨，就和我回家，慰藉我晚年。"},{text:"女峻辞不可。",annotations:["峻辞：坚决推辞。"],translation:"小翠坚决推辞不肯回去。"},{text:'夫人虑野亭荒寂，谋以多人服役。女曰："我诸人悉不愿见，惟前两婢朝夕相从，不能无眷注耳；外惟一老仆应门，馀都无所复须。"',annotations:["眷注：挂念","应门：看门。"],translation:"夫人担心荒亭冷清，打算派许多仆人伺候。小翠说：其他人我都不愿相见，只有从前两个朝夕相伴的婢女，我心中挂念；除此之外只留一个老仆看门，其余全都不需要。"},{text:"夫人悉如其言。托公子养疴园中，日供食用而已。",annotations:["悉如其言：全部依她吩咐","养疴：养病。"],translation:"夫人全部照她的话安排，对外只说元丰在园中养病，每日送来衣食。"},{text:"女每劝公子别婚，公子不从。",annotations:[],translation:"小翠时常劝元丰再娶妻子，元丰不肯。"},{text:"后年余，女眉目音声，渐与曩异，出像质之，迥若两人。",annotations:["曩：从前","质：对照画像","迥：完全。"],translation:"过了一年多，小翠容貌声音渐渐和从前不同，元丰拿出画像对照，完全像两个人。"},{text:'大怪之。女曰："视妾今日，何如畴昔美？"公子曰："今日美则美，然较昔日则似不如。"',annotations:["畴昔：往日。"],translation:"元丰十分奇怪。小翠说：你看我现在，和从前比哪个更美？元丰说：如今虽美，但比不上从前。"},{text:'女曰："意妾老矣！"公子曰："二十余岁人，何得速老？"女笑而焚图，救之已烬。',annotations:["烬：烧成灰烬。"],translation:"小翠说：想来我是老了！元丰说：才二十多岁，怎么会衰老这么快？小翠笑着烧毁画像，元丰抢救不及，画像烧成灰烬。"},{text:'一日，谓公子曰："昔在家时，阿翁谓妾抵死不作茧。今亲老君孤，妾实不能产，恐误君宗嗣。请娶妇于家，旦晚侍奉翁姑，君往来于两间，亦无所不便。"',annotations:["不作茧：道家修仙不生凡胎","宗嗣：家族后代。"],translation:"一天，小翠对元丰说：从前在家，我母亲说我至死不会生凡胎子女。如今公婆年老，家中无后，我实在不能生育，怕耽误你传宗接代。你回家另娶妻子，早晚侍奉公婆，你往返两家，也并无不便。"},{text:"公子然之，纳币于锺太史之家。",annotations:["纳币：下聘礼订婚。"],translation:"元丰听从她的话，向锺太史家下聘订婚。"},{text:"吉期将近，女为新人制衣履，赍送母所。",annotations:["吉期：婚期","赍：送去。"],translation:"婚期将近，小翠为新娘缝制衣物鞋袜，托人送到锺家。"},{text:"及新人入门，则言貌举止，与小翠无毫发之异。大奇之。",annotations:[],translation:"等到新娘进门，言谈容貌举止，和小翠分毫不差。元丰十分惊奇。"},{text:"往至园亭，则女已不知所在。",annotations:[],translation:"他赶到亭园，小翠已经不见踪影。"},{text:'问婢，婢出红巾曰："娘子暂归宁，留此贻公子。"',annotations:["归宁：回仙府","贻：赠予。"],translation:"询问婢女，婢女拿出一条红丝巾说：娘子暂时回仙府，留下这个送给公子。"},{text:"展巾，则结玉玦一枚，心知其不返，遂携婢俱归。",annotations:["玉玦：玉器，象征诀别。"],translation:"展开丝巾，里面是一枚玉玦，元丰明白小翠不会再回来，于是带着婢女回家。"},{text:"虽顷刻不忘小翠，幸而对新人如觌旧好焉。",annotations:["觌(dí)：相见。"],translation:"元丰无时无刻不思念小翠，所幸面对新夫人，如同见到旧日心上人。"},{text:"始悟锺氏之姻，女预知之，故先化其貌，以慰他日之思云。",annotations:[],translation:"元丰才醒悟，这门婚事小翠早已预知，所以提前把新娘容貌化成自己的样子，宽慰他日我的思念。"},{text:'异史氏曰："一狐也，以无心之德，而犹思所报；而身受再造之福者，顾失声于破甑，何其鄙哉！',annotations:["异史氏：蒲松龄评论","再造之福：救命再造之恩","失声于破甑：摔碎玉瓶便痛骂小翠","甑：瓦器，代玉瓶。"],translation:"异史氏评论：一只狐狸，偶然受他人恩德，尚且一心报答；而承受小翠再造全家恩德的王家，只因摔碎一只瓶子就破口大骂，何其浅薄鄙俗！"},{text:'月缺重圆，从容而去，始知仙人之情，亦更深于流俗也！"',annotations:["月缺重圆：二人离散重逢","流俗：凡俗世人。"],translation:"二人离散又重逢，小翠最后从容离去，才知仙人的深情，远胜过世间凡夫俗子。"}]}},a=t=>n[t];export{a as g};
